import {GridRowId} from "@mui/x-data-grid";
import {createApi} from '@reduxjs/toolkit/query/react'
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../../api/baseQuery";
import {ICreateDeliveryMethod, IDeliveryMethod} from "../../../models/deliveryMethod";

export const deliveryMethodsApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: 'deliveryMethods',
    tagTypes:['DeliveryMethods'],
    baseQuery: createFirmBaseQuery('deliveryMethods'),
    endpoints: (builder) => ({
        getDeliveryMethods: builder.query<IDeliveryMethod[], void | Record<string, never>>({
            query: () => ({
                url: '',
                method: 'GET'
            }),
            providesTags:['DeliveryMethods']
        }),
        getDeliveryMethodById: builder.query<IDeliveryMethod, string | number>({
            query: (id) => ({
                url: `${id}`,
                method: 'GET'
            }),
        }),
        createDeliveryMethod: builder.mutation<number, ICreateDeliveryMethod>({
            query: (deliveryMethod: ICreateDeliveryMethod) => ({
                url: ``,
                method: 'POST',
                body: deliveryMethod,
            }),
            invalidatesTags:['DeliveryMethods']
        }),
        editDeliveryMethod: builder.mutation<number, IDeliveryMethod>({
            query: (deliveryMethod: IDeliveryMethod) => ({
                url: ``,
                method: 'PUT',
                body: deliveryMethod
            }),
            invalidatesTags:['DeliveryMethods']
        }),
        deleteDeliveryMethod: builder.mutation<number, GridRowId>({
            query: (id: GridRowId) => ({
                url: `${id}`,
                method: 'DELETE'
            }),
            invalidatesTags:['DeliveryMethods']
        }),
    }),
})

export const {
    useGetDeliveryMethodsQuery,
    useGetDeliveryMethodByIdQuery,
    useDeleteDeliveryMethodMutation,
    useCreateDeliveryMethodMutation,
    useEditDeliveryMethodMutation
} = deliveryMethodsApi;
