import React, {
    createContext,
    ReactNode,
    useCallback,
    useContext,
    useEffect,
    useMemo,
    useState,
} from "react";
import {extraDictionaries} from "./extraTranslations";
import {epassDictionaries} from "./epassTranslations";
import {navigationDictionaries} from "./navigationTranslations";
import {productRecognitionDictionaries} from "./productRecognitionTranslations";
import {
    defaultLanguage,
    dictionaries,
    getLanguageOption,
    isSupportedLanguage,
    Language,
    languageOptions,
    Translate,
    TranslationParams,
} from "./translations";

const languageStorageKey = "vivotech.crm.language";

const formatMessage = (message: string, params?: TranslationParams) => {
    if (!params) {
        return message;
    }

    return Object.entries(params).reduce((result, [key, value]) => {
        return result.replace(new RegExp(`\\{${key}\\}`, "g"), String(value ?? ""));
    }, message);
};

const getMessage = (language: Language, key: string) => {
    const dictionary = dictionaries[language];
    const extraDictionary = extraDictionaries[language];
    const fallbackDictionary = dictionaries[defaultLanguage];
    const extraFallbackDictionary = extraDictionaries[defaultLanguage];
    const fallbackMessage = language === "en"
        ? undefined
        : extraFallbackDictionary[key] || fallbackDictionary[key];

    return productRecognitionDictionaries[language][key] || navigationDictionaries[language][key] || epassDictionaries[language][key] ||
        extraDictionary[key] ||
        dictionary[key] ||
        (language !== "en" ? epassDictionaries[defaultLanguage][key] : undefined) ||
        fallbackMessage ||
        key;
};

const getBrowserLanguage = (): Language => {
    if (typeof window === "undefined") {
        return defaultLanguage;
    }

    const storedLanguage = window.localStorage.getItem(languageStorageKey);

    if (isSupportedLanguage(storedLanguage)) {
        return storedLanguage;
    }

    const browserLanguage = window.navigator.language.split("-")[0];

    if (isSupportedLanguage(browserLanguage)) {
        return browserLanguage;
    }

    return defaultLanguage;
};

let activeLanguage: Language = getBrowserLanguage();

export const getCurrentLanguage = () => activeLanguage;

export const setCurrentLanguage = (language: Language) => {
    activeLanguage = language;

    if (typeof window === "undefined") {
        return;
    }

    window.localStorage.setItem(languageStorageKey, language);
    document.documentElement.lang = getLanguageOption(language).htmlLang;
};

export const translate: Translate = (key, params) => {
    const message = getMessage(activeLanguage, key);

    return formatMessage(message, params);
};

interface LanguageContextValue {
    language: Language;
    locale: string;
    languageOptions: typeof languageOptions;
    setLanguage: (language: Language) => void;
    t: Translate;
}

const LanguageContext = createContext<LanguageContextValue | undefined>(undefined);

interface LanguageProviderProps {
    children: ReactNode;
}

export const LanguageProvider = ({children}: LanguageProviderProps) => {
    const [language, setLanguageState] = useState<Language>(() => getCurrentLanguage());

    useEffect(() => {
        setCurrentLanguage(language);
    }, [language]);

    const setLanguage = useCallback((nextLanguage: Language) => {
        setLanguageState(nextLanguage);
    }, []);

    const t = useCallback<Translate>((key, params) => {
        const message = getMessage(language, key);

        return formatMessage(message, params);
    }, [language]);

    const value = useMemo(
        () => ({
            language,
            locale: getLanguageOption(language).locale,
            languageOptions,
            setLanguage,
            t,
        }),
        [language, setLanguage, t],
    );

    return (
        <LanguageContext.Provider value={value}>
            {children}
        </LanguageContext.Provider>
    );
};

export const useTranslation = () => {
    const context = useContext(LanguageContext);

    if (!context) {
        throw new Error("useTranslation must be used inside LanguageProvider");
    }

    return context;
};
