import {retry} from '@reduxjs/toolkit/query/react';
import {createFirmBaseQuery} from '../../api/baseQuery';

// Background reads can fail while the host wakes up or a connection is replaced.
// Retry only reads; sending a message stays under the draft's idempotency key.
export const collaborationBaseQuery = retry(createFirmBaseQuery('collaboration'), {
    retryCondition: (error, args, {attempt, baseQueryApi}) => {
        const method = typeof args === 'string' ? 'GET' : (args.method || 'GET').toUpperCase();
        return method === 'GET' && attempt <= 2 && !baseQueryApi.signal.aborted &&
            (error.status === 'FETCH_ERROR' || error.status === 'TIMEOUT_ERROR' || (typeof error.status === 'number' && error.status >= 500) ||
                (error.status === 'PARSING_ERROR' && error.originalStatus >= 500));
    },
    backoff: async attempt => {await new Promise(resolve => setTimeout(resolve, 300 * 2 ** (attempt - 1)));},
});
