import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {
    CommercialOffer,
    CommercialOfferCustomer,
    CommercialOfferDelivery,
    CommercialOfferEditRequest,
    CommercialOfferProduct,
    CommercialOfferTemplate,
    CommercialOfferTemplateWriteRequest,
} from "../../models/commercialOffer";

interface UpdateCustomerProfileRequest {
    customerId: number;
    email: string;
    taxNumber: string;
    contract: string;
}

interface OfferActionRequest {
    id: string;
    concurrencyStamp: string;
}

export interface ConvertedOrder {
    id: number;
    number: string;
    createdAt: string;
}

export const commercialOffersApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "commercialOffersApi",
    baseQuery: createFirmBaseQuery("commercial-offers"),
    tagTypes: ["CommercialOffers", "CommercialOffer", "CommercialOfferCustomers", "CommercialOfferTemplates"],
    endpoints: (builder) => ({
        getCommercialOffers: builder.query<CommercialOffer[], void>({
            query: () => "",
            providesTags: (result) => [
                {type: "CommercialOffers", id: "LIST"},
                ...(result ?? []).map(({id}) => ({type: "CommercialOffer" as const, id})),
            ],
        }),
        getCommercialOffer: builder.query<CommercialOffer, string>({
            query: (id) => id,
            providesTags: (_result, _error, id) => [{type: "CommercialOffer", id}],
        }),
        getCommercialOfferCustomers: builder.query<CommercialOfferCustomer[], void>({
            query: () => "customers",
            providesTags: [{type: "CommercialOfferCustomers", id: "LIST"}],
        }),
        updateCommercialOfferCustomer: builder.mutation<CommercialOfferCustomer, UpdateCustomerProfileRequest>({
            query: ({customerId, ...body}) => ({
                url: `customers/${customerId}/commercial-profile`,
                method: "PUT",
                body,
            }),
            invalidatesTags: [{type: "CommercialOfferCustomers", id: "LIST"}],
        }),
        getCommercialOfferProducts: builder.query<CommercialOfferProduct[], {customerId: number; includeUnavailable?: boolean}>({
            query: ({customerId, includeUnavailable = true}) => ({
                url: "products",
                params: {customerId, includeUnavailable},
            }),
        }),
        getCommercialOfferTemplates: builder.query<CommercialOfferTemplate[], void>({
            query: () => "templates",
            providesTags: (result) => [
                {type: "CommercialOfferTemplates", id: "LIST"},
                ...(result ?? []).map(({id}) => ({type: "CommercialOfferTemplates" as const, id})),
            ],
        }),
        getCommercialOfferTemplate: builder.query<CommercialOfferTemplate, string>({
            query: (id) => `templates/${id}`,
            providesTags: (_result, _error, id) => [{type: "CommercialOfferTemplates", id}],
        }),
        createCommercialOfferTemplate: builder.mutation<CommercialOfferTemplate, CommercialOfferTemplateWriteRequest>({
            query: (body) => ({url: "templates", method: "POST", body}),
            invalidatesTags: [{type: "CommercialOfferTemplates", id: "LIST"}],
        }),
        updateCommercialOfferTemplate: builder.mutation<CommercialOfferTemplate, {id: string; body: CommercialOfferTemplateWriteRequest}>({
            query: ({id, body}) => ({url: `templates/${id}`, method: "PUT", body}),
            invalidatesTags: (_result, _error, {id}) => [
                {type: "CommercialOfferTemplates", id},
                {type: "CommercialOfferTemplates", id: "LIST"},
            ],
        }),
        deleteCommercialOfferTemplate: builder.mutation<void, {id: string; concurrencyStamp: string}>({
            query: ({id, concurrencyStamp}) => ({
                url: `templates/${id}`,
                method: "DELETE",
                params: {concurrencyStamp},
            }),
            invalidatesTags: [{type: "CommercialOfferTemplates", id: "LIST"}],
        }),
        createCommercialOffer: builder.mutation<CommercialOffer, {customerId: number; templateId?: string | null}>({
            query: (body) => ({url: "", method: "POST", body}),
            invalidatesTags: [{type: "CommercialOffers", id: "LIST"}],
        }),
        updateCommercialOffer: builder.mutation<CommercialOffer, {id: string; body: CommercialOfferEditRequest}>({
            query: ({id, body}) => ({url: id, method: "PUT", body}),
            invalidatesTags: (_result, _error, {id}) => [
                {type: "CommercialOffer", id},
                {type: "CommercialOffers", id: "LIST"},
            ],
        }),
        issueCommercialOffer: builder.mutation<CommercialOffer, OfferActionRequest>({
            query: ({id, concurrencyStamp}) => ({
                url: `${id}/issue`,
                method: "POST",
                body: {concurrencyStamp},
            }),
            invalidatesTags: (_result, _error, {id}) => [
                {type: "CommercialOffer", id},
                {type: "CommercialOffers", id: "LIST"},
            ],
        }),
        approveCommercialOffer: builder.mutation<CommercialOffer, OfferActionRequest & {reason: string}>({
            query: ({id, concurrencyStamp, reason}) => ({
                url: `${id}/approve`,
                method: "POST",
                body: {concurrencyStamp, reason},
            }),
            invalidatesTags: (_result, _error, {id}) => [
                {type: "CommercialOffer", id},
                {type: "CommercialOffers", id: "LIST"},
            ],
        }),
        reviseCommercialOffer: builder.mutation<CommercialOffer, OfferActionRequest>({
            query: ({id, concurrencyStamp}) => ({
                url: `${id}/revise`,
                method: "POST",
                body: {concurrencyStamp},
            }),
            invalidatesTags: (_result, _error, {id}) => [
                {type: "CommercialOffer", id},
                {type: "CommercialOffers", id: "LIST"},
            ],
        }),
        sendCommercialOffer: builder.mutation<CommercialOfferDelivery, OfferActionRequest>({
            query: ({id, concurrencyStamp}) => ({
                url: `${id}/send`,
                method: "POST",
                body: {concurrencyStamp},
            }),
            invalidatesTags: (_result, _error, {id}) => [
                {type: "CommercialOffer", id},
                {type: "CommercialOffers", id: "LIST"},
            ],
        }),
        convertCommercialOffer: builder.mutation<ConvertedOrder, OfferActionRequest>({
            query: ({id, concurrencyStamp}) => ({
                url: `${id}/convert`,
                method: "POST",
                body: {concurrencyStamp},
            }),
            invalidatesTags: (_result, _error, {id}) => [
                {type: "CommercialOffer", id},
                {type: "CommercialOffers", id: "LIST"},
            ],
        }),
        downloadCommercialOfferPdf: builder.mutation<Blob, {id: string; version: number}>({
            query: ({id, version}) => ({
                url: `${id}/pdf`,
                params: {version},
                responseHandler: (response) => response.blob(),
            }),
        }),
        previewCommercialOfferPdf: builder.mutation<Blob, {id: string}>({
            query: ({id}) => ({
                url: `${id}/preview`,
                responseHandler: (response) => response.blob(),
            }),
        }),
    }),
});

export const {
    useGetCommercialOffersQuery,
    useGetCommercialOfferQuery,
    useGetCommercialOfferCustomersQuery,
    useUpdateCommercialOfferCustomerMutation,
    useGetCommercialOfferProductsQuery,
    useGetCommercialOfferTemplatesQuery,
    useGetCommercialOfferTemplateQuery,
    useCreateCommercialOfferTemplateMutation,
    useUpdateCommercialOfferTemplateMutation,
    useDeleteCommercialOfferTemplateMutation,
    useCreateCommercialOfferMutation,
    useUpdateCommercialOfferMutation,
    useIssueCommercialOfferMutation,
    useApproveCommercialOfferMutation,
    useReviseCommercialOfferMutation,
    useSendCommercialOfferMutation,
    useConvertCommercialOfferMutation,
    useDownloadCommercialOfferPdfMutation,
    usePreviewCommercialOfferPdfMutation,
} = commercialOffersApi;
