import React, {useState} from 'react';
import {Alert, Button, Stack, Typography} from '@mui/material';
import {Link} from 'react-router-dom';
import {useCallQuery, useCallsQuery, useInboxQuery} from './operationsApi';
export default function IncomingCallBanner() {
    const calls = useCallsQuery(undefined,{pollingInterval:3000}); const inbox = useInboxQuery(undefined,{pollingInterval:10000});
    const [dismissed,setDismissed] = useState<string|null>(null);
    const active = calls.data?.find(c=>c.direction==='inbound' && (c.state==='ringing' || c.state==='answered') && Date.now()-new Date(c.startedAt).getTime()<3600000);
    const detail = useCallQuery(active?.id || '',{skip:!active || active.id===dismissed,pollingInterval:3000});
    const unread = inbox.data?.filter(n=>!n.readAt).length || 0;
    return <Stack spacing={1} sx={{px:2,pt:1}}>{active && active.id!==dismissed && <Alert severity="success" onClose={()=>setDismissed(active.id)} action={<Button component={Link} to={`/telephony?call=${active.id}`}>Открыть звонок</Button>}><Typography>Входящий звонок: {detail.data ? detail.data.customers.map(c=>c.name).join(', ') || 'Новый клиент' : 'Определяем клиента'} · +{active.phone}</Typography><Typography variant="caption">{detail.data?.orders.length ? `Связанные заказы: ${detail.data.orders.map(o=>`№${o.id}`).join(', ')}` : 'Уточните тему разговора'}</Typography></Alert>}{unread>0 && <Button sx={{alignSelf:'flex-start'}} component={Link} to="/orderPipeline">Уведомления по заказам: {unread}</Button>}</Stack>;
}
