import {createApi} from '@reduxjs/toolkit/query/react';
import {createFirmBaseQuery} from '../../api/baseQuery';

export type Country = 'RU' | 'BY' | 'KZ';
export interface CompanyIdentity {country: Country; taxNumber: string; kpp?: string | null}
export interface Counterparty extends CompanyIdentity {
    name: string; fullName: string; ogrn?: string | null; address: string; status?: string | null;
    manager?: string | null; phone?: string | null; email?: string | null; warnings: string[]; data: Record<string, unknown>;
    retrievedAt?: string;
}
export interface CompanySearch {query: string; country: Country; exact?: boolean; kpp?: string | null; count?: number}
export interface DaDataOperation {id: string; title: string; service: string; requiresSecret: boolean; adminOnly: boolean}
export interface DaDataSettingsStatus {hasApiKey: boolean; hasSecretKey: boolean; usesServerDefaults: boolean}
export interface UpdateDaDataSettings {apiKey?: string; secretKey?: string; clearSecretKey?: boolean}
export const companyIdentity = (company: Counterparty): CompanyIdentity => ({country: company.country, taxNumber: company.taxNumber, kpp: company.kpp});
export const counterpartiesApi = createApi({
    reducerPath: 'counterpartiesApi', baseQuery: createFirmBaseQuery('counterparties'), keepUnusedDataFor: 0,
    tagTypes: ['DaDataSettings', 'DaDataCapabilities'],
    endpoints: builder => ({
        counterpartyCapabilities: builder.query<{isConfigured: boolean; canClean: boolean; operations: DaDataOperation[]}, void>({query: () => 'capabilities', providesTags: ['DaDataCapabilities']}),
        daDataSettings: builder.query<DaDataSettingsStatus, void>({query: () => 'settings', providesTags: ['DaDataSettings']}),
        updateDaDataSettings: builder.mutation<DaDataSettingsStatus, UpdateDaDataSettings>({
            query: body => ({url: 'settings', method: 'PUT', body}),
            invalidatesTags: (result) => result ? ['DaDataSettings', 'DaDataCapabilities'] : [],
        }),
        resetDaDataSettings: builder.mutation<DaDataSettingsStatus, void>({
            query: () => ({url: 'settings', method: 'DELETE'}),
            invalidatesTags: (result) => result ? ['DaDataSettings', 'DaDataCapabilities'] : [],
        }),
        searchCounterparties: builder.mutation<Counterparty[], CompanySearch>({query: body => ({url: 'search', method: 'POST', body})}),
        executeDaData: builder.mutation<unknown, {operation: string; body: unknown}>({query: ({operation, body}) => ({url: `execute/${operation}`, method: 'POST', body})}),
        applyDocumentCounterparty: builder.mutation<{approvalVersion: string; partyId: number}, {documentId: number; role: number; organization: CompanyIdentity; expectedVersion: string; partyId?: number}>({
            query: ({documentId, role, ...body}) => ({url: `documents/${documentId}/parties/${role}`, method: 'PUT', body}),
        }),
    }),
});
export const {useCounterpartyCapabilitiesQuery, useDaDataSettingsQuery, useUpdateDaDataSettingsMutation, useResetDaDataSettingsMutation,
    useSearchCounterpartiesMutation, useExecuteDaDataMutation, useApplyDocumentCounterpartyMutation} = counterpartiesApi;
