import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {
    CreateOrEditLogisticsTripDto,
    InstallationCrewUserDto,
    LogisticsMapPointDto,
    LogisticsTripDto,
    LogisticsTripParams,
    UpcomingTripParams,
    LogisticsTripStatus,
} from "../../models/logistics";

const cleanParams = (params?: object) => {
    if (!params) {
        return undefined;
    }

    return Object.fromEntries(
        Object.entries(params).filter(([, value]) =>
            value !== undefined && value !== null && value !== "",
        ),
    );
};

export const logisticsApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "logisticsApi",
    tagTypes: ["LogisticsTrips", "LogisticsTrip", "LogisticsMap", "Installers"],
    baseQuery: createFirmBaseQuery(),
    endpoints: (builder) => ({
        getLogisticsTrips: builder.query<LogisticsTripDto[], LogisticsTripParams | void>({
            query: (params) => ({
                url: "logistics/trips",
                method: "GET",
                params: cleanParams(params || undefined),
            }),
            providesTags: ["LogisticsTrips"],
        }),
        getUpcomingTrips: builder.query<LogisticsTripDto[], UpcomingTripParams | void>({
            query: (params) => ({
                url: "logistics/trips/upcoming",
                method: "GET",
                params: cleanParams(params || undefined),
            }),
            providesTags: ["LogisticsTrips"],
        }),
        getMyUpcomingTrips: builder.query<LogisticsTripDto[], UpcomingTripParams | void>({
            query: (params) => ({
                url: "logistics/trips/my-upcoming",
                method: "GET",
                params: cleanParams(params || undefined),
            }),
            providesTags: ["LogisticsTrips"],
        }),
        getLogisticsMap: builder.query<LogisticsMapPointDto[], LogisticsTripParams | void>({
            query: (params) => ({
                url: "logistics/map",
                method: "GET",
                params: cleanParams(params || undefined),
            }),
            providesTags: ["LogisticsMap"],
        }),
        getInstallers: builder.query<InstallationCrewUserDto[], void>({
            query: () => ({
                url: "logistics/installers",
                method: "GET",
            }),
            providesTags: ["Installers"],
        }),
        createLogisticsTrip: builder.mutation<number, CreateOrEditLogisticsTripDto>({
            query: (trip) => ({
                url: "logistics/trips",
                method: "POST",
                body: trip,
            }),
            invalidatesTags: ["LogisticsTrips", "LogisticsMap"],
        }),
        editLogisticsTrip: builder.mutation<
            number,
            {tripId: number; trip: CreateOrEditLogisticsTripDto}
        >({
            query: ({tripId, trip}) => ({
                url: `logistics/trips/${tripId}`,
                method: "PUT",
                body: trip,
            }),
            invalidatesTags: ["LogisticsTrip", "LogisticsTrips", "LogisticsMap"],
        }),
        changeLogisticsTripStatus: builder.mutation<
            number,
            {tripId: number; status: LogisticsTripStatus}
        >({
            query: ({tripId, status}) => ({
                url: `logistics/trips/${tripId}/status`,
                method: "PUT",
                body: status,
            }),
            invalidatesTags: ["LogisticsTrip", "LogisticsTrips", "LogisticsMap"],
        }),
        deleteLogisticsTrip: builder.mutation<number, number>({
            query: (tripId) => ({
                url: `logistics/trips/${tripId}`,
                method: "DELETE",
            }),
            invalidatesTags: ["LogisticsTrips", "LogisticsMap"],
        }),
    }),
});

export const {
    useChangeLogisticsTripStatusMutation,
    useCreateLogisticsTripMutation,
    useDeleteLogisticsTripMutation,
    useEditLogisticsTripMutation,
    useGetInstallersQuery,
    useGetLogisticsMapQuery,
    useGetLogisticsTripsQuery,
    useGetMyUpcomingTripsQuery,
    useGetUpcomingTripsQuery,
} = logisticsApi;
