export const supportedLanguages = ["ru", "en", "pl", "lt"] as const;

export type Language = typeof supportedLanguages[number];

export type TranslationParams = Record<string, string | number | null | undefined>;

export type Translate = (key: string, params?: TranslationParams) => string;

export const defaultLanguage: Language = "ru";

export const languageOptions: Array<{
    code: Language;
    label: string;
    shortLabel: string;
    locale: string;
    htmlLang: string;
}> = [
    {code: "ru", label: "Русский", shortLabel: "RU", locale: "ru-RU", htmlLang: "ru"},
    {code: "en", label: "English", shortLabel: "EN", locale: "en-US", htmlLang: "en"},
    {code: "pl", label: "Polski", shortLabel: "PL", locale: "pl-PL", htmlLang: "pl"},
    {code: "lt", label: "Lietuvių", shortLabel: "LT", locale: "lt-LT", htmlLang: "lt"},
];

export const isSupportedLanguage = (language: string | null | undefined): language is Language =>
    Boolean(language && supportedLanguages.includes(language as Language));

export const getLanguageOption = (language: Language) =>
    languageOptions.find((option) => option.code === language) || languageOptions[0];

