import React from "react";
import {Button, IconButton, MenuItem, Select, SelectChangeEvent, Tooltip} from "@mui/material";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";
import CloseOutlinedIcon from "@mui/icons-material/CloseOutlined";
import MenuOutlinedIcon from "@mui/icons-material/MenuOutlined";
import MoreVertOutlinedIcon from "@mui/icons-material/MoreVertOutlined";
import TranslateOutlinedIcon from "@mui/icons-material/TranslateOutlined";
import {useAppDispatch, useAppSelector} from "../../../store/store";
import {openCloseAccountbar, openCloseSidebar} from "../menu/menuSlice";
import Image from "../../../ui/images/logo-no-background.png";
import {Language, useTranslation} from "../../../i18n";
import AppearancePicker from "../../../ui/appearance/AppearancePicker";
import "./Header.css";
import {useAuth} from "../../../auth/AuthContext";
import {useGetFirmsQuery} from "../../firms/firmsApi";
import {getActiveFirmId} from "../../../api/config";

const Header = () => {
    const dispatch = useAppDispatch();
    const {isSidebarOpen} = useAppSelector((state: any) => state.menu);
    const {language, languageOptions, setLanguage, t} = useTranslation();
    const {user, isSuperAdmin, switchFirm} = useAuth();
    const {data: firms = []} = useGetFirmsQuery(undefined, {skip: !isSuperAdmin});

    const handleLanguageChange = (event: SelectChangeEvent) => {
        setLanguage(event.target.value as Language);
    };

    return (
        <header className="header">
            <div className="header__brand">
                <img className="header__logo" src={Image} alt="VivoTech CRM"/>
                <div className="header__product">
                    <span className="header__product-name">VivoTech CRM</span>
                    <span className="header__product-meta">
                        {firms.find((firm) => String(firm.id) === getActiveFirmId())?.name ||
                            user?.firmName ||
                            "Выберите компанию"}
                    </span>
                </div>
                <Tooltip title={isSidebarOpen ? t("Свернуть меню") : t("Развернуть меню")}>
                    <IconButton
                        className="header__menu-button"
                        aria-label={isSidebarOpen ? t("Свернуть меню") : t("Развернуть меню")}
                        onClick={() => dispatch(openCloseSidebar({}))}
                    >
                        {isSidebarOpen ? <CloseOutlinedIcon/> : <MenuOutlinedIcon/>}
                    </IconButton>
                </Tooltip>
            </div>

            <div className="header__actions">
                {isSuperAdmin && (
                    <Select
                        className="header__firm-select"
                        size="small"
                        value={getActiveFirmId()}
                        displayEmpty
                        onChange={(event) => switchFirm(Number(event.target.value))}
                        inputProps={{"aria-label": "Активная компания"}}
                    >
                        <MenuItem value="" disabled>Выберите компанию</MenuItem>
                        {firms.map((firm) => (
                            <MenuItem
                                key={firm.id}
                                value={String(firm.id)}
                                disabled={firm.isBlocked}
                            >
                                {firm.name}{firm.isBlocked ? " — доступ заблокирован" : ""}
                            </MenuItem>
                        ))}
                    </Select>
                )}
                <AppearancePicker/>

                <div className="header__language">
                    <TranslateOutlinedIcon fontSize="small" aria-hidden="true"/>
                    <Select
                        className="header__language-select"
                        size="small"
                        value={language}
                        onChange={handleLanguageChange}
                        inputProps={{"aria-label": t("Язык интерфейса")}}
                        renderValue={(selected) =>
                            languageOptions.find((option) => option.code === selected)?.shortLabel || selected
                        }
                    >
                        {languageOptions.map((option) => (
                            <MenuItem key={option.code} value={option.code}>
                                {option.label}
                            </MenuItem>
                        ))}
                    </Select>
                </div>

                <nav className="header__nav" aria-label={t("Профиль")}>
                    <Button
                        className="header__account-button"
                        startIcon={<AccountCircleIcon/>}
                        variant="outlined"
                        onClick={() => dispatch(openCloseAccountbar({}))}
                    >
                        {user?.name || t("Аккаунт")}
                    </Button>
                </nav>
            </div>

            <Tooltip title={t("Открыть меню аккаунта")}>
                <IconButton
                    className="header__mobile-account"
                    aria-label={t("Открыть меню аккаунта")}
                    onClick={() => dispatch(openCloseAccountbar({}))}
                >
                    <MoreVertOutlinedIcon/>
                </IconButton>
            </Tooltip>
        </header>
    );
};

export default Header;
