interface NavigationItem {
    item: FirmMenuItem | null;
    to: string;
    icon: React.ElementType<SvgIconProps>;
    text: string;
    displayOrder: number;
}

type VisibleNavigationItem = NavigationItem & {
    setting?: FirmMenuSetting;
};

interface NavigationGroupDefinition {
    key: string;
    icon: React.ElementType<SvgIconProps>;
    text: string;
    items: FirmMenuItem[];
    routes?: string[];
}

interface NavigationGroup {
    type: "group";
    key: string;
    icon: React.ElementType<SvgIconProps>;
    text: string;
    displayOrder: number;
    children: VisibleNavigationItem[];
}

type NavigationEntry = ({type: "link"} & VisibleNavigationItem) | NavigationGroup;

