import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {
    CatalogGenerationBatch,
    CatalogGenerationBatchDraft,
    CatalogGenerationJob,
    DeleteCatalogGenerationBatchResult,
    StartCatalogGenerationResult,
} from "../../models/catalogGeneration";

export const catalogGenerationApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "catalogGeneration",
    tagTypes: ["GenerationBatches"],
    baseQuery: createFirmBaseQuery("catalog-generation"),
    endpoints: (builder) => ({
        startCatalogGeneration: builder.mutation<StartCatalogGenerationResult, FormData>({
            query: (formData) => ({url: "", method: "POST", body: formData}),
            invalidatesTags: ["GenerationBatches"],
        }),
        editCatalogGenerationBatch: builder.mutation<StartCatalogGenerationResult, {batchId: string; formData: FormData}>({
            query: ({batchId, formData}) => ({url: `batches/${batchId}`, method: "PUT", body: formData}),
            invalidatesTags: ["GenerationBatches"],
        }),
        getCatalogGenerationStatus: builder.query<CatalogGenerationJob, string>({
            query: (jobId) => ({url: jobId, method: "GET"}),
        }),
        cancelCatalogGeneration: builder.mutation<{cancelled: boolean}, string>({
            query: (jobId) => ({url: `${jobId}/cancel`, method: "POST"}),
            invalidatesTags: ["GenerationBatches"],
        }),
        getCatalogGenerationBatches: builder.query<CatalogGenerationBatch[], void>({
            query: () => ({url: "batches", method: "GET"}),
            providesTags: ["GenerationBatches"],
        }),
        getCatalogGenerationBatchDraft: builder.query<CatalogGenerationBatchDraft, string>({
            query: (batchId) => ({url: `batches/${batchId}/draft`, method: "GET"}),
        }),
        deleteCatalogGenerationBatch: builder.mutation<DeleteCatalogGenerationBatchResult, string>({
            query: (batchId) => ({url: `batches/${batchId}`, method: "DELETE"}),
            invalidatesTags: ["GenerationBatches"],
        }),
    }),
});

export const {
    useStartCatalogGenerationMutation,
    useEditCatalogGenerationBatchMutation,
    useGetCatalogGenerationStatusQuery,
    useCancelCatalogGenerationMutation,
    useGetCatalogGenerationBatchesQuery,
    useGetCatalogGenerationBatchDraftQuery,
    useDeleteCatalogGenerationBatchMutation,
} = catalogGenerationApi;
