import React, {createContext, ReactNode, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useState} from "react";
import {CssBaseline, ThemeProvider} from "@mui/material";
import {alpha} from "@mui/material/styles";
import {getAppTheme} from "./theme";
import {Language, useTranslation} from "./i18n";
import {AppColorMode, AppDensity, AppPalette, AppThemeMode, getThemeColors, isAppColorMode, isAppDensity, isAppPalette} from "./themePresets";

export const appearanceStorageKey = "vivotech.crm.appearance";
const legacyThemeStorageKey = "vivotech.crm.theme";
const systemQuery = "(prefers-color-scheme: dark)";

export interface AppearancePreferences {colorMode: AppColorMode; palette: AppPalette; density: AppDensity}
const defaultPreferences: AppearancePreferences = {colorMode: "system", palette: "violet", density: "comfortable"};

export const readAppearancePreferences = (): AppearancePreferences => {
    try {
        const value = JSON.parse(window.localStorage.getItem(appearanceStorageKey) || "null");
        if (value && typeof value === "object") return {
            colorMode: isAppColorMode(value.colorMode) ? value.colorMode : "system",
            palette: isAppPalette(value.palette) ? value.palette : "violet",
            density: isAppDensity(value.density) ? value.density : "comfortable",
        };
        const legacy = window.localStorage.getItem(legacyThemeStorageKey);
        return {...defaultPreferences, colorMode: legacy === "light" || legacy === "dark" ? legacy : "system"};
    } catch {return defaultPreferences;}
};

const getSystemMode = (): AppThemeMode => typeof window.matchMedia === "function" && window.matchMedia(systemQuery).matches ? "dark" : "light";

export const applyAppearanceToDocument = (mode: AppThemeMode, preferences: AppearancePreferences) => {
    const c = getThemeColors(mode, preferences.palette);
    const root = document.documentElement;
    root.dataset.theme = mode;
    root.dataset.palette = preferences.palette;
    root.dataset.density = preferences.density;
    root.style.colorScheme = mode;
    root.style.background = c.page;
    const tokens: Record<string, string> = {
        "color-page": c.page, "color-page-soft": c.pageSoft, "color-surface": c.paper,
        "color-surface-soft": c.paperSoft, "color-surface-muted": c.paperMuted,
        "color-header-bg": alpha(c.paper, .94), "color-sidebar-bg": c.paper,
        "color-text": c.text, "color-muted": c.muted, "color-border": c.border, "color-border-strong": c.borderStrong,
        "color-primary": c.primary, "color-primary-hover": c.primaryHover, "color-primary-soft": c.primarySoft,
        "color-primary-soft-hover": alpha(c.primary, .16), "color-primary-border": alpha(c.primary, .24),
        "color-secondary": c.secondary, "color-secondary-hover": c.secondaryHover,
        "color-success": c.success, "color-success-hover": c.successHover, "color-success-soft": c.successSoft,
        "color-success-text": c.success, "color-success-border": alpha(c.success, .25),
        "color-warning": c.warning, "color-warning-hover": c.warningHover, "color-warning-soft": c.warningSoft,
        "color-warning-text": c.warning, "color-warning-border": alpha(c.warning, .25),
        "color-danger": c.danger, "color-danger-hover": c.dangerHover, "color-danger-soft": c.dangerSoft,
        "color-danger-text": c.danger, "color-danger-border": alpha(c.danger, .25), "color-on-danger": c.onPrimary,
        "color-disabled": c.disabled, "color-disabled-text": c.disabledText,
        "color-on-primary": c.onPrimary, "color-on-secondary": c.onPrimary,
        "gradient-subtle": `linear-gradient(135deg, ${c.paperSoft}, ${c.pageSoft})`,
        "shadow-control": "0 1px 2px rgba(30, 24, 50, .04)", "shadow-soft": c.shadowSoft,
        "shadow-hover": mode === "dark" ? "0 8px 28px rgba(0,0,0,.22)" : "0 8px 28px rgba(38,30,63,.08)",
        "shadow-popover": c.shadowPopover, "focus-ring": `0 0 0 3px ${alpha(c.primary, .22)}`,
        "control-height": preferences.density === "compact" ? "36px" : "44px",
        "panel-padding": preferences.density === "compact" ? "16px" : "clamp(16px, 2vw, 24px)",
        "table-cell-padding": preferences.density === "compact" ? "10px 14px" : "15px 18px",
    };
    Object.entries(tokens).forEach(([key, value]) => root.style.setProperty(`--${key}`, value));
    document.querySelector('meta[name="theme-color"]')?.setAttribute("content", c.page);
};

interface AppThemeModeContextValue extends AppearancePreferences {
    mode: AppThemeMode;
    isDarkMode: boolean;
    setThemeMode: (mode: AppThemeMode) => void;
    toggleThemeMode: () => void;
    setAppearance: (preferences: Partial<AppearancePreferences>) => void;
}
const AppThemeModeContext = createContext<AppThemeModeContextValue | undefined>(undefined);

export const AppThemeProvider = ({children, language = "ru"}: {children: ReactNode; language?: Language}) => {
    const [preferences, setPreferences] = useState(readAppearancePreferences);
    const [systemMode, setSystemMode] = useState(getSystemMode);
    const mode = preferences.colorMode === "system" ? systemMode : preferences.colorMode;
    const theme = useMemo(() => getAppTheme(mode, preferences.palette, preferences.density, language), [mode, preferences.palette, preferences.density, language]);

    useLayoutEffect(() => {applyAppearanceToDocument(mode, preferences);}, [mode, preferences]);
    useEffect(() => {
        try {window.localStorage.setItem(appearanceStorageKey, JSON.stringify(preferences));} catch { /* Preferences still work when browser storage is disabled. */ }
    }, [preferences]);
    useEffect(() => {
        if (typeof window.matchMedia !== "function") return;
        const media = window.matchMedia(systemQuery);
        const change = () => setSystemMode(media.matches ? "dark" : "light");
        media.addEventListener?.("change", change);
        return () => media.removeEventListener?.("change", change);
    }, []);
    useEffect(() => {
        const sync = (event: StorageEvent) => {if (event.key === appearanceStorageKey) setPreferences(readAppearancePreferences());};
        window.addEventListener("storage", sync);
        return () => window.removeEventListener("storage", sync);
    }, []);

    const setAppearance = useCallback((next: Partial<AppearancePreferences>) => setPreferences(current => ({...current, ...next})), []);
    const setThemeMode = useCallback((next: AppThemeMode) => setAppearance({colorMode: next}), [setAppearance]);
    const toggleThemeMode = useCallback(() => setThemeMode(mode === "dark" ? "light" : "dark"), [mode, setThemeMode]);
    const value = useMemo(() => ({...preferences, mode, isDarkMode: mode === "dark", setAppearance, setThemeMode, toggleThemeMode}), [preferences, mode, setAppearance, setThemeMode, toggleThemeMode]);

    return <AppThemeModeContext.Provider value={value}><ThemeProvider theme={theme}><CssBaseline/>{children}</ThemeProvider></AppThemeModeContext.Provider>;
};

export const LocalizedAppThemeProvider = ({children}: {children: ReactNode}) => {
    const {language} = useTranslation();
    return <AppThemeProvider language={language}>{children}</AppThemeProvider>;
};

export const useAppThemeMode = () => {
    const context = useContext(AppThemeModeContext);
    if (!context) throw new Error("useAppThemeMode must be used inside AppThemeProvider");
    return context;
};
