import {GridRowId} from "@mui/x-data-grid";
import {createApi} from '@reduxjs/toolkit/query/react'
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../../api/baseQuery";
import {ICreateSource, ISource} from "../../../models/source";

export const sourcesApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: 'sources',
    tagTypes: ['Sources'],
    baseQuery: createFirmBaseQuery('sources'),
    endpoints: (builder) => ({
        getSources: builder.query<ISource[], void | Record<string, never>>({
            query: () => ({
                url: '',
                method: 'GET'
            }),
            providesTags: ['Sources']
        }),
        getSourceById: builder.query<ISource, string | number>({
            query: (id) => ({
                url: `${id}`,
                method: 'GET'
            }),
        }),
        createSource: builder.mutation<number, ICreateSource>({
            query: (source: ICreateSource) => ({
                url: ``,
                method: 'POST',
                body: source,
            }),
            invalidatesTags: ['Sources']
        }),
        editSource: builder.mutation<number, ISource>({
            query: (source: ISource) => ({
                url: ``,
                method: 'PUT',
                body: source
            }),
            invalidatesTags: ['Sources']
        }),
        deleteSource: builder.mutation<number, GridRowId>({
            query: (id: GridRowId) => ({
                url: `${id}`,
                method: 'DELETE'
            }),
            invalidatesTags: ['Sources']
        }),
    }),
})

export const {
    useGetSourcesQuery,
    useGetSourceByIdQuery,
    useCreateSourceMutation,
    useEditSourceMutation,
    useDeleteSourceMutation
} = sourcesApi;
