import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../../api/baseQuery";
import {FirmMenuSetting} from "../../../models/menu";

export const menuSettingsApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "menuSettings",
    tagTypes: ["MenuSettings"],
    baseQuery: createFirmBaseQuery(),
    endpoints: (builder) => ({
        getMenuSettings: builder.query<FirmMenuSetting[], void>({
            query: () => ({
                url: "menu-settings",
                method: "GET",
            }),
            providesTags: ["MenuSettings"],
        }),
        updateMenuSettings: builder.mutation<FirmMenuSetting[], FirmMenuSetting[]>({
            query: (settings) => ({
                url: "menu-settings",
                method: "PUT",
                body: settings,
            }),
            invalidatesTags: ["MenuSettings"],
        }),
    }),
});

export const {
    useGetMenuSettingsQuery,
    useUpdateMenuSettingsMutation,
} = menuSettingsApi;
