import {BaseQueryFn, FetchArgs, FetchBaseQueryError, fetchBaseQuery} from "@reduxjs/toolkit/query/react";
import {API_BASE_URL, getAccessToken, getActiveFirmId} from "./config";
import {getCurrentLanguage} from "../i18n";

export const liveServerDataApiOptions = {
    keepUnusedDataFor: 0,
    refetchOnMountOrArgChange: true,
    refetchOnFocus: true,
    refetchOnReconnect: true,
} as const;

const prepareHeaders = (headers: Headers) => {
    const token = getAccessToken();

    if (token) {
        headers.set("Authorization", `Bearer ${token}`);
    }

    const language = getCurrentLanguage();
    headers.set("Accept-Language", language);
    headers.set("X-Locale", language);

    return headers;
};

const rawBaseQuery = fetchBaseQuery({
    baseUrl: API_BASE_URL,
    prepareHeaders,
    timeout: 60_000,
});

const disableBrowserCacheForGet = (args: string | FetchArgs): FetchArgs => {
    if (typeof args === "string") {
        return {url: args, cache: "no-store"};
    }

    const method = (args.method || "GET").toUpperCase();

    const request = args.body instanceof FormData ? {timeout: 180_000, ...args} : args;
    return method === "GET" ? {...request, cache: "no-store"} : request;
};

const withUnauthorizedHandling = (
    query: BaseQueryFn<string | FetchArgs, unknown, FetchBaseQueryError>,
): BaseQueryFn<string | FetchArgs, unknown, FetchBaseQueryError> =>
    async (args, api, extraOptions) => {
        // fetchBaseQuery's timeout calls api.abort(). Keep that cancellation
        // local to the HTTP request so RTK delivers TIMEOUT_ERROR to the UI
        // instead of discarding it as a cancelled thunk.
        const controller = new AbortController();
        const abort = () => controller.abort();
        api.signal.addEventListener("abort", abort, {once: true});
        if (api.signal.aborted) controller.abort();
        try {
            const result = await query(disableBrowserCacheForGet(args), {...api, signal: controller.signal, abort}, extraOptions);

            if (result.error?.status === 401 && typeof window !== "undefined") {
                window.dispatchEvent(new Event("vivotech:unauthorized"));
            }

            return result;
        } finally {
            api.signal.removeEventListener("abort", abort);
        }
    };

export const createApiBaseQuery = () => withUnauthorizedHandling(rawBaseQuery);

export const createFirmBaseQuery = (resourcePath = ""): BaseQueryFn<
    string | FetchArgs,
    unknown,
    FetchBaseQueryError
> => {
    const normalizedResource = resourcePath.replace(/^\/+|\/+$/g, "");

    return withUnauthorizedHandling(async (args, api, extraOptions) => {
        const firmId = getActiveFirmId();
        if (!firmId) return {error: {status: 'CUSTOM_ERROR', error: 'tenant.context_required'}};
        const request = typeof args === "string" ? {url: args} : {...args};
        const normalizedUrl = request.url.replace(/^\/+/, "");
        const prefix = `/firms/${firmId}${
            normalizedResource ? `/${normalizedResource}` : ""
        }`;

        return rawBaseQuery(
            {...request, url: normalizedUrl ? `${prefix}/${normalizedUrl}` : prefix},
            api,
            extraOptions,
        );
    });
};
