export type AppThemeMode = "light" | "dark";
export type AppColorMode = AppThemeMode | "system";
export type AppPalette = "violet" | "ocean" | "copper";
export type AppDensity = "comfortable" | "compact";

export const themePresets = [
    {palette: "violet", mode: "light", name: "Фарфор", description: "Чистый белый · мягкий ирис"},
    {palette: "ocean", mode: "light", name: "Лагуна", description: "Прохладный свет · океанский синий"},
    {palette: "copper", mode: "light", name: "Лён", description: "Тёплый кремовый · медный акцент"},
    {palette: "violet", mode: "dark", name: "Обсидиан", description: "Глубокий графит · светлая лаванда"},
    {palette: "ocean", mode: "dark", name: "Север", description: "Ночной синий · ледяной акцент"},
    {palette: "copper", mode: "dark", name: "Эспрессо", description: "Тёплый графит · янтарный свет"},
] as const;

const accents = {
    violet: {light: ["#6250c7", "#5140ae", "#f0edfc"], dark: ["#b6a5ff", "#c9bcff", "#29243e"]},
    ocean: {light: ["#176b96", "#125777", "#e8f3fa"], dark: ["#7dc9f3", "#a4dcfa", "#1b303e"]},
    copper: {light: ["#9b522d", "#7d3f20", "#fbefe5"], dark: ["#ecb487", "#f4cba8", "#392b23"]},
} as const;

export const getThemeColors = (mode: AppThemeMode, palette: AppPalette = "violet") => {
    const dark = mode === "dark";
    const warm = palette === "copper";
    const ocean = palette === "ocean";
    const [primary, primaryHover, primarySoft] = accents[palette][mode];
    return {
        page: dark ? warm ? "#161412" : ocean ? "#101821" : "#14141b" : warm ? "#f7f4ef" : ocean ? "#f2f6f9" : "#f6f6fa",
        pageSoft: dark ? warm ? "#1d1916" : ocean ? "#15202a" : "#1a1923" : warm ? "#f0eae2" : ocean ? "#eaf1f7" : "#efedf8",
        paper: dark ? warm ? "#211d19" : ocean ? "#19232e" : "#1e1e28" : "#ffffff",
        paperSoft: dark ? warm ? "#2b2520" : ocean ? "#222f3c" : "#292935" : warm ? "#f8f4ef" : ocean ? "#f0f5f9" : "#f5f4fa",
        paperMuted: dark ? warm ? "#1b1815" : ocean ? "#141e28" : "#191922" : warm ? "#fcfaf7" : "#fcfcfe",
        text: dark ? warm ? "#f5efe8" : "#f0f0f6" : warm ? "#302923" : "#262538",
        muted: dark ? warm ? "#b8aaa0" : "#b0afc3" : warm ? "#75685e" : "#6f6d83",
        border: dark ? warm ? "#3a322b" : ocean ? "#314151" : "#373643" : warm ? "#e7ded3" : "#e6e4ef",
        borderStrong: dark ? warm ? "#887666" : "#777488" : warm ? "#9c8978" : "#8e879d",
        primary, primaryHover, primarySoft,
        secondary: dark ? "#dbd9e9" : "#474356",
        secondaryHover: dark ? "#f0edf8" : "#302c3e",
        success: dark ? "#79d4aa" : "#247653",
        successHover: dark ? "#a1e7c6" : "#195c40",
        successSoft: dark ? "#20352c" : "#eaf7f0",
        warning: dark ? "#efc27b" : "#946218",
        warningHover: dark ? "#f5d8a7" : "#754c10",
        warningSoft: dark ? "#392f20" : "#fff5df",
        danger: dark ? "#f5a1aa" : "#b8394a",
        dangerHover: dark ? "#ffc0c7" : "#972a3a",
        dangerSoft: dark ? "#3b252d" : "#fff0f2",
        disabled: dark ? "#2b2935" : "#efedf3",
        disabledText: dark ? "#8b869a" : "#827b92",
        onPrimary: dark ? "#181421" : "#ffffff",
        shadowSoft: dark ? "0 2px 8px rgba(0, 0, 0, .12)" : "0 2px 8px rgba(38, 30, 63, .035), 0 12px 32px rgba(38, 30, 63, .025)",
        shadowPopover: dark ? "0 24px 80px rgba(0, 0, 0, .5)" : "0 24px 80px rgba(38, 30, 63, .15)",
    };
};

export const isAppPalette = (value: unknown): value is AppPalette => value === "violet" || value === "ocean" || value === "copper";
export const isAppColorMode = (value: unknown): value is AppColorMode => value === "light" || value === "dark" || value === "system";
export const isAppDensity = (value: unknown): value is AppDensity => value === "comfortable" || value === "compact";
