import {GridRowId} from "@mui/x-data-grid";
import {createApi} from '@reduxjs/toolkit/query/react'
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {PagedResponse} from "../../models/api";
import {ICreateCategory} from "../../models/category";
import {IProduct, IShortProduct, ProductParams} from "../../models/product";
import {BulkDeleteRequest, BulkDeleteResult} from "../../models/bulkDelete";
import {ProductFileAnalysis, ProductFileImportResult, ProductFileImportSettings, ProductFilePreview} from "../../models/productFileImport";
import {ApproveProductDraftsResult, ProductRecognitionBatch, ProductRecognitionBatchSummary, ProductRecognitionCapabilities, ProductRecognitionDraft} from "../../models/productRecognition";

const toProductQueryParams = (productParams: ProductParams) => {
    const {productCategories, categories, ...params} = productParams;

    return {
        ...params,
        categories: categories || productCategories?.join(",") || undefined,
    };
};

export const productsApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: 'products',
    tagTypes: ['Products','Product','ProductFileImportSettings', 'Recognition'],
    baseQuery: createFirmBaseQuery('products'),
    endpoints: (builder) => ({
        getRecognitionCapabilities: builder.query<ProductRecognitionCapabilities, void>({
            query: () => 'recognition/capabilities',
        }),
        getRecognitionBatches: builder.query<ProductRecognitionBatchSummary[], void>({
            query: () => 'recognition/batches', providesTags: ['Recognition'],
        }),
        getRecognitionBatch: builder.query<ProductRecognitionBatch, string>({
            query: (id) => `recognition/batches/${id}`, providesTags: ['Recognition'],
        }),
        getRecognitionDraft: builder.query<ProductRecognitionDraft, string>({
            query: (id) => `recognition/drafts/${id}`, providesTags: ['Recognition'],
        }),
        recognizeProducts: builder.mutation<ProductRecognitionBatch, FormData>({
            query: (body) => ({url: 'recognition/batches', method: 'POST', body, timeout: 900_000}),
            invalidatesTags: ['Recognition'],
        }),
        clearRecognitionBuffer: builder.mutation<void, string | void>({
            query: (id) => ({url: `recognition/batches${id ? `/${id}` : ''}`, method: 'DELETE'}),
            invalidatesTags: (_, error) => error ? [] : ['Recognition'],
        }),
        deleteRecognitionDraft: builder.mutation<void, {id: string; version: string}>({
            query: ({id, version}) => ({url: `recognition/drafts/${id}`, method: 'DELETE', body: {version}}),
            invalidatesTags: (_, error) => error ? [] : ['Recognition'],
        }),
        addRecognitionDraft: builder.mutation<ProductRecognitionDraft, string>({
            query: (id) => ({url: `recognition/batches/${id}/drafts`, method: 'POST'}),
            invalidatesTags: ['Recognition'],
        }),
        saveRecognitionDraft: builder.mutation<ProductRecognitionDraft, {id: string; body: FormData}>({
            query: ({id, body}) => ({url: `recognition/drafts/${id}`, method: 'PUT', body}),
            invalidatesTags: ['Recognition'],
        }),
        approveRecognitionDraft: builder.mutation<number, {id: string; version: string}>({
            query: ({id, version}) => ({url: `recognition/drafts/${id}/approve`, method: 'POST', body: {version}}),
            invalidatesTags: ['Recognition', 'Products', 'Product'],
        }),
        approveRecognitionDrafts: builder.mutation<ApproveProductDraftsResult, {batchId: string; drafts: {id: string; version: string}[]}>({
            query: ({batchId, drafts}) => ({url: `recognition/batches/${batchId}/approve`, method: 'POST', body: {drafts}, timeout: 300_000}),
            invalidatesTags: ['Recognition', 'Products', 'Product'],
        }),
        rejectRecognitionDraft: builder.mutation<ProductRecognitionDraft, {id: string; version: string}>({
            query: ({id, version}) => ({url: `recognition/drafts/${id}/reject`, method: 'POST', body: {version}}),
            invalidatesTags: ['Recognition'],
        }),
        getProducts: builder.query<PagedResponse<IShortProduct>, ProductParams>({
            query: (productParams: ProductParams) => ({
                url: '',
                method: 'GET',
                params: toProductQueryParams(productParams)
            }),
            providesTags: ['Products'],
        }),
        getProductById: builder.query<IProduct, string | number>({
            query: (id) => ({
                url: `${id}`,
                method: 'GET'
            }),
            providesTags: ['Product'],
        }),
        getProductsForSearch: builder.query<IShortProduct[], string | void>({
            query: (searchTerm = "") => ({
                url: 'search',
                method: 'GET',
                params: {searchTerm}
            }),
        }),
        getProductsByCategoryId: builder.query<IShortProduct[], string | number>({
            query: (id) => ({
                url: `categories/${id}`,
                method: 'GET'
            }),
        }),
        createProduct: builder.mutation<number, FormData>({
            query: (product: FormData) => ({
                url: ``,
                method: 'POST',
                body: product
            }),
            invalidatesTags: ['Products','Product']
        }),
        analyzeProductFile: builder.mutation<ProductFileAnalysis, FormData>({
            query: (body) => ({
                url: 'file-import/analyze',
                method: 'POST',
                body,
            }),
        }),
        previewProductFile: builder.mutation<ProductFilePreview, FormData>({
            query: (body) => ({
                url: 'file-import/preview',
                method: 'POST',
                body,
            }),
        }),
        getProductFileImportSettings: builder.query<ProductFileImportSettings, void>({
            query: () => ({url: 'file-import/settings', method: 'GET'}),
            providesTags: ['ProductFileImportSettings'],
        }),
        updateProductFileImportSettings: builder.mutation<ProductFileImportSettings, ProductFileImportSettings>({
            query: (body) => ({url: 'file-import/settings', method: 'PUT', body}),
            invalidatesTags: ['ProductFileImportSettings'],
        }),
        importProductsFromFile: builder.mutation<ProductFileImportResult, FormData>({
            query: (body) => ({
                url: 'file-import',
                method: 'POST',
                body,
            }),
            invalidatesTags: ['Products', 'Product'],
        }),
        editProduct: builder.mutation<number, FormData>({
            query: (product:FormData) => ({
                url: ``,
                method: 'PUT',
                body: product,
            }),
            invalidatesTags: ['Products','Product']
        }),
        deleteProduct: builder.mutation<number, GridRowId>({
            query: (id: GridRowId) => ({
                url: `${id}`,
                method: 'DELETE'
            }),
            invalidatesTags: ['Products']
        }),
        bulkDeleteProducts: builder.mutation<BulkDeleteResult, BulkDeleteRequest>({
            query: (request) => ({
                url: 'bulk-delete',
                method: 'POST',
                body: request,
            }),
            invalidatesTags: ['Products', 'Product'],
        }),
        moveProductsToCategory: builder.mutation<boolean, {categoryId: number | string; category: ICreateCategory}>({
            query: ({categoryId, category}) => ({
                url: `move-products/${categoryId}`,
                method: 'POST',
                body: category,
            }),
            invalidatesTags: ['Products']
        }),
    }),
})

export const {
    useGetRecognitionCapabilitiesQuery, useGetRecognitionBatchesQuery, useGetRecognitionBatchQuery,
    useGetRecognitionDraftQuery, useRecognizeProductsMutation, useAddRecognitionDraftMutation,
    useClearRecognitionBufferMutation, useDeleteRecognitionDraftMutation,
    useSaveRecognitionDraftMutation, useApproveRecognitionDraftMutation, useRejectRecognitionDraftMutation,
    useApproveRecognitionDraftsMutation,
    useBulkDeleteProductsMutation, useCreateProductMutation, useDeleteProductMutation,
    useEditProductMutation,
    useAnalyzeProductFileMutation, usePreviewProductFileMutation, useImportProductsFromFileMutation,
    useGetProductFileImportSettingsQuery, useUpdateProductFileImportSettingsMutation,
    useGetProductByIdQuery, useGetProductsByCategoryIdQuery,useGetProductsQuery,useLazyGetProductsByCategoryIdQuery,
    useGetProductsForSearchQuery, useMoveProductsToCategoryMutation
} = productsApi;
