import {GridRowId} from "@mui/x-data-grid";
import {createApi} from '@reduxjs/toolkit/query/react'
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../../api/baseQuery";
import {ICreatePaymentMethod, IPaymentMethod} from "../../../models/paymentMethod";

export const paymentMethodsApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: 'paymentMethods',
    tagTypes:['PaymentMethods'],
    baseQuery: createFirmBaseQuery('paymentMethods'),
    endpoints: (builder) => ({
        getPaymentMethods: builder.query<IPaymentMethod[], void | Record<string, never>>({
            query: () => ({
                url: '',
                method: 'GET'
            }),
            providesTags:['PaymentMethods']
        }),
        getPaymentMethodById: builder.query<IPaymentMethod, string | number>({
            query: (id) => ({
                url: `${id}`,
                method: 'GET'
            }),
        }),
        createPaymentMethod: builder.mutation<number, ICreatePaymentMethod>({
            query: (paymentMethod: ICreatePaymentMethod) => ({
                url: ``,
                method: 'POST',
                body: paymentMethod,
            }),
            invalidatesTags:['PaymentMethods']
        }),
        editPaymentMethod: builder.mutation<number, IPaymentMethod>({
            query: (paymentMethod: IPaymentMethod) => ({
                url: ``,
                method: 'PUT',
                body: paymentMethod
            }),
            invalidatesTags:['PaymentMethods']
        }),
        deletePaymentMethod: builder.mutation<number, GridRowId>({
            query: (id: GridRowId) => ({
                url: `${id}`,
                method: 'DELETE'
            }),
            invalidatesTags:['PaymentMethods']
        }),
    }),
})

export const {
    useGetPaymentMethodsQuery,
    useGetPaymentMethodByIdQuery,
    useCreatePaymentMethodMutation,
    useEditPaymentMethodMutation,
    useDeletePaymentMethodMutation
} = paymentMethodsApi;
