import {createApi} from "@reduxjs/toolkit/query/react";
import {createApiBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {AuthUser, Firm, UpsertFirm} from "../../models/auth";

export const firmsApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "firmsApi",
    tagTypes: ["Firms", "FirmUsers"],
    baseQuery: createApiBaseQuery(),
    endpoints: (builder) => ({
        getFirms: builder.query<Firm[], void>({
            query: () => "/firms",
            providesTags: ["Firms"],
        }),
        getFirm: builder.query<Firm, number>({
            query: (id) => `/firms/${id}`,
            providesTags: (_result, _error, id) => [{type: "Firms", id}],
        }),
        getFirmUsers: builder.query<AuthUser[], number>({
            query: (id) => `/firms/${id}/users`,
            providesTags: (_result, _error, id) => [{type: "FirmUsers", id}],
        }),
        createFirm: builder.mutation<Firm, UpsertFirm>({
            query: (body) => ({url: "/firms", method: "POST", body}),
            invalidatesTags: ["Firms"],
        }),
        updateFirm: builder.mutation<Firm, {id: number; body: UpsertFirm}>({
            query: ({id, body}) => ({url: `/firms/${id}`, method: "PUT", body}),
            invalidatesTags: (_result, _error, {id}) => ["Firms", {type: "Firms", id}],
        }),
        updateFirmAccess: builder.mutation<Firm, {id: number; isBlocked: boolean}>({
            query: ({id, isBlocked}) => ({
                url: `/firms/${id}/access`,
                method: "PUT",
                body: {isBlocked},
            }),
            invalidatesTags: (_result, _error, {id}) => ["Firms", {type: "Firms", id}],
        }),
        deleteFirm: builder.mutation<void, number>({
            query: (id) => ({url: `/firms/${id}`, method: "DELETE"}),
            invalidatesTags: ["Firms"],
        }),
    }),
});

export const {
    useGetFirmsQuery,
    useGetFirmQuery,
    useGetFirmUsersQuery,
    useCreateFirmMutation,
    useUpdateFirmMutation,
    useUpdateFirmAccessMutation,
    useDeleteFirmMutation,
} = firmsApi;
