import React, {useEffect, useRef} from "react";
import styledCom from "styled-components";
import AccountCircleOutlinedIcon from "@mui/icons-material/AccountCircleOutlined";
import SettingsOutlinedIcon from "@mui/icons-material/SettingsOutlined";
import LogoutOutlinedIcon from "@mui/icons-material/LogoutOutlined";
import TelegramIcon from "@mui/icons-material/Telegram";
import {useAppDispatch, useAppSelector} from "../../../../store/store";
import {closeNavigationPanels} from "../menuSlice";
import {useTranslation} from "../../../../i18n";
import {useAuth} from "../../../../auth/AuthContext";
import {useNavigate} from "react-router-dom";

const AccountMenu = styledCom.div({
    position: "fixed",
    top: "calc(var(--app-header-height) + 10px)",
    right: "14px",
    zIndex: 40,
    display: "grid",
    gap: "8px",
    width: "min(280px, calc(100vw - 28px))",
    padding: "10px",
    background: "var(--color-surface)",
    border: "1px solid var(--color-border)",
    borderRadius: "16px",
    boxShadow: "var(--shadow-popover)",
});

const AccountMenuItem = styledCom.button({
    display: "grid",
    gridTemplateColumns: "22px minmax(0, 1fr)",
    alignItems: "center",
    gap: "10px",
    minHeight: "42px",
    padding: "0 12px",
    color: "var(--color-text)",
    background: "transparent",
    border: 0,
    borderRadius: "10px",
    font: "inherit",
    fontWeight: 700,
    textAlign: "left",
    cursor: "pointer",
    transition: "background-color 160ms ease, color 160ms ease",

    "&:hover": {
        background: "var(--color-surface-soft)",
    },

    svg: {
        color: "var(--color-muted)",
    },
});

const Accountbar = () => {
    const {isAccountbarOpen} = useAppSelector((state: any) => state.menu);
    const {t} = useTranslation();
    const {user, isCompanyAdmin, signOut} = useAuth();
    const navigate = useNavigate();
    const dispatch = useAppDispatch();
    const menuRef = useRef<HTMLDivElement>(null);
    useEffect(() => {
        if (!isAccountbarOpen) return;
        const previous = document.activeElement as HTMLElement | null;
        menuRef.current?.querySelector<HTMLButtonElement>('button')?.focus();
        const close = () => dispatch(closeNavigationPanels({collapseSidebar: false}));
        const outside = (event: PointerEvent) => {
            if (!menuRef.current?.contains(event.target as Node) && !(event.target as Element).closest?.('.header__account-button, .header__mobile-account')) close();
        };
        const keyboard = (event: KeyboardEvent) => {if (event.key === 'Escape') {close(); previous?.focus();}};
        document.addEventListener('pointerdown', outside);
        document.addEventListener('keydown', keyboard);
        return () => {document.removeEventListener('pointerdown', outside); document.removeEventListener('keydown', keyboard);};
    }, [isAccountbarOpen, dispatch]);

    if (!isAccountbarOpen) {
        return null;
    }

    return (
        <AccountMenu ref={menuRef} role="menu" aria-label={t("Меню аккаунта")}>
            <AccountMenuItem type="button" role="menuitem">
                <AccountCircleOutlinedIcon aria-hidden="true"/>
                <span>{user?.name}<br/><small>{user?.email}</small></span>
            </AccountMenuItem>
            <AccountMenuItem type="button" role="menuitem" onClick={() => {dispatch(closeNavigationPanels({collapseSidebar: false})); navigate(isCompanyAdmin ? "/users" : "/settings");}}>
                <SettingsOutlinedIcon aria-hidden="true"/>
                {isCompanyAdmin ? "Пользователи" : t("Настройки")}
            </AccountMenuItem>
            <AccountMenuItem type="button" role="menuitem" onClick={() => {dispatch(closeNavigationPanels({collapseSidebar: false})); navigate('/telegram-link');}}>
                <TelegramIcon aria-hidden="true"/>
                Мой Telegram
            </AccountMenuItem>
            <AccountMenuItem type="button" role="menuitem" onClick={signOut}>
                <LogoutOutlinedIcon aria-hidden="true"/>
                Выйти
            </AccountMenuItem>
        </AccountMenu>
    );
};

export default Accountbar;
