import {translate} from "../i18n";

const hasMessage = (value: unknown): value is string => typeof value === "string" && Boolean(value.trim());

export const getApiErrorMessage = (error: unknown, fallback: string) => {
    if (hasMessage(error)) {
        return error;
    }

    if (typeof error === "object" && error) {
        const errorWithData = error as {data?: unknown; error?: unknown; message?: unknown; status?: unknown; originalStatus?: number};

        if (errorWithData.status === "TIMEOUT_ERROR") return translate("Время ожидания ответа истекло. Проверьте результат операции перед повторной отправкой.");
        if (errorWithData.status === "FETCH_ERROR") return translate("Ответ сервера не получен. Проверьте соединение и результат операции перед повторной отправкой.");
        if (errorWithData.status === "PARSING_ERROR") {
            if (errorWithData.originalStatus && errorWithData.originalStatus >= 400 && errorWithData.originalStatus < 500 &&
                hasMessage(errorWithData.data) && errorWithData.data.length <= 4000 && !/<[^>]+>/.test(errorWithData.data)) return errorWithData.data;
            return translate("Не удалось прочитать ответ сервера. Обновите данные, чтобы проверить результат операции.");
        }
        if (errorWithData.error === "tenant.context_required") return translate("Выберите компанию для продолжения работы.");

        if (
            hasMessage(errorWithData.data) &&
            !/^\s*(?:<!doctype\s+html|<html)\b/i.test(errorWithData.data)
        ) {
            return errorWithData.data;
        }

        if (typeof errorWithData.data === "object" && errorWithData.data) {
            const data = errorWithData.data as {
                detail?: unknown;
                error?: unknown;
                message?: unknown;
                title?: unknown;
                errors?: unknown;
            };

            const validationErrors = data.errors && typeof data.errors === "object"
                ? Object.values(data.errors).flat().filter(hasMessage)
                : [];
            if (validationErrors.length) return validationErrors.join(" ");

            if (hasMessage(data.detail)) {
                return data.detail;
            }

            if (hasMessage(data.message)) {
                return data.message;
            }

            if (hasMessage(data.error)) {
                return data.error;
            }

            if (hasMessage(data.title)) {
                return data.title;
            }
        }

        if (hasMessage(errorWithData.error)) {
            return errorWithData.error;
        }

        if (hasMessage(errorWithData.message)) {
            return errorWithData.message;
        }
    }

    if (error instanceof Error && hasMessage(error.message)) {
        return error.message;
    }

    return fallback;
};
