import {goodsInvoicesApi} from "../components/transportWaybills/goodsInvoicesApi";
import {costingApi} from "../components/costing/costingApi";
import {operationsApi} from "../components/operations/operationsApi";
import {combineReducers, configureStore, createAction, UnknownAction} from "@reduxjs/toolkit";
import {setupListeners} from "@reduxjs/toolkit/query";
import {TypedUseSelectorHook, useDispatch, useSelector} from "react-redux";
import {menuSlice} from "../components/layout/menu/menuSlice";
import {orderSlice} from "../components/orders/orderSlice";
import {rtkQueryErrorLogger} from "../middleware/rtkQueryErrorLogger";
import {deliveryMethodsApi} from "../components/shared/deliveryMethod/deliveryMethodsApi";
import {sourcesApi} from "../components/shared/sources/sourceApi";
import {statusesApi} from "../components/shared/statuses/statusesApi";
import {paymentMethodsApi} from "../components/shared/paymentMethod/paymentMethodsApi";
import {categoriesApi} from "../components/categories/categoriesApi";
import {productsApi} from "../components/products/productsApi";
import {createOrderApi} from "../components/orders/createOrder/createOrderApi";
import {servicesApi} from "../components/services/servicesApi";
import {analyticsApi} from "../components/reports/analyticsApi";
import {usersApi} from "../components/users/usersApi";
import {authApi} from "../components/auth/authApi";
import {firmsApi} from "../components/firms/firmsApi";
import {stockApi} from "../components/stock/stockApi";
import {menuSettingsApi} from "../components/layout/menu/menuSettingsApi";
import {logisticsApi} from "../components/logistics/logisticsApi";
import {transportWaybillsApi} from "../components/transportWaybills/transportWaybillsApi";
import {testDataApi} from "../components/settings/testDataApi";
import {catalogGenerationApi} from "../components/catalogGeneration/catalogGenerationApi";
import {commercialOffersApi} from "../components/commercialOffers/commercialOffersApi";
import {warehouseReceiptsApi} from "../components/warehouse/warehouseReceiptsApi";
import {stockAlertsApi} from "../components/warehouse/stockAlertsApi";
import {collaborationApi} from "../components/collaboration/collaborationApi";
import {sharedDataInvalidation} from "../middleware/sharedDataInvalidation";
import {counterpartiesApi} from '../components/counterparties/counterpartiesApi';

const rootReducer = combineReducers({
    [counterpartiesApi.reducerPath]: counterpartiesApi.reducer,
    [costingApi.reducerPath]: costingApi.reducer,
    [operationsApi.reducerPath]: operationsApi.reducer,
    menu: menuSlice.reducer,
    order: orderSlice.reducer,
    [goodsInvoicesApi.reducerPath]: goodsInvoicesApi.reducer,
    [warehouseReceiptsApi.reducerPath]: warehouseReceiptsApi.reducer,
    [stockAlertsApi.reducerPath]: stockAlertsApi.reducer,
    [collaborationApi.reducerPath]: collaborationApi.reducer,
    [createOrderApi.reducerPath]: createOrderApi.reducer,
    [productsApi.reducerPath]:productsApi.reducer,
    [categoriesApi.reducerPath]:categoriesApi.reducer,
    [catalogGenerationApi.reducerPath]: catalogGenerationApi.reducer,
    [commercialOffersApi.reducerPath]: commercialOffersApi.reducer,
    [servicesApi.reducerPath]: servicesApi.reducer,
    [analyticsApi.reducerPath]: analyticsApi.reducer,
    [usersApi.reducerPath]: usersApi.reducer,
    [authApi.reducerPath]: authApi.reducer,
    [firmsApi.reducerPath]: firmsApi.reducer,
    [stockApi.reducerPath]: stockApi.reducer,
    [logisticsApi.reducerPath]: logisticsApi.reducer,
    [transportWaybillsApi.reducerPath]: transportWaybillsApi.reducer,
    [menuSettingsApi.reducerPath]: menuSettingsApi.reducer,
    [testDataApi.reducerPath]: testDataApi.reducer,
    [deliveryMethodsApi.reducerPath]: deliveryMethodsApi.reducer,
    [sourcesApi.reducerPath]: sourcesApi.reducer,
    [statusesApi.reducerPath]: statusesApi.reducer,
    [paymentMethodsApi.reducerPath]: paymentMethodsApi.reducer,
});

const sessionEnded = createAction("session/ended");
type StoreState = ReturnType<typeof rootReducer>;

export const store = configureStore({
    reducer: (state: StoreState | undefined, action: UnknownAction) =>
        rootReducer(sessionEnded.match(action) ? undefined : state, action),
    middleware: (getDefaultMiddleware) =>
        getDefaultMiddleware().concat([
            rtkQueryErrorLogger,
            counterpartiesApi.middleware,
            costingApi.middleware,
            operationsApi.middleware,
            sharedDataInvalidation,
            goodsInvoicesApi.middleware,
            warehouseReceiptsApi.middleware,
            stockAlertsApi.middleware,
            collaborationApi.middleware,
            deliveryMethodsApi.middleware,
            sourcesApi.middleware,
            statusesApi.middleware,
            paymentMethodsApi.middleware,
            catalogGenerationApi.middleware,
            commercialOffersApi.middleware,
            categoriesApi.middleware,
            productsApi.middleware,
            createOrderApi.middleware,
            servicesApi.middleware,
            analyticsApi.middleware,
            usersApi.middleware,
            authApi.middleware,
            firmsApi.middleware,
            stockApi.middleware,
            logisticsApi.middleware,
            transportWaybillsApi.middleware,
            menuSettingsApi.middleware,
            testDataApi.middleware
        ])
});

setupListeners(store.dispatch);

export const resetSessionState = () => {
    store.dispatch(sessionEnded());
    // resetApiState also releases RTK Query subscriptions and polling timers;
    // replacing reducer data alone would leave them attached to the old user.
    for (const api of [
        costingApi, operationsApi, goodsInvoicesApi, warehouseReceiptsApi,
        stockAlertsApi, collaborationApi, deliveryMethodsApi, sourcesApi,
        statusesApi, paymentMethodsApi, catalogGenerationApi, commercialOffersApi,
        categoriesApi, productsApi, createOrderApi, servicesApi, analyticsApi,
        usersApi, authApi, firmsApi, stockApi, logisticsApi, transportWaybillsApi,
        menuSettingsApi, testDataApi, counterpartiesApi,
    ]) {
        store.dispatch(api.util.resetApiState());
    }
};

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;

export const useAppDispatch = () => useDispatch<AppDispatch>();

export const useAppSelector: TypedUseSelectorHook<RootState> = useSelector;
