import {goodsInvoicesApi} from "../components/transportWaybills/goodsInvoicesApi";
import {costingApi} from "../components/costing/costingApi";
import {servicesApi} from "../components/services/servicesApi";
import {operationsApi} from "../components/operations/operationsApi";
import {commercialOffersApi} from "../components/commercialOffers/commercialOffersApi";
import {isAction, Middleware} from "@reduxjs/toolkit";
import {productsApi} from "../components/products/productsApi";
import {stockApi} from "../components/stock/stockApi";
import {createOrderApi} from "../components/orders/createOrder/createOrderApi";
import {analyticsApi} from "../components/reports/analyticsApi";
import {logisticsApi} from "../components/logistics/logisticsApi";
import {collaborationApi} from "../components/collaboration/collaborationApi";
import {warehouseReceiptsApi} from "../components/warehouse/warehouseReceiptsApi";
import {stockAlertsApi} from "../components/warehouse/stockAlertsApi";
import {catalogGenerationApi} from "../components/catalogGeneration/catalogGenerationApi";
import {categoriesApi} from "../components/categories/categoriesApi";
import {testDataApi} from "../components/settings/testDataApi";
import {usersApi} from "../components/users/usersApi";
import {transportWaybillsApi} from "../components/transportWaybills/transportWaybillsApi";

// Each API has its own cache. A successful write also refreshes related modules.
export const sharedDataInvalidation: Middleware = api => next => action => {
    const result = next(action);
    if (!isAction(action) || !action.type.endsWith("/executeMutation/fulfilled")) return result;
    const name = (action as {meta?: {arg?: {endpointName?: string}}}).meta?.arg?.endpointName ?? "";
    if (["originalGoodsInvoice", "analyzeProductFile", "previewProductFile", "generalRoom", "sendTeamMessage", "createTeamRoom", "createTeamTask", "updateTeamTask"].includes(name)) return result;
    const prefix = action.type.split("/")[0];
    if ([productsApi.reducerPath, servicesApi.reducerPath, catalogGenerationApi.reducerPath, testDataApi.reducerPath, warehouseReceiptsApi.reducerPath].some(path => path === prefix)
        || (prefix === goodsInvoicesApi.reducerPath && name === "approveGoodsInvoice")) api.dispatch(costingApi.util.invalidateTags(["Costing"]));
    if (prefix === createOrderApi.reducerPath || prefix === commercialOffersApi.reducerPath) api.dispatch(operationsApi.util.invalidateTags(["Operations", "Inbox"]));
    if (prefix === operationsApi.reducerPath && ["changeStage", "applyDiscount"].includes(name)) {
        api.dispatch(createOrderApi.util.invalidateTags(["Orders", "CreateOrder"]));
        api.dispatch(analyticsApi.util.invalidateTags(["Analytics"]));
        api.dispatch(logisticsApi.util.invalidateTags(["LogisticsTrips", "LogisticsTrip", "LogisticsMap", "Installers"]));
        api.dispatch(collaborationApi.util.invalidateTags(["References"]));
    }
    if ((prefix === goodsInvoicesApi.reducerPath && name === "approveGoodsInvoice") || [productsApi.reducerPath, stockApi.reducerPath, warehouseReceiptsApi.reducerPath, createOrderApi.reducerPath, catalogGenerationApi.reducerPath, categoriesApi.reducerPath, testDataApi.reducerPath].some(path => path === prefix)) {
        api.dispatch(productsApi.util.invalidateTags(["Products", "Product"]));
        api.dispatch(stockApi.util.invalidateTags(["Stock"]));
        api.dispatch(stockAlertsApi.util.invalidateTags(["StockAlerts"]));
        api.dispatch(warehouseReceiptsApi.util.invalidateTags(["Receipts"]));
        api.dispatch(goodsInvoicesApi.util.invalidateTags(["Invoices"]));
        api.dispatch(createOrderApi.util.invalidateTags(["Orders", "CreateOrder"]));
        api.dispatch(analyticsApi.util.invalidateTags(["Analytics"]));
    }
    if ([usersApi.reducerPath, createOrderApi.reducerPath, logisticsApi.reducerPath].some(path => path === prefix)) api.dispatch(logisticsApi.util.invalidateTags(["LogisticsTrips", "LogisticsTrip", "LogisticsMap", "Installers"]));
    if ([productsApi.reducerPath, createOrderApi.reducerPath, transportWaybillsApi.reducerPath, goodsInvoicesApi.reducerPath, warehouseReceiptsApi.reducerPath, usersApi.reducerPath, categoriesApi.reducerPath].some(path => path === prefix))
        api.dispatch(collaborationApi.util.invalidateTags(["References", "Users"]));
    return result;
};
