import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {PagedResponse} from "../../models/api";
import {
    BulkEditProductCountRequest,
    BulkEditProductCountResult,
    ISetProductForStock,
    ProductParams,
} from "../../models/product";
import {IStockProduct} from "./types";

const toStockQueryParams = (productParams: ProductParams) => {
    const {productCategories, categories, ...params} = productParams;

    return {
        ...params,
        categories: categories || productCategories?.join(",") || undefined,
    };
};

export const stockApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "stockApi",
    tagTypes: ["Stock"],
    baseQuery: createFirmBaseQuery("stock"),
    endpoints: (builder) => ({
        getStockInfo: builder.query<PagedResponse<IStockProduct>, ProductParams>({
            query: (productParams) => ({
                url: "",
                method: "GET",
                params: toStockQueryParams(productParams),
            }),
            providesTags: ["Stock"],
        }),
        editProductCount: builder.mutation<number, ISetProductForStock>({
            query: (productCount) => ({
                url: "",
                method: "PUT",
                body: productCount,
            }),
            invalidatesTags: ["Stock"],
        }),
        bulkEditProductCount: builder.mutation<BulkEditProductCountResult, BulkEditProductCountRequest>({
            query: (request) => ({
                url: "bulk-edit",
                method: "POST",
                body: request,
            }),
            invalidatesTags: ["Stock"],
        }),
    }),
});

export const {
    useBulkEditProductCountMutation,
    useEditProductCountMutation,
    useGetStockInfoQuery,
} = stockApi;
