import React from "react";
import {Alert, Button, CircularProgress} from "@mui/material";
import BusinessOutlinedIcon from "@mui/icons-material/BusinessOutlined";
import LogoutOutlinedIcon from "@mui/icons-material/LogoutOutlined";
import RefreshOutlinedIcon from "@mui/icons-material/RefreshOutlined";
import styledCom from "styled-components";
import {useAuth} from "../../auth/AuthContext";
import {Firm} from "../../models/auth";
import Image from "../../ui/images/logo-no-background.png";

const Page = styledCom.main({
    minHeight: "100dvh",
    display: "grid",
    placeItems: "center",
    padding: "clamp(16px, 4vw, 36px)",
    background: "linear-gradient(135deg, var(--color-page), var(--color-page-soft))",
});

const Panel = styledCom.section({
    width: "min(880px, 100%)",
    display: "grid",
    gap: "24px",
    padding: "clamp(22px, 5vw, 42px)",
    background: "var(--color-surface)",
    border: "1px solid var(--color-border)",
    borderRadius: "24px",
    boxShadow: "var(--shadow-popover)",
});

const Header = styledCom.header({
    display: "flex",
    alignItems: "flex-start",
    justifyContent: "space-between",
    gap: "20px",

    img: {width: "170px", maxWidth: "48vw"},

    "@media (max-width: 560px)": {
        alignItems: "stretch",
        flexDirection: "column",
    },
});

const Intro = styledCom.div({
    display: "grid",
    gap: "8px",

    h1: {
        margin: 0,
        color: "var(--color-text)",
        fontSize: "clamp(25px, 5vw, 34px)",
    },

    p: {
        margin: 0,
        color: "var(--color-muted)",
        lineHeight: 1.55,
    },
});

const FirmGrid = styledCom.div({
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(min(230px, 100%), 1fr))",
    gap: "14px",
});

const FirmButton = styledCom.button<{disabled?: boolean}>(({disabled}) => ({
    minHeight: "118px",
    display: "grid",
    gridTemplateColumns: "40px minmax(0, 1fr)",
    alignItems: "center",
    gap: "14px",
    padding: "18px",
    color: "var(--color-text)",
    textAlign: "left",
    background: disabled ? "var(--color-surface-soft)" : "var(--color-surface)",
    border: "1px solid var(--color-border)",
    borderRadius: "16px",
    cursor: disabled ? "not-allowed" : "pointer",
    opacity: disabled ? 0.62 : 1,
    transition: "border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease",

    "&:hover": disabled ? {} : {
        borderColor: "var(--color-primary)",
        boxShadow: "var(--shadow-popover)",
        transform: "translateY(-1px)",
    },

    svg: {
        color: disabled ? "var(--color-muted)" : "var(--color-primary)",
        fontSize: "34px",
    },

    strong: {
        display: "block",
        marginBottom: "5px",
        fontSize: "17px",
    },

    span: {
        display: "block",
        color: "var(--color-muted)",
        fontSize: "13px",
        lineHeight: 1.4,
    },
}));

const Center = styledCom.div({
    minHeight: "160px",
    display: "grid",
    placeItems: "center",
});

interface FirmSelectionPageProps {
    firms: Firm[];
    isLoading: boolean;
    isError: boolean;
    onRetry: () => void;
}

const FirmSelectionPage = ({firms, isLoading, isError, onRetry}: FirmSelectionPageProps) => {
    const {user, switchFirm, signOut} = useAuth();

    return (
        <Page>
            <Panel>
                <Header>
                    <img src={Image} alt="VivoTech CRM"/>
                    <Button startIcon={<LogoutOutlinedIcon/>} onClick={signOut}>
                        Выйти
                    </Button>
                </Header>

                <Intro>
                    <h1>Выберите компанию</h1>
                    <p>
                        {user?.name ? `${user.name}, ` : ""}
                        выберите рабочий контекст. После выбора откроется привычное меню,
                        а все данные будут отфильтрованы по этой компании.
                    </p>
                </Intro>

                {isLoading ? (
                    <Center><CircularProgress/></Center>
                ) : isError ? (
                    <Alert
                        severity="error"
                        action={
                            <Button color="inherit" startIcon={<RefreshOutlinedIcon/>} onClick={onRetry}>
                                Повторить
                            </Button>
                        }
                    >
                        Не удалось загрузить список компаний.
                    </Alert>
                ) : firms.length === 0 ? (
                    <Alert severity="warning">Нет доступных компаний.</Alert>
                ) : (
                    <FirmGrid>
                        {firms.map((firm) => (
                            <FirmButton
                                key={firm.id}
                                type="button"
                                disabled={firm.isBlocked}
                                onClick={() => !firm.isBlocked && switchFirm(firm.id)}
                            >
                                <BusinessOutlinedIcon/>
                                <span>
                                    <strong>{firm.name}</strong>
                                    <span>
                                        {firm.isBlocked
                                            ? "Доступ заблокирован"
                                            : firm.address || `${firm.activeUserCount} пользователей`}
                                    </span>
                                </span>
                            </FirmButton>
                        ))}
                    </FirmGrid>
                )}
            </Panel>
        </Page>
    );
};

export default FirmSelectionPage;
