import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {AuthUser, UpsertUser, UserRole} from "../../models/auth";

export const usersApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "usersApi",
    tagTypes: ["Users"],
    baseQuery: createFirmBaseQuery("users"),
    endpoints: (builder) => ({
        getUsers: builder.query<AuthUser[], void>({
            query: () => "",
            providesTags: ["Users"],
        }),
        getRoles: builder.query<UserRole[], void>({
            query: () => "roles",
        }),
        createUser: builder.mutation<AuthUser, UpsertUser>({
            query: (body) => ({url: "", method: "POST", body}),
            invalidatesTags: ["Users"],
        }),
        updateUser: builder.mutation<AuthUser, {id: number; body: UpsertUser}>({
            query: ({id, body}) => ({url: String(id), method: "PUT", body}),
            invalidatesTags: ["Users"],
        }),
        deleteUser: builder.mutation<void, number>({
            query: (id) => ({url: String(id), method: "DELETE"}),
            invalidatesTags: ["Users"],
        }),
    }),
});

export const {
    useGetUsersQuery,
    useGetRolesQuery,
    useCreateUserMutation,
    useUpdateUserMutation,
    useDeleteUserMutation,
} = usersApi;
