import {isRejectedWithValue, Middleware} from "@reduxjs/toolkit";
import {toast} from "react-toastify";
import {getApiErrorMessage} from "../api/errors";
import {translate} from "../i18n";

export const rtkQueryErrorLogger: Middleware = () => {
    const failedQueries = new Map<string, string>();
    return (next) => (action) => {
        const result = next(action);
        const event = action as {type?: string; meta?: {arg?: {type?: string; queryCacheKey?: string}}; payload?: {status?: unknown; queryCacheKey?: string}};
        if (typeof event.type !== "string") return result;
        const request = event.meta?.arg;
        const payload = event.payload;
        // Chat polling reports connection state inline and recovers automatically.
        // A persistent toast for the same background request obscures sent messages.
        if (event.type.startsWith('collaborationApi/')) return result;
        const removed = event.type.endsWith('/queries/removeQueryResult');
        const queryCacheKey = request?.queryCacheKey || (removed ? payload?.queryCacheKey : undefined);
        const key = queryCacheKey ? `${event.type.split("/")[0]}:${queryCacheKey}` : "";
        if (key && (event.type.endsWith("/fulfilled") || removed)) {
            const message = failedQueries.get(key);
            failedQueries.delete(key);
            if (message && !Array.from(failedQueries.values()).includes(message)) toast.dismiss(`query-error:${message}`);
        }
        if (event.type.endsWith("/resetApiState")) {
            failedQueries.forEach(message => toast.dismiss(`query-error:${message}`));
            failedQueries.clear();
        }
        // Mutations report their specific result in the action handler. Queries
        // also need feedback when a page or a background refresh cannot load data.
        if (isRejectedWithValue(action) && request?.type === "query" && payload?.status !== 401 && (!key || !failedQueries.has(key))) {
            const message = getApiErrorMessage(action.payload, translate("Не удалось загрузить данные. Повторите запрос."));
            if (key) failedQueries.set(key, message);
            toast.error(message, {toastId: `query-error:${message}`, autoClose: false});
        }
        return result;
    };
};
