import React, {FormEvent, useState} from 'react';
import {Alert, Button, Container, Paper, Stack, TextField, Typography} from '@mui/material';
import {useChangePasswordMutation} from '../components/auth/authApi';
import {useTranslation} from '../i18n';
import {getApiErrorMessage} from '../api/errors';
import {useAuth} from './AuthContext';
import messages from './passwordMessages.json';

export default function ChangePasswordPage() {
    const {language} = useTranslation();
    const copy = messages[language];
    const {signIn, signOut} = useAuth();
    const [changePassword, {isLoading}] = useChangePasswordMutation();
    const [currentPassword, setCurrentPassword] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmation, setConfirmation] = useState('');
    const [error, setError] = useState('');
    const submit = async (event: FormEvent) => {
        event.preventDefault();
        if (confirmation !== newPassword) {
            setError(copy.mismatch);
            return;
        }
        setError('');
        try {
            signIn(await changePassword({currentPassword, newPassword}).unwrap());
        } catch (failure) {
            setError(getApiErrorMessage(failure, copy.failed));
        }
    };
    return <Container maxWidth="sm" sx={{py: 6}}>
        <Paper component="main" sx={{p: {xs: 3, sm: 5}}}>
            <Stack component="form" aria-labelledby="password-change-title" onSubmit={submit} spacing={3}>
                <Typography id="password-change-title" component="h1" variant="h5">{copy.title}</Typography>
                <Typography>{copy.description}</Typography>
                {error && <Alert severity="error">{error}</Alert>}
                <TextField required type="password" label={copy.current} autoComplete="current-password" value={currentPassword} onChange={event => setCurrentPassword(event.target.value)}/>
                <TextField required type="password" label={copy.next} autoComplete="new-password" inputProps={{minLength: 16, maxLength: 1024}} value={newPassword} onChange={event => setNewPassword(event.target.value)}/>
                <TextField required type="password" label={copy.confirm} autoComplete="new-password" value={confirmation} onChange={event => setConfirmation(event.target.value)}/>
                <Button type="submit" variant="contained" disabled={isLoading}>{isLoading ? copy.saving : copy.save}</Button>
                <Button onClick={signOut}>{copy.exit}</Button>
            </Stack>
        </Paper>
    </Container>;
}
