import React from "react";
import {Button} from "@mui/material";
import LogoutOutlinedIcon from "@mui/icons-material/LogoutOutlined";
import ArrowForwardRoundedIcon from "@mui/icons-material/ArrowForwardRounded";
import AppearancePicker from "../../ui/appearance/AppearancePicker";
import styledCom from "styled-components";
import {AuthUser} from "../../models/auth";
import Image from "../../ui/images/logo-no-background.png";

import {modules, Workspace} from "./modules";
import {moduleIcons} from "./moduleIcons";
export type {Workspace} from "./modules";

const WORKSPACE_STORAGE_KEY = "vivotech.activeWorkspace";

export const readWorkspace = (): Workspace | null => {
    const value = window.sessionStorage.getItem(WORKSPACE_STORAGE_KEY);
    return value && Object.prototype.hasOwnProperty.call(modules, value) ? value as Workspace : null;
};

export const saveWorkspace = (workspace: Workspace | null) => {
    if (workspace) {
        window.sessionStorage.setItem(WORKSPACE_STORAGE_KEY, workspace);
    } else {
        window.sessionStorage.removeItem(WORKSPACE_STORAGE_KEY);
    }
};

