import React, {CSSProperties, useState} from "react";
import {Box, Button, Dialog, DialogContent, DialogTitle, IconButton, ToggleButton, ToggleButtonGroup, Tooltip, Typography} from "@mui/material";
import PaletteOutlinedIcon from "@mui/icons-material/PaletteOutlined";
import CheckRoundedIcon from "@mui/icons-material/CheckRounded";
import CloseRoundedIcon from "@mui/icons-material/CloseRounded";
import LightModeOutlinedIcon from "@mui/icons-material/LightModeOutlined";
import DarkModeOutlinedIcon from "@mui/icons-material/DarkModeOutlined";
import DesktopWindowsOutlinedIcon from "@mui/icons-material/DesktopWindowsOutlined";
import {useAppThemeMode} from "../../themeMode";
import {getThemeColors, themePresets} from "../../themePresets";
import "./appearance.css";

export default function AppearancePicker({label = false, native = false}: {label?: boolean; native?: boolean}) {
    const [open, setOpen] = useState(false);
    const {mode, colorMode, palette, density, setAppearance} = useAppThemeMode();
    const preset = themePresets.find(item => item.mode === mode && item.palette === palette);
    const triggerProps = {onClick: () => setOpen(true), "aria-label": "Оформление интерфейса", "aria-haspopup": "dialog" as const, "aria-expanded": open};

    return <>
        <Tooltip title="Оформление интерфейса">
            {native ? <button type="button" {...triggerProps} className="icon-button"><PaletteOutlinedIcon/></button> : label ? <Button {...triggerProps} variant="outlined" startIcon={<PaletteOutlinedIcon/>}>Оформление</Button> :
                <IconButton {...triggerProps} sx={{width: 40, height: 40, bgcolor: "background.paper", border: "1px solid", borderColor: "divider"}}><PaletteOutlinedIcon fontSize="small"/></IconButton>}
        </Tooltip>
        <Dialog open={open} onClose={() => setOpen(false)} fullWidth maxWidth="sm" aria-labelledby="appearance-title"
            PaperProps={{sx: {m: {xs: 2, sm: 4}, width: {xs: "calc(100% - 32px)", sm: "calc(100% - 64px)"}}}}>
            <DialogTitle component="div" sx={{display: "flex", alignItems: "flex-start", gap: 2}}>
                <Box sx={{flex: 1}}><Typography component="h2" id="appearance-title" variant="h5">Ваше пространство</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{mt: .5}}>Выберите настроение, в котором приятно работать.</Typography></Box>
                <IconButton aria-label="Закрыть оформление" onClick={() => setOpen(false)}><CloseRoundedIcon/></IconButton>
            </DialogTitle>
            <DialogContent>
                <Typography component="h3" variant="subtitle2" sx={{mb: 1}}>Режим</Typography>
                <ToggleButtonGroup fullWidth exclusive value={colorMode} aria-label="Режим оформления" onChange={(_, next) => next && setAppearance({colorMode: next})}
                    sx={{mb: 2.5, "& .MuiToggleButton-root": {flex: 1, minWidth: 0, px: {xs: .75, sm: 2}, fontSize: {xs: 12, sm: 13}},
                        "@media (max-width: 360px)": {"& .MuiSvgIcon-root": {display: "none"}}}}>
                    <ToggleButton value="light"><LightModeOutlinedIcon fontSize="small" sx={{mr: .75}}/>Светлый</ToggleButton>
                    <ToggleButton value="dark"><DarkModeOutlinedIcon fontSize="small" sx={{mr: .75}}/>Тёмный</ToggleButton>
                    <ToggleButton value="system"><DesktopWindowsOutlinedIcon fontSize="small" sx={{mr: .75}}/>Авто</ToggleButton>
                </ToggleButtonGroup>
                <Typography component="h3" variant="subtitle2" sx={{mb: 1}}>Темы</Typography>
                <div className="appearance-grid" role="group" aria-label="Темы интерфейса">
                    {themePresets.map(item => {
                        const c = getThemeColors(item.mode, item.palette);
                        const selected = palette === item.palette && mode === item.mode;
                        return <button key={`${item.palette}-${item.mode}`} type="button" className={`appearance-card ${selected ? "is-selected" : ""}`}
                            aria-label={`Тема ${item.name}`} aria-pressed={selected}
                            onClick={() => setAppearance({palette: item.palette, colorMode: colorMode === "system" && mode === item.mode ? "system" : item.mode})}>
                            <div className="appearance-preview" aria-hidden="true" style={{"--preview-page": c.page, "--preview-paper": c.paper, "--preview-soft": c.paperSoft, "--preview-border": c.border, "--preview-accent": c.primary} as CSSProperties}>
                                <div className="preview-top"><i/><i/><i/></div>
                                <div className="preview-layout"><div className="preview-nav"><i/><i/><i/></div><div className="preview-content"><div className="preview-title"/><div className="preview-stats"><i/><i/><i/></div><div className="preview-table"><i/><i/><i/></div></div></div>
                            </div>
                            <span className="appearance-card-label"><strong>{item.name}</strong>{selected && <CheckRoundedIcon aria-hidden="true" sx={{fontSize: 18}}/>}</span>
                            <span className="appearance-card-description">{item.description}</span>
                        </button>;
                    })}
                </div>
                <Box sx={{mt: 3, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 2, flexWrap: "wrap"}}>
                    <Box><Typography component="h3" variant="subtitle2">Плотность интерфейса</Typography><Typography variant="caption" color="text.secondary">Больше воздуха или больше данных.</Typography></Box>
                    <ToggleButtonGroup size="small" exclusive value={density} aria-label="Плотность интерфейса" onChange={(_, next) => next && setAppearance({density: next})}>
                        <ToggleButton value="comfortable">Комфортная</ToggleButton><ToggleButton value="compact">Компактная</ToggleButton>
                    </ToggleButtonGroup>
                </Box>
                <Box sx={{mt: 3, pt: 2, borderTop: "1px solid", borderColor: "divider", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 2}}>
                    <Typography variant="caption" color="text.secondary" role="status">{preset?.name} · настройки сохранены</Typography><Button variant="contained" onClick={() => setOpen(false)}>Готово</Button>
                </Box>
            </DialogContent>
        </Dialog>
    </>;
}
