import {alpha, createTheme} from "@mui/material/styles";
import {enUS, plPL, ruRU} from "@mui/material/locale";
import {Language} from "./i18n/translations";
import type {} from "@mui/x-data-grid/themeAugmentation";
import {AppDensity, AppPalette, AppThemeMode, getThemeColors} from "./themePresets";

export type {AppThemeMode} from "./themePresets";

export const getAppTheme = (mode: AppThemeMode, palette: AppPalette = "violet", density: AppDensity = "comfortable", language: Language = "ru") => {
    const c = getThemeColors(mode, palette);
    const compact = density === "compact";
    const ring = `0 0 0 3px ${alpha(c.primary, .2)}`;
    return createTheme({
        palette: {
            mode,
            primary: {main: c.primary, dark: c.primaryHover, light: c.primarySoft, contrastText: c.onPrimary},
            secondary: {main: c.secondary, dark: c.secondaryHover, contrastText: mode === "dark" ? "#181421" : "#fff"},
            success: {main: c.success, dark: c.successHover, light: c.successSoft, contrastText: c.onPrimary},
            warning: {main: c.warning, dark: c.warningHover, light: c.warningSoft, contrastText: c.onPrimary},
            error: {main: c.danger, dark: c.dangerHover, light: c.dangerSoft, contrastText: c.onPrimary},
            info: {main: c.primary, light: c.primarySoft, contrastText: c.onPrimary},
            text: {primary: c.text, secondary: c.muted, disabled: c.disabledText},
            background: {default: c.page, paper: c.paper}, divider: c.border,
            action: {hover: alpha(c.primary, .06), selected: alpha(c.primary, .1), focus: alpha(c.primary, .16), disabled: c.disabledText, disabledBackground: c.disabled},
        },
        shape: {borderRadius: 12},
        typography: {
            fontFamily: '"Manrope", "Segoe UI", -apple-system, BlinkMacSystemFont, sans-serif',
            h1: {fontSize: "36px", fontWeight: 800, lineHeight: 1.16, letterSpacing: "-.045em"},
            h2: {fontSize: "28px", fontWeight: 800, lineHeight: 1.2, letterSpacing: "-.035em"},
            h3: {fontSize: "22px", fontWeight: 750, lineHeight: 1.3, letterSpacing: "-.025em"},
            h4: {fontSize: "24px", fontWeight: 800, letterSpacing: "-.03em"},
            h5: {fontSize: "21px", fontWeight: 750, letterSpacing: "-.025em"},
            h6: {fontSize: "18px", fontWeight: 750, letterSpacing: "-.02em"},
            body1: {fontSize: "14px", lineHeight: 1.65}, body2: {fontSize: "13px", lineHeight: 1.65},
            subtitle1: {fontSize: "14px", fontWeight: 700}, subtitle2: {fontSize: "13px", fontWeight: 700},
            button: {fontSize: "13px", fontWeight: 700, textTransform: "none", letterSpacing: 0},
            caption: {fontSize: "12px", lineHeight: 1.5},
        },
        components: {
            MuiCssBaseline: {styleOverrides: {body: {background: c.page, color: c.text}, "::selection": {background: alpha(c.primary, .22)}}},
            MuiButton: {defaultProps: {disableElevation: true}, styleOverrides: {
                root: {minHeight: compact ? 36 : 42, borderRadius: 10, padding: "9px 16px", lineHeight: 1.4,
                    transition: "background-color 160ms, border-color 160ms, box-shadow 160ms", "&.Mui-focusVisible": {outline: `2px solid ${c.primary}`, outlineOffset: 3},
                    "&.Mui-disabled": {backgroundColor: c.disabled, color: c.disabledText}},
                containedPrimary: {boxShadow: `0 2px 3px ${alpha(c.primary, .12)}, inset 0 1px 0 rgba(255,255,255,.12)`, "&:hover": {backgroundColor: c.primaryHover}},
                outlined: {borderColor: c.borderStrong, "&:hover": {backgroundColor: c.primarySoft, borderColor: c.primary}},
                sizeSmall: {minHeight: 32, padding: "5px 10px", fontSize: 12}, sizeLarge: {minHeight: 48, padding: "12px 22px"},
            }},
            MuiIconButton: {styleOverrides: {root: {borderRadius: 10, color: c.muted, "&:hover": {backgroundColor: c.paperSoft, color: c.primary}, "&.Mui-focusVisible": {outline: `2px solid ${c.primary}`, outlineOffset: 2}}}},
            MuiFormControl: {styleOverrides: {root: {minWidth: 0, maxWidth: "100%", verticalAlign: "top"}}},
            MuiInputBase: {styleOverrides: {root: {minWidth: 0, maxWidth: "100%"}, input: {minWidth: 0}}},
            MuiOutlinedInput: {styleOverrides: {
                root: {borderRadius: 10, backgroundColor: c.paper, fontSize: 14,
                    "& .MuiOutlinedInput-notchedOutline": {borderColor: c.borderStrong}, "&:hover .MuiOutlinedInput-notchedOutline": {borderColor: c.muted},
                    "&.Mui-focused": {boxShadow: ring}, "&.Mui-focused .MuiOutlinedInput-notchedOutline": {borderColor: c.primary, borderWidth: 1},
                    "&.Mui-error .MuiOutlinedInput-notchedOutline": {borderColor: c.danger}, "&.Mui-disabled": {backgroundColor: c.paperSoft}},
                input: {padding: compact ? "12px 14px" : "15px 14px", "&.MuiInputBase-inputSizeSmall": {padding: compact ? "9px 12px" : "11px 12px"},
                    "&.MuiInputBase-inputMultiline": {padding: 0}},
                notchedOutline: {top: 0, "& legend": {display: "none"}},
            }},
            MuiInputLabel: {defaultProps: {shrink: true}, styleOverrides: {
                root: {position: "static", transform: "none", maxWidth: "100%", marginBottom: 8, whiteSpace: "normal", overflowWrap: "anywhere",
                    color: c.muted, fontSize: 13, lineHeight: 1.45, fontWeight: 600, pointerEvents: "auto", transition: "color 160ms",
                    "&.Mui-focused": {color: c.primary}},
            }},
            MuiFormHelperText: {styleOverrides: {root: {margin: "8px 2px 0", fontSize: 12, lineHeight: 1.5, whiteSpace: "normal", overflowWrap: "anywhere"}}},
            MuiInputAdornment: {styleOverrides: {root: {color: c.muted}}},
            MuiPaper: {styleOverrides: {root: {backgroundImage: "none", backgroundColor: c.paper}, rounded: {borderRadius: 16}, elevation1: {boxShadow: c.shadowSoft}}},
            MuiCard: {styleOverrides: {root: {border: `1px solid ${c.border}`, boxShadow: c.shadowSoft}}},
            MuiMenu: {styleOverrides: {paper: {marginTop: 6, padding: 4, border: `1px solid ${c.border}`, borderRadius: 14, boxShadow: c.shadowPopover}}},
            MuiMenuItem: {styleOverrides: {root: {minHeight: 40, borderRadius: 8, margin: "2px 0", fontSize: 13, "&.Mui-selected, &.Mui-selected:hover": {backgroundColor: c.primarySoft, color: c.primary}}}},
            MuiAutocomplete: {styleOverrides: {paper: {border: `1px solid ${c.border}`, boxShadow: c.shadowPopover}, option: {borderRadius: 8, margin: "2px 6px"}}},
            MuiDialog: {styleOverrides: {paper: {borderRadius: 22, border: `1px solid ${c.border}`, boxShadow: c.shadowPopover}}},
            MuiDialogTitle: {styleOverrides: {root: {minWidth: 0, padding: "24px 24px 16px", fontWeight: 750, fontSize: 20, letterSpacing: "-.025em", overflowWrap: "anywhere", "& > .MuiBox-root": {minWidth: 0}}}},
            MuiDialogContent: {styleOverrides: {root: {padding: "16px 24px 24px"}}},
            MuiDialogActions: {styleOverrides: {root: {padding: "16px 24px", gap: 8, flexWrap: "wrap", borderTop: `1px solid ${c.border}`}}},
            MuiBackdrop: {styleOverrides: {root: {backgroundColor: "rgba(16, 13, 26, .48)", backdropFilter: "blur(4px)"}}},
            MuiDrawer: {styleOverrides: {paper: {boxShadow: c.shadowPopover}}},
            MuiTooltip: {styleOverrides: {tooltip: {fontSize: 12, padding: "8px 12px", borderRadius: 8, backgroundColor: mode === "dark" ? "#f0edf8" : "#292638", color: mode === "dark" ? "#292638" : "#fff"}}},
            MuiChip: {styleOverrides: {root: {borderRadius: 7, fontSize: 12, fontWeight: 650, height: 28}, sizeSmall: {height: 24}, colorPrimary: {backgroundColor: c.primarySoft, color: c.primary}, colorSuccess: {backgroundColor: c.successSoft, color: c.success}, colorWarning: {backgroundColor: c.warningSoft, color: c.warning}, colorError: {backgroundColor: c.dangerSoft, color: c.danger}}},
            MuiAlert: {styleOverrides: {root: {borderRadius: 12, fontSize: 13, alignItems: "center"}, standardSuccess: {backgroundColor: c.successSoft, color: c.success}, standardError: {backgroundColor: c.dangerSoft, color: c.danger}, standardWarning: {backgroundColor: c.warningSoft, color: c.warning}, standardInfo: {backgroundColor: c.primarySoft, color: c.primary}}},
            MuiTabs: {styleOverrides: {root: {minHeight: 44}, indicator: {height: 3, borderRadius: "3px 3px 0 0"}}},
            MuiTab: {styleOverrides: {root: {minHeight: 44, fontSize: 13, textTransform: "none", fontWeight: 650, color: c.muted}}},
            MuiToggleButtonGroup: {styleOverrides: {root: {padding: 4, gap: 4, backgroundColor: c.paperSoft, borderRadius: 12}, grouped: {border: "0 !important", borderRadius: "8px !important", margin: "0 !important"}}},
            MuiToggleButton: {styleOverrides: {root: {minHeight: 36, fontSize: 13, textTransform: "none", color: c.muted, "&.Mui-selected, &.Mui-selected:hover": {backgroundColor: c.paper, color: c.primary, boxShadow: c.shadowSoft}}}},
            MuiTableContainer: {styleOverrides: {root: {borderRadius: 14}}},
            MuiTableCell: {styleOverrides: {root: {borderColor: c.border, padding: compact ? "10px 14px" : "14px 16px", fontSize: 13}, head: {backgroundColor: c.paperSoft, color: c.muted, fontSize: 12, fontWeight: 700}, body: {fontVariantNumeric: "tabular-nums"}}},
            MuiTableRow: {styleOverrides: {root: {"&.MuiTableRow-hover:hover": {backgroundColor: c.paperSoft}}}},
            MuiDataGrid: {defaultProps: {rowHeight: compact ? 44 : 56, columnHeaderHeight: 48}, styleOverrides: {
                root: {border: `1px solid ${c.border}`, borderRadius: 14, backgroundColor: c.paper, color: c.text, fontSize: 13,
                    "& .MuiDataGrid-cell:focus, & .MuiDataGrid-cell:focus-within, & .MuiDataGrid-columnHeader:focus, & .MuiDataGrid-columnHeader:focus-within": {outline: `2px solid ${c.primary}`, outlineOffset: -2},
                    "& .MuiDataGrid-columnSeparator": {color: c.border}, "& .MuiDataGrid-virtualScroller": {scrollbarWidth: "thin"}, "& .MuiDataGrid-selectedRowCount": {color: c.primary}},
                columnHeaders: {backgroundColor: c.paperSoft, borderBottom: `1px solid ${c.border}`, color: c.muted, fontSize: 12}, columnHeaderTitle: {fontWeight: 700},
                cell: {borderBottom: `1px solid ${c.border}`, fontVariantNumeric: "tabular-nums"}, row: {"&:hover": {backgroundColor: c.paperSoft}, "&.Mui-selected, &.Mui-selected:hover": {backgroundColor: c.primarySoft}},
                footerContainer: {minHeight: 56, borderTop: `1px solid ${c.border}`}, toolbarContainer: {padding: 12, gap: 8},
            }},
            MuiPaginationItem: {styleOverrides: {root: {borderRadius: 9, fontWeight: 650, "&.Mui-selected, &.Mui-selected:hover": {backgroundColor: c.primarySoft, color: c.primary}}}},
            MuiLinearProgress: {styleOverrides: {root: {borderRadius: 4, backgroundColor: c.primarySoft}}},
            MuiSkeleton: {styleOverrides: {root: {backgroundColor: c.paperSoft, borderRadius: 8}}},
        },
    }, {ru: ruRU, en: enUS, pl: plPL, lt: enUS}[language]);
};

export const theme = getAppTheme("light");
