import {GridRowId} from "@mui/x-data-grid";
import {createApi} from '@reduxjs/toolkit/query/react'
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../../api/baseQuery";
import {PagedResponse} from "../../../models/api";
import {ICreateOrEditOrder, IReadOrder, IReadOrderDetails, OrderParams} from "../../../models/order";
import {IShortProduct} from "../../../models/product";
import {IServiceShort} from "../../../models/service";
import {BulkDeleteRequest, BulkDeleteResult} from "../../../models/bulkDelete";
import {AddCustomerNoteInput, ICustomerDetail, ICustomerPage, ICustomerOrdersPage, ICustomerNotesPage, SaveCustomerInput} from "../../../models/customer";

const toOrderQueryParams = (orderParams: OrderParams) => {
    const {orderStatuses, ...params} = orderParams;

    return {
        ...params,
        orderStatuses: orderStatuses.join(",") || undefined,
    };
};

export const createOrderApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: 'createOrder',
    tagTypes:['CreateOrder', 'Orders', 'Customers'],
    baseQuery: createFirmBaseQuery(),
    endpoints: (builder) => ({
        getOrderCustomers: builder.query<ICustomerPage, {search?: string; page?: number; pageSize?: number; attentionRequired?: boolean; phone?: string}>({
            query: (params) => ({url: 'customers', params}), providesTags: ['Customers'],
        }),
        getCustomer: builder.query<ICustomerDetail, number>({
            query: id => `customers/${id}`, providesTags: ['Customers'],
        }),
        getCustomerOrders: builder.query<ICustomerOrdersPage, {id: number; page: number}>({
            query: ({id, page}) => ({url: `customers/${id}/orders`, params: {page, pageSize: 20}}), providesTags: ['Customers'],
        }),
        getCustomerNotes: builder.query<ICustomerNotesPage, {id: number; page: number}>({
            query: ({id, page}) => ({url: `customers/${id}/notes`, params: {page}}), providesTags: ['Customers'],
        }),
        saveCustomer: builder.mutation<ICustomerDetail, SaveCustomerInput & {id?: number}>({
            query: ({id, ...body}) => ({url: id ? `customers/${id}` : 'customers', method: id ? 'PUT' : 'POST', body}), invalidatesTags: ['Customers'],
        }),
        addCustomerNote: builder.mutation<number, AddCustomerNoteInput>({
            query: ({customerId, ...body}) => ({url: `customers/${customerId}/notes`, method: 'POST', body}), invalidatesTags: ['Customers'],
        }),
        resolveCustomerNote: builder.mutation<boolean, {customerId: number; noteId: number}>({
            query: ({customerId, noteId}) => ({url: `customers/${customerId}/notes/${noteId}/resolve`, method: 'PUT'}), invalidatesTags: ['Customers'],
        }),
        getOrders: builder.query<PagedResponse<IReadOrder>, OrderParams>({
            query: (orderParams) => ({
                url: 'orders',
                method: 'GET',
                params: toOrderQueryParams(orderParams),
            }),
            providesTags: ['Orders'],
        }),
        getOrderById: builder.query<IReadOrderDetails, string | number>({
            query: (id) => ({
                url: `orders/${id}`,
                method: 'GET'
            }),
            providesTags: ['CreateOrder'],
        }),
        getOrderProductOptions: builder.query<IShortProduct[], string | {searchTerm: string; excludedIds?: string}>({
            query: (input) => ({
                url: 'products/search',
                method: 'GET',
                params: typeof input === 'string' ? {searchTerm: input} : input,
            }),
        }),
        getOrderServiceOptions: builder.query<IServiceShort[], string>({
            query: (searchTerm: string) => ({
                url: 'services/search',
                method: 'GET',
                params: {searchTerm}
            }),
        }),
        createOrder: builder.mutation<number, ICreateOrEditOrder>({
            query: (order: ICreateOrEditOrder) => ({
                url: `orders`,
                method: 'POST',
                body: order,
            }),
            invalidatesTags:['CreateOrder', 'Orders', 'Customers']
        }),
        editOrder: builder.mutation<number, ICreateOrEditOrder>({
            query: (order: ICreateOrEditOrder) => ({
                url: `orders/${order.id}`,
                method: 'PUT',
                body: order
            }),
            invalidatesTags:['CreateOrder', 'Orders', 'Customers']
        }),
        changeOrderStatus: builder.mutation<number, { orderId: number; orderStatusId: number | string }>({
            query: ({orderId, orderStatusId}) => ({
                url: `orders/order-status/${orderId}`,
                method: 'PUT',
                body: JSON.stringify(Number(orderStatusId)),
                headers: {'Content-Type': 'application/json'},
            }),
            invalidatesTags: ['Orders', 'CreateOrder'],
        }),
        deleteOrder: builder.mutation<number, GridRowId>({
            query: (id: GridRowId) => ({
                url: `orders/${id}`,
                method: 'DELETE'
            }),
            invalidatesTags:['CreateOrder', 'Orders', 'Customers']
        }),
        bulkDeleteOrders: builder.mutation<BulkDeleteResult, BulkDeleteRequest>({
            query: (request) => ({
                url: 'orders/bulk-delete',
                method: 'POST',
                body: request,
            }),
            invalidatesTags: ['CreateOrder', 'Orders'],
        }),
    }),
})

export const {
    useGetOrderCustomersQuery,
    useGetCustomerQuery,
    useGetCustomerOrdersQuery, useGetCustomerNotesQuery, useSaveCustomerMutation, useAddCustomerNoteMutation, useResolveCustomerNoteMutation,
   useCreateOrderMutation,
    useBulkDeleteOrdersMutation,
    useDeleteOrderMutation,
    useEditOrderMutation,
    useChangeOrderStatusMutation,
    useGetOrdersQuery,
    useGetOrderByIdQuery,
    useGetOrderProductOptionsQuery,
    useGetOrderServiceOptionsQuery
} = createOrderApi;
