import {createSlice, PayloadAction} from "@reduxjs/toolkit";
import {RootState} from "../../../store/store";

interface MenuSlice {
    isSidebarOpen: boolean,
    isAccountbarOpen:boolean
}

export const menuSlice = createSlice({
    name: 'sidebar',
    initialState: {
        isSidebarOpen: true,
        isAccountbarOpen:false
    } as MenuSlice,
    reducers: {
        openCloseSidebar: (state, action) => {
            state.isSidebarOpen = !state.isSidebarOpen;
        },
        openCloseAccountbar: (state, action) => {
            state.isAccountbarOpen = !state.isAccountbarOpen;
        },
        closeNavigationPanels: (state, action: PayloadAction<{collapseSidebar: boolean}>) => {
            state.isAccountbarOpen = false;
            if (action.payload.collapseSidebar) state.isSidebarOpen = false;
        },
    },
    extraReducers: (builder => {

    })
})

export const menuSelectors = ((state: RootState) => state.menu);
export const {openCloseSidebar,openCloseAccountbar,closeNavigationPanels} = menuSlice.actions;
