import {GridRowId} from "@mui/x-data-grid";
import {createApi} from '@reduxjs/toolkit/query/react'
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../../api/baseQuery";
import {ICreateStatus, IStatus} from "../../../models/status";

export const statusesApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: 'statuses',
    tagTypes: ['Statuses'],
    baseQuery: createFirmBaseQuery('statuses'),
    endpoints: (builder) => ({
        getStatuses: builder.query<IStatus[], void | Record<string, never>>({
            query: () => ({
                url: '',
                method: 'GET'
            }),
            providesTags: ['Statuses']
        }),
        getStatusById: builder.query<IStatus, string | number>({
            query: (id) => ({
                url: `${id}`,
                method: 'GET'
            }),
        }),
        createStatus: builder.mutation<number, ICreateStatus>({
            query: (status: ICreateStatus) => ({
                url: ``,
                method: 'POST',
                body: status,
            }),
            invalidatesTags: ['Statuses']
        }),
        editStatus: builder.mutation<number, IStatus>({
            query: (status: IStatus) => ({
                url: ``,
                method: 'PUT',
                body: status
            }),
            invalidatesTags: ['Statuses']
        }),
        deleteStatus: builder.mutation<number, GridRowId>({
            query: (id: GridRowId) => ({
                url: `${id}`,
                method: 'DELETE'
            }),
            invalidatesTags: ['Statuses']
        }),
    }),
})

export const {
    useCreateStatusMutation,
    useDeleteStatusMutation,
    useEditStatusMutation,
    useGetStatusesQuery,
    useGetStatusByIdQuery
} = statusesApi;
