import {GridRowId} from "@mui/x-data-grid";
import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {PagedResponse} from "../../models/api";
import {IService, IServiceShort, ServiceParams} from "../../models/service";
import {BulkDeleteRequest, BulkDeleteResult} from "../../models/bulkDelete";

const toServiceQueryParams = (serviceParams: ServiceParams) => {
    const {categories, ...params} = serviceParams;

    return {
        ...params,
        categories: categories?.join(",") || undefined,
    };
};

export const servicesApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "services",
    tagTypes: ["Services", "Service"],
    baseQuery: createFirmBaseQuery("services"),
    endpoints: (builder) => ({
        getServices: builder.query<PagedResponse<IServiceShort>, ServiceParams>({
            query: (serviceParams) => ({
                url: "",
                method: "GET",
                params: toServiceQueryParams(serviceParams),
            }),
            providesTags: ["Services"],
        }),
        getServiceById: builder.query<IService, string | number>({
            query: (serviceId) => ({
                url: `${serviceId}`,
                method: "GET",
            }),
            providesTags: ["Service"],
        }),
        getServicesForSearch: builder.query<IServiceShort[], string | void>({
            query: (searchTerm = "") => ({
                url: "search",
                method: "GET",
                params: {searchTerm},
            }),
        }),
        getServicesByCategoryId: builder.query<IServiceShort[], string | number>({
            query: (categoryId) => ({
                url: `categories/${categoryId}`,
                method: "GET",
            }),
        }),
        createService: builder.mutation<number, FormData>({
            query: (service) => ({
                url: "",
                method: "POST",
                body: service,
            }),
            invalidatesTags: ["Services", "Service"],
        }),
        editService: builder.mutation<number, FormData>({
            query: (service) => ({
                url: "",
                method: "PUT",
                body: service,
            }),
            invalidatesTags: ["Services", "Service"],
        }),
        deleteService: builder.mutation<number, GridRowId>({
            query: (serviceId) => ({
                url: `${serviceId}`,
                method: "DELETE",
            }),
            invalidatesTags: ["Services"],
        }),
        bulkDeleteServices: builder.mutation<BulkDeleteResult, BulkDeleteRequest>({
            query: (request) => ({
                url: "bulk-delete",
                method: "POST",
                body: request,
            }),
            invalidatesTags: ["Services", "Service"],
        }),
    }),
});

export const {
    useBulkDeleteServicesMutation,
    useCreateServiceMutation,
    useDeleteServiceMutation,
    useEditServiceMutation,
    useGetServiceByIdQuery,
    useGetServicesByCategoryIdQuery,
    useGetServicesForSearchQuery,
    useGetServicesQuery,
} = servicesApi;
