import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {ReceiptApprovalStatus, TransportWaybillDto, TransportWaybillProcessingStatus} from "../../models/transportWaybill";
import {Receipt, ReceiveStock, WaybillReceiptPreparation} from "../warehouse/warehouseReceiptsApi";
export interface InvoiceListParams {
    page: number;
    pageSize: number;
    archive: "Active" | "Archived" | "All";
    approvalStatus?: ReceiptApprovalStatus;
    isApproved?: boolean;
    status?: TransportWaybillProcessingStatus;
    searchTerm?: string;
}
export interface InvoicePage {
    items: TransportWaybillDto[];
    metaData: {currentPage: number; pageSize: number; totalCount: number; totalPages: number};
}
export const goodsInvoicesApi = createApi({
    ...liveServerDataApiOptions, reducerPath: "goodsInvoicesApi", baseQuery: createFirmBaseQuery("invoices"), tagTypes: ["Invoices"],
    endpoints: builder => ({
        goodsInvoices: builder.query<InvoicePage, InvoiceListParams>({query: params => ({url:"", params:{...params,includePagination:true}}), providesTags:["Invoices"]}),
        goodsInvoice: builder.query<TransportWaybillDto, number>({query: id => String(id), providesTags:["Invoices"]}),
        invoicePreparation: builder.query<WaybillReceiptPreparation, number>({query: id => `${id}/preparation`, providesTags:["Invoices"]}),
        uploadGoodsInvoice: builder.mutation<TransportWaybillDto, {file: File; priceKind: number; currency: string; fxRate: number}>({query: ({file, priceKind, currency, fxRate}) => {const body = new FormData(); body.append("file",file); body.append("priceKind",String(priceKind)); if (priceKind !== 3) {body.append("currency",currency); body.append("fxRate",String(fxRate));} return {url:"upload",method:"POST",body};}, invalidatesTags:["Invoices"]}),
        approveGoodsInvoice: builder.mutation<Receipt, {id: number; expectedVersion: string; receipt: ReceiveStock}>({query: ({id,...body}) => ({url:`${id}/approve`,method:"POST",body}), invalidatesTags:["Invoices"]}),
        rejectGoodsInvoice: builder.mutation<void, {id: number; expectedVersion: string; reason: string}>({query: ({id,...body}) => ({url:`${id}/reject`,method:"POST",body}), invalidatesTags:["Invoices"]}),
        archiveGoodsInvoice: builder.mutation<void, number>({query: id => ({url:String(id),method:"DELETE"}), invalidatesTags:["Invoices"]}),
        restoreGoodsInvoice: builder.mutation<void, number>({query: id => ({url:`${id}/restore`,method:"POST"}), invalidatesTags:["Invoices"]}),
        clearInvoiceArchive: builder.mutation<{deletedCount: number}, void>({query: () => ({url:"archive",method:"DELETE"}), invalidatesTags:["Invoices"]}),
        deleteArchivedInvoice: builder.mutation<{deletedCount: number}, number>({query: id => ({url:`${id}/archive`,method:"DELETE"}), invalidatesTags:["Invoices"]}),
        originalGoodsInvoice: builder.mutation<Blob, number>({query: id => ({url:`${id}/file`,method:"GET",responseHandler: response => response.blob()})}),
    }),
});
export const {useGoodsInvoicesQuery, useGoodsInvoiceQuery, useInvoicePreparationQuery, useUploadGoodsInvoiceMutation, useApproveGoodsInvoiceMutation, useRejectGoodsInvoiceMutation, useOriginalGoodsInvoiceMutation, useArchiveGoodsInvoiceMutation, useRestoreGoodsInvoiceMutation, useClearInvoiceArchiveMutation, useDeleteArchivedInvoiceMutation} = goodsInvoicesApi;
export const approvalLabel = (status?: ReceiptApprovalStatus | null) => status === ReceiptApprovalStatus.Pending ? "Ожидает одобрения" : status === ReceiptApprovalStatus.Approved ? "Приход одобрен" : status === ReceiptApprovalStatus.Rejected ? "Приход отклонён" : "Нет предложения";
