import React, {useEffect, useRef, useState} from "react";
import {Box, Button, Chip, Dialog, DialogContent, DialogTitle, IconButton, InputAdornment, TextField, Typography} from "@mui/material";
import AppsOutlinedIcon from "@mui/icons-material/AppsOutlined";
import KeyboardArrowDownOutlinedIcon from "@mui/icons-material/KeyboardArrowDownOutlined";
import CloseOutlinedIcon from "@mui/icons-material/CloseOutlined";
import SearchOutlinedIcon from "@mui/icons-material/SearchOutlined";
import ArrowForwardOutlinedIcon from "@mui/icons-material/ArrowForwardOutlined";
import styled from "styled-components";
import {modules, Workspace} from "./modules";
import {moduleIcons, moduleNavigationLabels} from "./moduleIcons";

const Bar = styled.div({
    position: "sticky", top: 0, zIndex: 50, height: "var(--app-module-navigation-height, 76px)",
    display: "flex", alignItems: "center", gap: 18, padding: "8px clamp(14px, 2vw, 28px)",
    color: "var(--color-text)", background: "var(--color-surface)", borderBottom: "1px solid var(--color-border)",
    "@media (max-width: 900px)": {flexDirection: "column", alignItems: "stretch", gap: 8, padding: "9px 14px"},
});
const Launcher = styled.button({
    display: "flex", alignItems: "center", gap: 10, minHeight: 44, flexShrink: 0, padding: "6px 12px",
    color: "var(--color-primary)", background: "var(--color-primary-soft)", border: "1px solid var(--color-primary-border)",
    borderRadius: 12, cursor: "pointer", textAlign: "left", font: "inherit",
    "&:hover": {background: "var(--color-primary-soft-hover)"},
    "&:focus-visible": {outline: "2px solid var(--color-primary)", outlineOffset: 3},
    svg: {width: 22, height: 22, flexShrink: 0},
    strong: {display: "block", fontSize: 13, lineHeight: 1.25},
    small: {display: "block", fontSize: 10, marginTop: 2, color: "var(--color-muted)", lineHeight: 1.25},
    "@media (max-width: 900px)": {minHeight: 44, height: 44, width: "100%", padding: "5px 12px"},
});
const Shortcuts = styled.nav({
    display: "flex", alignItems: "center", gap: 5, flex: 1, minWidth: 0, overflowX: "auto", overflowY: "hidden", overscrollBehaviorX: "contain",
    padding: "4px 2px", scrollbarWidth: "thin", scrollbarColor: "var(--color-border-strong) transparent",
    "@media (max-width: 900px)": {flex: "none", height: 44, padding: "0 2px"},
});
const Shortcut = styled.button<{ $active: boolean }>(({ $active }) => ({
    display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 7, flexShrink: 0, minHeight: 40,
    padding: "8px 12px", borderRadius: 9, border: "1px solid transparent",
    color: $active ? "var(--color-primary)" : "var(--color-muted)", background: $active ? "var(--color-primary-soft)" : "transparent",
    font: "inherit", fontWeight: $active ? 750 : 550, fontSize: 12, whiteSpace: "nowrap", cursor: "pointer",
    "&:hover": {background: "var(--color-primary-soft)", color: "var(--color-primary)"},
    "&:focus-visible": {outline: "2px solid var(--color-primary)", outlineOffset: -2},
    svg: {width: 19, height: 19, flexShrink: 0},
    "@media (max-width: 900px)": {minHeight: 36, padding: "6px 10px"},
}));

type Props = {workspace: Workspace; onSelect: (workspace: Workspace) => void};

const ModuleNavigation = ({workspace, onSelect}: Props) => {
    const [open, setOpen] = useState(false);
    const [search, setSearch] = useState("");
    const activeShortcut = useRef<HTMLButtonElement>(null);
    const shortcutContainer = useRef<HTMLElement>(null);
    const launcher = useRef<HTMLButtonElement>(null);
    const moduleKeys = Object.keys(modules) as Workspace[];
    useEffect(() => {
        const revealActiveModule = () => activeShortcut.current?.scrollIntoView?.({block: "nearest", inline: "nearest"});
        revealActiveModule();
        const observer = typeof ResizeObserver === "undefined" ? undefined : new ResizeObserver(revealActiveModule);
        if (shortcutContainer.current) observer?.observe(shortcutContainer.current);
        return () => observer?.disconnect();
    }, [workspace]);
    const choose = (next: Workspace) => {
        setOpen(false);
        if (next !== workspace) onSelect(next);
    };
    const query = search.trim().toLocaleLowerCase();
    const matches = moduleKeys.filter(key => !query || `${modules[key].title} ${moduleNavigationLabels[key]} ${modules[key].description}`.toLocaleLowerCase().includes(query));

    return <>
        <Bar>
            <Launcher ref={launcher} type="button" aria-label="Все модули" aria-haspopup="dialog" aria-expanded={open}
                onClick={() => {setSearch(""); setOpen(true);}}>
                <AppsOutlinedIcon aria-hidden="true"/>
                <span><strong>Все модули</strong><small>Сейчас: {modules[workspace].title}</small></span>
                <KeyboardArrowDownOutlinedIcon aria-hidden="true" sx={{ml: "auto"}}/>
            </Launcher>
            <Shortcuts ref={shortcutContainer} aria-label="Модули CRM">
                {moduleKeys.map(key => {
                    const Icon = moduleIcons[key]; const active = key === workspace;
                    return <Shortcut key={key} type="button" $active={active} ref={active ? activeShortcut : undefined}
                        aria-current={active ? "page" : undefined} aria-label={modules[key].title} title={modules[key].description}
                        onClick={() => choose(key)}><Icon aria-hidden="true"/><span>{moduleNavigationLabels[key]}</span></Shortcut>;
                })}
            </Shortcuts>
        </Bar>
        <Dialog open={open} onClose={() => setOpen(false)} maxWidth="md" fullWidth aria-labelledby="module-picker-title"
            PaperProps={{sx: {borderRadius: 4, maxHeight: "calc(100dvh - 32px)", m: {xs: 2, sm: 4}, width: "calc(100% - 32px)"}}}
            TransitionProps={{onExited: () => launcher.current?.focus()}}>
            <DialogTitle component="div" id="module-picker-header" sx={{display: "flex", alignItems: "center", gap: 2}}>
                <Box sx={{flex: 1}}><Typography component="h2" id="module-picker-title" variant="h6" fontWeight={750}>Выберите модуль</Typography>
                    <Typography variant="body2" color="text.secondary">Откройте нужный раздел одним нажатием.</Typography></Box>
                <IconButton aria-label="Закрыть выбор модуля" onClick={() => setOpen(false)}><CloseOutlinedIcon/></IconButton>
            </DialogTitle>
            <DialogContent>
                <TextField autoFocus size="small" fullWidth label="Поиск модуля" placeholder="Название модуля или задача" value={search}
                    onChange={event => setSearch(event.target.value)} InputProps={{startAdornment: <InputAdornment position="start"><SearchOutlinedIcon fontSize="small"/></InputAdornment>}} sx={{mt: .5, mb: 2}}/>
                <Box sx={{display: "grid", gridTemplateColumns: {xs: "1fr", sm: "repeat(2, minmax(0, 1fr))"}, gap: 1.5}}>
                    {matches.map(key => {
                        const Icon = moduleIcons[key]; const active = key === workspace;
                        return <Button key={key} aria-label={`Открыть модуль «${modules[key].title}»`} onClick={() => choose(key)}
                            sx={{display: "flex", alignItems: "flex-start", gap: 1.5, p: 2, border: "1px solid", borderColor: active ? "primary.main" : "divider",
                                borderRadius: 3, textTransform: "none", textAlign: "left", color: "text.primary", bgcolor: active ? "action.selected" : "background.paper", minHeight: 116}}>
                            <Box sx={{display: "grid", placeItems: "center", p: 1, bgcolor: "action.selected", color: "primary.main", borderRadius: 2}}><Icon/></Box>
                            <Box sx={{flex: 1, minWidth: 0}}><Box sx={{display: "flex", alignItems: "center", flexWrap: "wrap", gap: 1, mb: .5}}>
                                <Typography fontWeight={750} fontSize={14}>{modules[key].title}</Typography>{active && <Chip label="Текущий" size="small" color="primary" variant="outlined"/>}</Box>
                                <Typography fontSize={12} color="text.secondary">{modules[key].description}</Typography></Box>
                            <ArrowForwardOutlinedIcon sx={{fontSize: 18, color: "text.secondary", mt: .5}}/>
                        </Button>;
                    })}
                </Box>
                {matches.length === 0 && <Typography color="text.secondary" sx={{py: 3, textAlign: "center"}}>Модуль не найден. Попробуйте другое название или задачу.</Typography>}
            </DialogContent>
        </Dialog>
    </>;
};

export default ModuleNavigation;
