import {createApi} from '@reduxjs/toolkit/query/react';
import {createFirmBaseQuery, liveServerDataApiOptions} from '../../api/baseQuery';

export type UserOption = {id:number; name:string; isManager:boolean};
export type Versioned = {id:string; firmId:number; version:number};
export type OrderSnapshot = {id:number; customerId:number; customerName:string; phone:string; statusId:number; statusName:string; totalSum:number; finalSum:number; discount:number; responsibleUserIds:number[]; createdAt:string; modifiedAt:string; comment:string; version:number};
export type Work = Versioned & {orderId:number; stageEnteredAt:string; expectedCloseAt:string|null; nextActionAt:string|null; nextAction:string; priority:string; watcherUserIds:number[]; paidAmount:number; notifyTelegram:boolean};
export type StageRule = Versioned & {statusId:number; position:number; probability:number; maxHours:number; isClosed:boolean; isWon:boolean; requirePayment:boolean; allowedNextStatusIds:number[]; notifyUserIds:number[]};
export type Stage = {status:{id:number;name:string}; rule:StageRule};
export type Card = {order:OrderSnapshot;work:Work;overdue:boolean;contactOverdue:boolean;weightedAmount:number};
export type Pipeline = {stages:Stage[];orders:Card[];totalCount:number;truncated:boolean};
export type Discount = Versioned & {orderId:number;requestedBy:number;percent:number;baseTotal:number;reason:string;campaign:string;state:string;createdAt:string;expiresAt:string;decidedBy:number|null;decisionNote:string};
export type Policy = Versioned & {employeeLimitPercent:number;maximumPercent:number};
export type Activity = {id:string;kind:string;detail:string;actorUserId:number|null;createdAt:string};
export type Notification = {id:string;orderId:number|null;body:string;kind:string;createdAt:string;readAt:string|null;telegramRequested:boolean;telegramQueuedAt:string|null;deliveryError:string|null};
export type PhoneCall = Versioned & {externalId:string;phone:string;direction:string;state:string;extension:string;startedAt:string;answeredAt:string|null;endedAt:string|null;customerId:number|null;orderId:number|null;assignedUserId:number|null;callbackDueAt:string|null;callbackCompletedAt:string|null;note:string};
export type CallView = {call:PhoneCall;customers:{id:number;name:string;phone:string}[];orders:OrderSnapshot[]};
export type OrderDetail = {order:OrderSnapshot;work:Work;history:Activity[];discounts:Discount[];calls:PhoneCall[]};
export type Metrics = {activeOrders:number;pipelineAmount:number;weightedAmount:number;wonOrders:number;wonAmount:number;overdueOrders:number;unassignedOrders:number;pendingDiscounts:number;callbackOverdue:number;truncated:boolean;employees:{id:number;name:string;activeOrders:number;wonOrders:number;wonAmount:number;overdueOrders:number;assignedCalls:number;callbackOverdue:number}[]};
export type TelephonySettings = {enabled:boolean;provider:string;hasSecret:boolean;recipientUserIds:number[];callbackMinutes:number;version:number};

export const operationsApi = createApi({
    ...liveServerDataApiOptions, reducerPath:'operationsApi', baseQuery:createFirmBaseQuery('operations'), tagTypes:['Operations','Inbox','Calls','Settings'],
    endpoints:b => ({
        pipeline:b.query<Pipeline,{query:string;responsible?:number;overdueOnly:boolean;mine:boolean}>({query:params => ({url:'pipeline',params}),providesTags:['Operations']}),
        metrics:b.query<Metrics,void>({query:() => 'metrics',providesTags:['Operations','Calls']}),
        operationsUsers:b.query<UserOption[],void>({query:() => 'users'}),
        orderControl:b.query<OrderDetail,number>({query:id => `orders/${id}`,providesTags:['Operations','Calls']}),
        saveWork:b.mutation<Work,{orderId:number;work:Work}>({query:({orderId,work}) => ({url:`orders/${orderId}/work`,method:'PUT',body:work}),invalidatesTags:['Operations','Inbox']}),
        changeStage:b.mutation<void,{orderId:number;statusId:number;version:number;reason:string}>({query:({orderId,...body}) => ({url:`orders/${orderId}/stage`,method:'PUT',body}),invalidatesTags:['Operations','Inbox']}),
        saveStage:b.mutation<StageRule,StageRule>({query:body => ({url:`stages/${body.statusId}`,method:'PUT',body}),invalidatesTags:['Operations']}),
        discountPolicy:b.query<Policy,void>({query:() => 'discount-policy',providesTags:['Settings']}),
        saveDiscountPolicy:b.mutation<Policy,Policy>({query:body => ({url:'discount-policy',method:'PUT',body}),invalidatesTags:['Settings']}),
        discounts:b.query<Discount[],void>({query:() => 'discounts',providesTags:['Operations']}),
        requestDiscount:b.mutation<Discount,{orderId:number;percent:number;reason:string;campaign:string;validDays:number}>({query:({orderId,...body}) => ({url:`orders/${orderId}/discounts`,method:'POST',body}),invalidatesTags:['Operations','Inbox']}),
        decideDiscount:b.mutation<Discount,{id:string;approve:boolean;note:string;version:number}>({query:({id,...body}) => ({url:`discounts/${id}/decision`,method:'PUT',body}),invalidatesTags:['Operations','Inbox']}),
        applyDiscount:b.mutation<void,{id:string;orderVersion:number}>({query:({id,...body}) => ({url:`discounts/${id}/apply`,method:'POST',body}),invalidatesTags:['Operations','Inbox']}),
        inbox:b.query<Notification[],void>({query:() => 'notifications',providesTags:['Inbox']}),
        readNotification:b.mutation<void,string>({query:id => ({url:`notifications/${id}/read`,method:'PUT'}),invalidatesTags:['Inbox']}),
        calls:b.query<PhoneCall[],void>({query:() => 'telephony/calls',providesTags:['Calls']}),
        call:b.query<CallView,string>({query:id => `telephony/calls/${id}`,providesTags:['Calls']}),
        assignCall:b.mutation<PhoneCall,{id:string;orderId:number|null;userId:number|null;callbackCompleted:boolean;note:string;version:number}>({query:({id,...body}) => ({url:`telephony/calls/${id}`,method:'PUT',body}),invalidatesTags:['Calls','Operations']}),
        telephonySettings:b.query<TelephonySettings,void>({query:() => 'telephony/settings',providesTags:['Settings']}),
        saveTelephony:b.mutation<TelephonySettings,TelephonySettings & {secret:string}>({query:body => ({url:'telephony/settings',method:'PUT',body}),invalidatesTags:['Settings']}),
    }),
});
export const {usePipelineQuery,useMetricsQuery,useOperationsUsersQuery,useOrderControlQuery,useSaveWorkMutation,useChangeStageMutation,useSaveStageMutation,useDiscountPolicyQuery,useSaveDiscountPolicyMutation,useDiscountsQuery,useRequestDiscountMutation,useDecideDiscountMutation,useApplyDiscountMutation,useInboxQuery,useReadNotificationMutation,useCallsQuery,useCallQuery,useAssignCallMutation,useTelephonySettingsQuery,useSaveTelephonyMutation} = operationsApi;
