import {matchPath} from "react-router-dom";
import {moduleForPath, modules} from "../../workspaces/modules";
import {TranslationParams} from "../../../i18n";

export interface Breadcrumb {
    label: string;
    to: string;
    params?: TranslationParams;
}

const crumb = (label: string, to: string, params?: TranslationParams): Breadcrumb => ({label, to, params});
const directories = crumb("Справочники", "/directories");
const orders = crumb("Заказы", "/ordersManagement");
const products = crumb("Продукты", "/productsManagement");
const offers = crumb("Коммерческие предложения", "/commercialOffers");
const templates = crumb("Шаблоны КП", "/commercialOffers/templates");

const sections: Record<string, string> = {
    mainPage: "Обзор", reports: "Отчеты", ordersManagement: "Заказы", customers: "Клиенты", productsManagement: "Продукты",
    servicesManagement: "Услуги", stockManagement: "Остатки", warehouseReceipts: "Приёмка на склад",
    stockAlerts: "Закупки и пороги остатков", warehouseApprovals: "Согласование приходов",
    supplies: "Поставки",
    collaboration: "Общение и задачи", logistics: "Логистика", invoices: "Файлы для прихода", goodsInvoices: "Файлы для прихода",
    transportWaybills: "Файлы для прихода", commercialOffers: "Коммерческие предложения",
    directories: "Справочники", settings: "Настройки", users: "Пользователи", firms: "Компании",
    statuses: "Статусы заказов", deliveryMethods: "Способы доставки", paymentMethods: "Способы оплаты", sources: "Источники заказов",
    categoriesManagement: "Product categories", productCategories: "Product categories", categories: "Product categories", serviceCategories: "Service categories",
};

const directoryForms = [
    ["statuses", "Status", "Новый статус", "Редактирование статуса"],
    ["deliveryMethods", "DeliveryMethod", "Новый способ доставки", "Редактирование доставки"],
    ["paymentMethods", "PaymentMethod", "Новый способ оплаты", "Редактирование оплаты"],
    ["sources", "Source", "Новый источник", "Редактирование источника"],
] as const;

// Parents are explicit: browser history may contain a completed form or an external page.
export function getPageBreadcrumbs(pathname: string, search = "", returnTo?: unknown): Breadcrumb[] {
    const path = pathname.replace(/\/+$/, "") || "/";
    const module = moduleForPath(path);
    if (!module) return [];
    const root = crumb(modules[module].title, modules[module].path);
    const finish = (items: Breadcrumb[]) => [root, ...items].filter((item, index, all) =>
        !all.slice(index + 1).some(candidate => candidate.to === item.to));
    const match = (pattern: string) => matchPath(pattern, path)?.params;
    if (match('/supplies/:id')) return finish([crumb('Поставки', '/supplies'), crumb('Карточка поставки', path)]);
    if (path === "/costing/new") return finish([crumb("Новая калькуляция", path)]);
    if (match("/costing/:id")) return finish([crumb("Калькуляция", path)]);
    if (match("/servicesManagement/:id") && path !== "/servicesManagement/createService") return finish([crumb("Услуги", "/servicesManagement"), crumb("Карточка услуги", path)]);

    for (const [section, entity, createLabel, editLabel] of directoryForms) {
        const parent = crumb(sections[section], `/${section}`);
        if (path === parent.to) return finish([directories, parent]);
        if (path === `${parent.to}/create${entity}`) return finish([directories, parent, crumb(createLabel, path)]);
        if (match(`${parent.to}/edit${entity}/:id`)) return finish([directories, parent, crumb(editLabel, path)]);
    }

    const orderEditor = match("/ordersManagement/editOrder/:id");
    if (path === "/ordersManagement/createOrder" || orderEditor) return finish([orders, crumb(orderEditor ? "Редактирование заказа" : "Новый заказ", path)]);
    const orderCategories = match("/ordersManagement/editOrder/:id/categories/:categoryId?");
    if (orderCategories || match("/ordersManagement/createOrder/categories/:categoryId?")) {
        const editor = orderCategories ? `/ordersManagement/editOrder/${orderCategories.id}` : "/ordersManagement/createOrder";
        return finish([orders, crumb(orderCategories ? "Редактирование заказа" : "Новый заказ", editor), crumb("Каталог категорий", path)]);
    }
    const order = match("/ordersManagement/:id");
    if (order) return finish([orders, crumb("Заказ #{id}", path, {id: order.id})]);

    if (path === "/productsManagement/createProduct") return finish([products, crumb("Новый продукт", path)]);
    if (match("/productsManagement/editProduct/:id")) return finish([products, crumb("Редактирование продукта", path)]);
    if (match("/productsManagement/copyProduct/:id")) return finish([products, crumb("Копирование продукта", path)]);
    if (match("/productsManagement/editProduct/productDetails/:id")) return finish([products, crumb("Карточка товара", path)]);
    if (match("/productDetails/:id")) {
        const parent = typeof returnTo === "string" ? matchPath("/ordersManagement/:id", returnTo) : null;
        return parent ? [orders, crumb("Заказ #{id}", returnTo as string, {id: parent.params.id}), crumb("Карточка товара", path)]
            : finish([products, crumb("Карточка товара", path)]);
    }
    if (path === "/servicesManagement/createService" || match("/servicesManagement/editService/:id")) return finish([
        crumb("Услуги", "/servicesManagement"), crumb(path.endsWith("createService") ? "Новая услуга" : "Редактирование услуги", path),
    ]);

    for (const section of ["categoriesManagement", "productCategories", "categories", "serviceCategories"]) {
        if (path.startsWith(`/${section}/`)) return finish([
            crumb(sections[section], section === "categories" ? "/categoriesManagement" : `/${section}`),
            crumb(path.includes("categoriesGraphTree") ? "Category map" : "Manage hierarchy", path),
        ]);
    }

    if (path.startsWith("/catalogGeneration")) {
        if (path === "/catalogGeneration/epass") return finish([crumb("Формирование заявок в ePass", path)]);
        const generation = crumb("Catalog generation", "/catalogGeneration");
        if (path === "/catalogGeneration/lifecycle") return finish([generation, crumb("Жизненный цикл товара", path)]);
        if (path === "/catalogGeneration/recognition") return finish([generation, crumb("Из файла контрагента", path)]);
        if (path === "/catalogGeneration/file/review") return finish([generation, crumb("Генерация из файла ePass", "/catalogGeneration/file"), crumb("Product review", path)]);
        return finish([generation, ...(path === generation.to ? [] : [crumb(path.endsWith("/file") ? "Генерация из файла ePass" : "Generation batches", path)])]);
    }
    if (path.startsWith("/commercialOffers/templates")) return finish([offers, templates,
        ...(path === templates.to ? [] : [crumb(path.endsWith("/new") ? "Новый шаблон КП" : "Редактирование шаблона КП", path)]),
    ]);
    if (match("/commercialOffers/:id")) return finish([offers, crumb(path.endsWith("/new") ? "Новое коммерческое предложение" : "Коммерческое предложение", path)]);
    if (match("/warehouseReceipts/waybill/:waybillId")) return finish([crumb("Приёмка на склад", "/warehouseReceipts"), crumb("Предложение прихода", path)]);
    if (path === "/warehouseReceipts" && new URLSearchParams(search).has("receipt")) return finish([
        crumb("Приёмка на склад", "/warehouseReceipts"), crumb("Сохранённая приёмка", path + search),
    ]);
    if (match("/invoices/:id/approval") || match("/goodsInvoices/:id/approval")) return finish([crumb("Согласование приходов", "/warehouseApprovals"), crumb("Предложение прихода", path)]);
    if (match("/invoices/:id") || match("/goodsInvoices/:id") || match("/transportWaybills/:id")) {
        const section = path.split("/")[1];
        return finish([crumb(sections[section], `/${section}`), crumb("Детали файла для прихода", path)]);
    }
    const section = path.split("/")[1];
    return sections[section] ? finish([crumb(sections[section], path)]) : [];
}
