import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
export type StockAlertRule = {productId:number; name:string; gtin:string; currentStock:number; threshold:number; enabled:boolean; notifyTelegram:boolean; recipientUserIds:number[]; version:number};
export type StockAlert = {id:string; productId:number; name:string; gtin:string; currentStock:number; threshold:number; createdAt:string; telegramQueued:number; telegramPending:number; deliveryError:string | null};
export type StockAlertRecipient = {id:number; name:string; telegramReady:boolean};
export const stockAlertsApi = createApi({
    ...liveServerDataApiOptions, reducerPath:"stockAlertsApi", baseQuery:createFirmBaseQuery("warehouse/alerts"), tagTypes:["StockAlerts"],
    endpoints:builder => ({
        stockAlertRules:builder.query<StockAlertRule[],string>({query:query => ({url:"rules",params:{query}}),providesTags:["StockAlerts"]}),
        activeStockAlerts:builder.query<StockAlert[],void>({query:() => "",providesTags:["StockAlerts"]}),
        stockAlertRecipients:builder.query<StockAlertRecipient[],void>({query:() => "recipients"}),
        saveStockAlert:builder.mutation<void,{productId:number; threshold:number; enabled:boolean; notifyTelegram:boolean; recipientUserIds:number[]; version:number}>({
            query:({productId,...body}) => ({url:`rules/${productId}`,method:"PUT",body}),invalidatesTags:["StockAlerts"],
        }),
    }),
});
export const {useStockAlertRulesQuery,useActiveStockAlertsQuery,useStockAlertRecipientsQuery,useSaveStockAlertMutation} = stockAlertsApi;
