import React from "react";
import {Breadcrumbs, Button, Link, Stack, Typography} from "@mui/material";
import ArrowBackRoundedIcon from "@mui/icons-material/ArrowBackRounded";
import {Link as RouterLink, useLocation} from "react-router-dom";
import {useTranslation} from "../../../i18n";
import {getPageBreadcrumbs} from "./breadcrumbs";

export default function PageNavigation() {
    const {pathname, search, state} = useLocation();
    const {t} = useTranslation();
    const items = getPageBreadcrumbs(pathname, search, state?.returnTo);
    if (!items.length) return null;
    const parent = items[items.length - 2];

    return <Stack direction="row" alignItems="center" justifyContent="space-between" flexWrap="wrap" gap={1}
                  sx={{px: {xs: 2, md: 3}, pt: 2, pb: 1}}>
        <Breadcrumbs aria-label={t("Навигация по странице")} sx={{fontSize: 13}}>
            {items.map((item, index) => index === items.length - 1
                ? <Typography key={item.to} aria-current="page" color="text.primary" fontSize="inherit">{t(item.label, item.params)}</Typography>
                : <Link key={item.to} component={RouterLink} replace to={item.to} underline="hover" color="inherit">{t(item.label, item.params)}</Link>)}
        </Breadcrumbs>
        {parent && <Button component={RouterLink} replace to={parent.to} size="small" startIcon={<ArrowBackRoundedIcon/>}>
            {t("Назад")}
        </Button>}
    </Stack>;
}
