import React from 'react';
import ReactDOM from 'react-dom/client';
import "react-toastify/dist/ReactToastify.css";
import './index.css';
import App from './App';
import {Provider} from "react-redux";
import {store} from "./store/store";
import {LanguageProvider} from "./i18n";
import {LocalizedAppThemeProvider as AppThemeProvider} from "./themeMode";

if (process.env.NODE_ENV === 'development' && process.env.REACT_APP_CRM_CONNECTION_MODE === 'shared') {
    document.title = 'VivoTech CRM · Общие рабочие данные';
}

const root = ReactDOM.createRoot(
    document.getElementById('root') as HTMLElement
);
root.render(
    <Provider store={store}>
        <LanguageProvider>
            <AppThemeProvider>
                <App/>
            </AppThemeProvider>
        </LanguageProvider>
    </Provider>
);
