import {GridRowId} from "@mui/x-data-grid";
import {createApi} from '@reduxjs/toolkit/query/react'
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {CategoryType, ICategory, ICreateCategory, IEditCategory} from "../../models/category";

export interface CategoryQueryParams {
    searchTerm?: string;
    pageNumber?: number;
    pageSize?: number;
    type?: CategoryType;
}

export interface CategoryHierarchyParams {
    parentCategoryId?: number | string;
    type?: CategoryType;
}

type CategoryHierarchyArg = number | string | CategoryHierarchyParams | void;
type LastLevelCategoriesArg = CategoryType | {type?: CategoryType} | void;

const toHierarchyParams = (arg: CategoryHierarchyArg) => {
    if (arg === undefined || arg === "") {
        return undefined;
    }

    if (typeof arg === "object") {
        const {parentCategoryId, type} = arg;

        return {
            parentCategoryId: parentCategoryId || undefined,
            type,
        };
    }

    return {parentCategoryId: arg};
};

const toLastLevelParams = (arg: LastLevelCategoriesArg) => {
    if (arg === undefined) {
        return undefined;
    }

    if (typeof arg === "number") {
        return {type: arg};
    }

    return arg;
};

export const categoriesApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: 'categories',
    tagTypes: ['Categories'],
    baseQuery: createFirmBaseQuery('categories'),
    endpoints: (builder) => ({
        getCategories: builder.query<ICategory[], CategoryQueryParams | void>({
            query: (categoryParams) => ({
                url: '',
                method: 'GET',
                params: categoryParams || undefined,
            }),
            providesTags: ['Categories']
        }),
        getCategoriesHierarchy: builder.query<ICategory[], CategoryHierarchyArg>({
            query: (arg) => ({
                url: 'hierarchy',
                method: 'GET',
                params: toHierarchyParams(arg),
            }),
            providesTags: ['Categories']
        }),
        getCategoryById: builder.query<ICategory, number | string>({
            query: (id) => ({
                url: `${id}`,
                method: 'GET',
            }),
            providesTags: ['Categories']
        }),
        getLastLevelCategories: builder.query<ICategory[], LastLevelCategoriesArg>({
            query: (arg) => ({
                url: 'lastLevelCategories',
                method: 'GET',
                params: toLastLevelParams(arg),
            }),
            providesTags: ['Categories'],
        }),
        createCategory: builder.mutation<number, ICreateCategory>({
            query: (category: ICreateCategory) => ({
                url: ``,
                method: 'POST',
                body: category,
            }),
            invalidatesTags: ['Categories']
        }),
        editCategory: builder.mutation<number, { categoryId: number | string; category: IEditCategory }>({
            query: ({categoryId, category}) => ({
                url: `${categoryId}`,
                method: 'PUT',
                body: category
            }),
            invalidatesTags: ['Categories']
        }),
        deleteCategory: builder.mutation<number, GridRowId>({
            query: (id: GridRowId) => ({
                url: `${id}`,
                method: 'DELETE'
            }),
            invalidatesTags: ['Categories']
        }),
    }),
})

export const {
    useGetCategoriesQuery,
    useGetCategoryByIdQuery,
    useGetLastLevelCategoriesQuery,
    useGetCategoriesHierarchyQuery,
    useCreateCategoryMutation,
    useDeleteCategoryMutation,
    useEditCategoryMutation
} = categoriesApi;
