export const modules = {
    counterparties: {title: 'Проверка контрагентов', description: 'Организации по ИНН, УНП и БИН, реквизиты и сведения из реестров DaData', path: '/counterparties'},
    costing: {title: "Себестоимость", description: "Себестоимость и ценообразование по поступлениям, наценка, утверждение цен и нормативные калькуляции", path: "/costing"},
    orders: {title: "Заказы", description: "Воронка, контроль заказов, телефония и логистика", path: "/ordersManagement"},
    customers: {title: 'Клиенты', description: 'Контакты, все заказы, заметки и история взаимодействия', path: '/customers'},
    catalog: {title: "Каталог", description: "Товары, услуги, категории и подготовка карточек из файлов клиентов", path: "/productsManagement"},
    warehouse: {title: "Склад", description: "Остатки, приёмка, согласование приходов и журнал поступлений", path: "/stockManagement"},
    documents: {title: "Документооборот", description: "Файлы для прихода, коммерческие предложения и шаблоны", path: "/invoices"},
    staff: {title: "Персонал", description: "Сотрудники, графики, часы, табели и зарплаты", path: "/staff/dashboard"},
    collaboration: {title: "Общение и задачи", description: "Беседы сотрудников и задачи со ссылками на записи CRM", path: "/collaboration"},
    analytics: {title: "Отчёты", description: "Показатели продаж и движения товаров", path: "/reports"},
    administration: {title: "Администрирование", description: "Пользователи, справочники и настройки компании", path: "/directories"},
} as const;
export type Workspace = keyof typeof modules;
export function moduleForPath(path: string): Workspace | null {
    const route = path.replace(/^#/, "").split("?")[0];
    if (/^\/counterparties(?:\/|$)/.test(route)) return 'counterparties';
    if (/^\/costing(?:\/|$)/.test(route)) return "costing";
    if (/^\/staff(?:\/|$)/.test(route)) return "staff";
    if (/^\/customers(?:\/|$)/.test(route)) return 'customers';
    if (/^\/(ordersManagement|orderPipeline|telephony|logistics)(?:\/|$)/.test(route)) return "orders";
    if (/^\/(productsManagement|productDetails|productCategories|categoriesManagement|categories|catalogGeneration|servicesManagement|serviceCategories)(?:\/|$)/.test(route)) return "catalog";
    if (/^\/(stockManagement|warehouseReceipts|stockAlerts|warehouseApprovals|supplies)(?:\/|$)/.test(route)) return "warehouse";
    if (/^\/(commercialOffers|invoices|transportWaybills|goodsInvoices)(?:\/|$)/.test(route)) return "documents";
    if (/^\/collaboration(?:\/|$)/.test(route)) return "collaboration";
    if (/^\/(reports|mainPage)(?:\/|$)/.test(route)) return "analytics";
    if (/^\/(directories|settings|users|firms|statuses|sources|paymentMethods|deliveryMethods)(?:\/|$)/.test(route)) return "administration";
    return null;
}
