import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {
    TransportWaybillDto,
    TransportWaybillQueryArgs,
    UploadTransportWaybillArgs,
} from "../../models/transportWaybill";

const cleanParams = (params?: TransportWaybillQueryArgs) => {
    if (!params) {
        return undefined;
    }

    return Object.fromEntries(
        Object.entries(params).filter(([, value]) =>
            value !== undefined && value !== null && value !== "",
        ),
    );
};

export const transportWaybillsApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "transportWaybillsApi",
    tagTypes: ["TransportWaybills", "TransportWaybill"],
    baseQuery: createFirmBaseQuery(),
    endpoints: (builder) => ({
        getTransportWaybills: builder.query<TransportWaybillDto[], TransportWaybillQueryArgs | void>({
            query: (params) => ({
                url: "transport-waybills",
                method: "GET",
                params: cleanParams(params || undefined),
            }),
            providesTags: ["TransportWaybills"],
        }),
        getProcessedTransportWaybills: builder.query<TransportWaybillDto[], TransportWaybillQueryArgs | void>({
            query: (params) => ({
                url: "transport-waybills/processed",
                method: "GET",
                params: cleanParams(params || undefined),
            }),
            providesTags: ["TransportWaybills"],
        }),
        getTransportWaybillById: builder.query<TransportWaybillDto, number>({
            query: (transportWaybillId) => ({
                url: `transport-waybills/${transportWaybillId}`,
                method: "GET",
            }),
            providesTags: (_result, _error, id) => [{type: "TransportWaybill", id}],
        }),
        uploadTransportWaybill: builder.mutation<TransportWaybillDto, UploadTransportWaybillArgs>({
            query: ({file, orderId, logisticsTripId}) => {
                const formData = new FormData();
                formData.append("file", file);

                if (orderId) {
                    formData.append("orderId", String(orderId));
                }

                if (logisticsTripId) {
                    formData.append("logisticsTripId", String(logisticsTripId));
                }

                return {
                    url: "transport-waybills/upload",
                    method: "POST",
                    body: formData,
                };
            },
            invalidatesTags: ["TransportWaybills"],
        }),
    }),
});

export const {
    useGetProcessedTransportWaybillsQuery,
    useGetTransportWaybillByIdQuery,
    useGetTransportWaybillsQuery,
    useUploadTransportWaybillMutation,
} = transportWaybillsApi;
