import React, {FormEvent, useState} from "react";
import {Alert, Button, IconButton, InputAdornment, TextField} from "@mui/material";
import ArrowForwardRoundedIcon from "@mui/icons-material/ArrowForwardRounded";
import VisibilityOutlinedIcon from "@mui/icons-material/VisibilityOutlined";
import VisibilityOffOutlinedIcon from "@mui/icons-material/VisibilityOffOutlined";
import Inventory2OutlinedIcon from "@mui/icons-material/Inventory2Outlined";
import ReceiptLongOutlinedIcon from "@mui/icons-material/ReceiptLongOutlined";
import PeopleOutlineRoundedIcon from "@mui/icons-material/PeopleOutlineRounded";
import CheckRoundedIcon from "@mui/icons-material/CheckRounded";
import {useLogInMutation} from "./authApi";
import {useAuth} from "../../auth/AuthContext";
import {getApiErrorMessage} from "../../api/errors";
import AppearancePicker from "../../ui/appearance/AppearancePicker";
import Image from "../../ui/images/logo-no-background.png";
import "./login.css";

const LoginPage = () => {
    const {signIn} = useAuth();
    const [logIn, {isLoading}] = useLogInMutation();
    const [name, setName] = useState("");
    const [password, setPassword] = useState("");
    const [showPassword, setShowPassword] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const submit = async (event: FormEvent) => {
        event.preventDefault();
        setError(null);
        try {signIn(await logIn({name, password}).unwrap());}
        catch (requestError) {setError(getApiErrorMessage(requestError, "Не удалось войти"));}
    };

    return <main className="login-page">
        <section className="login-story" aria-label="VivoTech CRM">
            <img className="login-logo" src={Image} alt="VivoTech CRM"/>
            <div className="login-story-content">
                <span className="login-eyebrow"><span/>Бизнес в вашем ритме</span>
                <h2>Всё важное.<br/>{" "}В одном<br/>{" "}<em>пространстве.</em></h2>
                <p>Заказы, склад, документы и команда — связаны между собой, всегда под рукой.</p>
                <div className="login-illustration" aria-hidden="true">
                    <div className="login-orbit"/>
                    <div className="login-feature feature-orders"><span><Inventory2OutlinedIcon/></span><div><strong>Заказы и склад</strong><small>От заявки до результата</small></div><CheckRoundedIcon/></div>
                    <div className="login-feature feature-documents"><span><ReceiptLongOutlinedIcon/></span><div><strong>Документы</strong><small>Всё на своих местах</small></div><CheckRoundedIcon/></div>
                    <div className="login-feature feature-team"><span><PeopleOutlineRoundedIcon/></span><div><strong>Ваша команда</strong><small>В едином рабочем ритме</small></div><CheckRoundedIcon/></div>
                </div>
            </div>
            <span className="login-story-footer">VivoTech · Создано для ежедневной работы</span>
        </section>
        <section className="login-form-side">
            <div className="login-appearance"><AppearancePicker label/></div>
            <form className="login-form" onSubmit={submit}>
                <span className="login-eyebrow">Рады видеть вас</span>
                <h1>Вход в CRM</h1>
                <p className="login-form-description">Войдите в аккаунт и продолжите работу.</p>
                {error && <Alert severity="error">{error}</Alert>}
                <TextField autoFocus required fullWidth label="Имя пользователя или email" autoComplete="username" value={name} onChange={event => setName(event.target.value)}/>
                <TextField required fullWidth type={showPassword ? "text" : "password"} label="Пароль" autoComplete="current-password" value={password} onChange={event => setPassword(event.target.value)}
                    InputProps={{endAdornment: <InputAdornment position="end"><IconButton aria-label={showPassword ? "Скрыть пароль" : "Показать пароль"} onClick={() => setShowPassword(value => !value)} onMouseDown={event => event.preventDefault()} edge="end">{showPassword ? <VisibilityOffOutlinedIcon fontSize="small"/> : <VisibilityOutlinedIcon fontSize="small"/>}</IconButton></InputAdornment>}}/>
                <Button size="large" variant="contained" type="submit" fullWidth disabled={isLoading} endIcon={<ArrowForwardRoundedIcon/>}>{isLoading ? "Входим…" : "Войти в пространство"}</Button>
                <p className="login-help">Нет доступа? Обратитесь к администратору вашей компании.</p>
            </form>
            <span className="login-form-footer">Ваш рабочий день начинается здесь.</span>
        </section>
    </main>;
};

export default LoginPage;
