import {createApi} from "@reduxjs/toolkit/query/react";
import {createApiBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {getCurrentLanguage} from "../../i18n";
import {LoginRequest, LoginResponse} from "../../models/auth";

export const authApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "authApi",
    baseQuery: createApiBaseQuery(),
    endpoints: (builder) => ({
        logIn: builder.mutation<LoginResponse, LoginRequest>({
            query: (credentials) => ({
                url: "/auth/login",
                method: "POST",
                body: credentials,
                params: {locale: getCurrentLanguage()},
            }),
        }),
        changePassword: builder.mutation<LoginResponse, {currentPassword: string; newPassword: string}>({
            query: (body) => ({url: '/auth/password', method: 'POST', body}),
        }),
    }),
});

export const {useLogInMutation, useChangePasswordMutation} = authApi;
