import React from "react";
import {Link} from "react-router-dom";
import styledCom from "styled-components";
import {SvgIconProps} from "@mui/material/SvgIcon";

const MenuItem = styledCom.div<{ $active: boolean }>(({ $active }) => ({
    display: "grid",
    gridTemplateColumns: "22px minmax(0, 1fr)",
    alignItems: "center",
    gap: "12px",
    minHeight: "46px",
    padding: "0 12px",
    borderRadius: "10px",
    color: $active ? "var(--color-primary)" : "var(--color-muted)",
    backgroundColor: $active ? "var(--color-primary-soft)" : "transparent",
    border: $active ? "1px solid var(--color-primary-border)" : "1px solid transparent",
    fontWeight: $active ? 700 : 550,
    boxShadow: $active ? "inset 3px 0 0 var(--color-primary)" : "none",
    transition:
        "background-color 160ms ease, border-color 160ms ease, color 160ms ease, transform 160ms ease",

    "&:hover": {
        color: $active ? "var(--color-primary)" : "var(--color-text)",
        backgroundColor: $active ? "var(--color-primary-soft)" : "var(--color-surface-soft)",
    },

    svg: {
        width: "20px",
        height: "20px",
    },
}));

const MenuText = styledCom.span({
    minWidth: 0,
    padding: "10px 0",
    overflowWrap: "anywhere",
    fontSize: "14px",
    lineHeight: 1.35,
});

interface SidebarNavLinkProps {
    to: string;
    icon: React.ElementType<SvgIconProps>;
    text: string;
    active: boolean;
}

const SidebarNavLink = ({to, icon, text, active}: SidebarNavLinkProps) => {
    const Icon = icon;

    return (
        <Link to={to} aria-label={text} aria-current={active ? "page" : undefined} style={{textDecoration: "none"}}>
            <MenuItem $active={active}>
                <Icon aria-hidden="true"/>
                <MenuText>{text}</MenuText>
            </MenuItem>
        </Link>
    );
};

export default SidebarNavLink;
