import IncomingCallBanner from "./components/operations/IncomingCallBanner";
import React, {lazy, Suspense, useEffect, useRef, useState} from "react";
import ChangePasswordPage from './auth/ChangePasswordPage';
import Header from "./components/layout/header/Header";
import Sidebar from "./components/layout/menu/sidebar/Sidebar";
import Accountbar from "./components/layout/menu/accountbar/Accountbar";
import {HashRouter, Navigate, Route, Routes, useLocation} from "react-router-dom";
import {ToastContainer} from "react-toastify";
import {ScrollToTop} from "./hooks/scrollToTop";
import {CategoryType} from "./models/category";
import {AuthProvider, useAuth} from "./auth/AuthContext";
import LoginPage from "./components/auth/LoginPage";
import {getActiveFirmId} from "./api/config";
import FirmSelectionPage from "./components/firms/FirmSelectionPage";
import {useGetFirmsQuery} from "./components/firms/firmsApi";
import WorkspaceSelectionPage, {Workspace, readWorkspace, saveWorkspace} from "./components/workspaces/WorkspaceSelectionPage";
import ModuleNavigation from "./components/workspaces/ModuleNavigation";
import {modules, moduleForPath} from "./components/workspaces/modules";
import {resetSessionState, useAppDispatch} from "./store/store";
import {closeNavigationPanels} from "./components/layout/menu/menuSlice";
import PageNavigation from "./components/layout/navigation/PageNavigation";
import Loader from "./ui/loader/loader";

const GoodsInvoicesPage = lazy(() => import("./components/transportWaybills/GoodsInvoicesPage"));
const CounterpartiesPage = lazy(() => import('./components/counterparties/CounterpartiesPage'));
const CostingPage = lazy(() => import("./components/costing/CostingPage"));
const ProcurementSourceList = lazy(() => import("./components/supplies/SuppliesPage"));
const ProcurementSourceDetail = lazy(() => import("./components/supplies/SupplyDetailPage"));
const CostingEditor = lazy(() => import("./components/costing/CostingEditor"));
const ServiceDetails = lazy(() => import("./components/services/ServiceDetails"));
const OrderPipelinePage = lazy(() => import("./components/operations/OrderPipelinePage"));
const TelephonyPage = lazy(() => import("./components/operations/TelephonyPage"));
const InvoiceApprovalPage = lazy(() => import("./components/warehouse/InvoiceApprovalPage"));
const MainPage = lazy(() => import("./components/mainPage/mainPage"));
const OrdersManagement = lazy(() => import("./components/orders/ordersManagement"));
const CustomersPage = lazy(() => import("./components/customers/CustomersPage"));
const CategoriesManagement = lazy(() => import("./components/categories/categoriesManagement"));
const Reports = lazy(() => import("./components/reports/reports"));
const ProductDetails = lazy(() => import("./components/products/productDetails"));
const ProductsManagement = lazy(() => import("./components/products/productsManagement"));
const CreateOrEditProduct = lazy(() => import("./components/products/createOrEditProduct"));
const OrderDetails = lazy(() => import("./components/orders/orderDetails"));
const CategoriesHierarchy = lazy(() => import("./components/categories/categoriesHierarchy"));
const CategoriesGraphTree = lazy(() => import("./components/categories/categoriesTree/categoriesGraphTree"));
const StockManagement = lazy(() => import("./components/stock/stockManagement"));
const CreateOrEditStatus = lazy(() => import("./components/shared/statuses/createOrEditStatus"));
const StatusesManagement = lazy(() => import("./components/shared/statuses/statusesManagement"));
const DeliveryMethodsManagement = lazy(() => import("./components/shared/deliveryMethod/deliveryMethodsManagement"));
const CreateOrEditDeliveryMethod = lazy(() => import("./components/shared/deliveryMethod/createOrEditDeliveryMethod"));
const PaymentMethodsManagement = lazy(() => import("./components/shared/paymentMethod/paymentMethodsManagement"));
const CreateOrEditPaymentMethod = lazy(() => import("./components/shared/paymentMethod/createOrEditPaymentMethod"));
const CreateOrEditSource = lazy(() => import("./components/shared/sources/createOrEditSource"));
const SourcesManagement = lazy(() => import("./components/shared/sources/sourcesManagement"));
const CreateOrder = lazy(() => import("./components/orders/createOrder/createOrder"));
const ServicesManagement = lazy(() => import("./components/services/servicesManagement"));
const CreateOrEditService = lazy(() => import("./components/services/createOrEditService"));
const DirectoriesManagement = lazy(() => import("./components/directories/directoriesManagement"));
const MenuSettingsManagement = lazy(() => import("./components/settings/menuSettingsManagement"));
const LogisticsManagement = lazy(() => import("./components/logistics/logisticsManagement"));
const TransportWaybillDetail = lazy(() => import("./components/transportWaybills/transportWaybillDetail"));
const UsersManagement = lazy(() => import("./components/users/usersManagement"));
const FirmsManagement = lazy(() => import("./components/firms/firmsManagement"));
const CatalogGenerationPage = lazy(() => import("./components/catalogGeneration/catalogGenerationPage"));
const CatalogGenerationBatchesPage = lazy(() => import("./components/catalogGeneration/catalogGenerationBatchesPage"));
const ProductFileGenerationPage = lazy(() => import("./components/catalogGeneration/productFileGenerationPage"));
const ProductFileReviewPage = lazy(() => import("./components/catalogGeneration/productFileReviewPage"));
const EpassPage = lazy(() => import("./components/catalogGeneration/epass/EpassPage"));
const ProductRecognitionPage = lazy(() => import("./components/catalogGeneration/recognition/ProductRecognitionPage"));
const StaffControlWorkspace = lazy(() => import("./components/workspaces/StaffControlWorkspace"));
const CommercialOffersPage = lazy(() => import("./components/commercialOffers/CommercialOffersPage"));
const CommercialOfferEditorPage = lazy(() => import("./components/commercialOffers/CommercialOfferEditorPage"));
const CommercialOfferTemplatesPage = lazy(() => import("./components/commercialOffers/CommercialOfferTemplatesPage"));
const CommercialOfferTemplateDesignerPage = lazy(() => import("./components/commercialOffers/CommercialOfferTemplateDesignerPage"));
const WarehouseReceiptsPage = lazy(() => import("./components/warehouse/WarehouseReceiptsPage"));
const InvoiceReceiptPage = lazy(() => import("./components/warehouse/InvoiceReceiptPage"));
const CollaborationPage = lazy(() => import("./components/collaboration/CollaborationPage"));
const StockAlertsPage = lazy(() => import("./components/warehouse/StockAlertsPage"));
const TelegramWebApp = lazy(() => import("./telegram/TelegramWebApp"));
const TelegramLinkPanel = lazy(() => import("./telegram/TelegramLinkPanel"));
const TelegramBrowserPage = lazy(() => import("./telegram/TelegramBrowserPage"));

const isTelegramLinkRoute = () => /^#\/telegram-link(?:\?|$)/.test(window.location.hash);
const readInitialWorkspace = (): Workspace | null => {
    const saved = readWorkspace();
    return moduleForPath(window.location.hash) ?? (isTelegramLinkRoute() && (!saved || saved === 'staff') ? 'orders' : saved);
};

function WorkspaceRouteSync({workspace, onChange}: {workspace: Workspace; onChange: (next: Workspace) => void}) {
    const location = useLocation();
    const previousPath = useRef(location.pathname);
    useEffect(() => {
        if (previousPath.current === location.pathname) return;
        previousPath.current = location.pathname;
        const next = moduleForPath(location.pathname);
        if (next && next !== workspace) onChange(next);
    }, [location.pathname, workspace, onChange]);
    return null;
}

function AppShell() {
    const dispatch = useAppDispatch();
    const {user, isCompanyAdmin, isSuperAdmin, signOut} = useAuth();
    const [workspace, setWorkspace] = useState<Workspace | null>(readInitialWorkspace);
    const {
        data: firms = [],
        isLoading: areFirmsLoading,
        isError: isFirmsError,
        refetch: refetchFirms,
    } = useGetFirmsQuery(undefined, {skip: !user || !isSuperAdmin || user.mustChangePassword});

    useEffect(() => {
        const initial = user ? readInitialWorkspace() : null;
        if (initial) saveWorkspace(initial);
        setWorkspace(initial);
    }, [user]);

    useEffect(() => {
        if (!user || user.mustChangePassword) return;
        const sync = () => {const next = isTelegramLinkRoute() ? readInitialWorkspace() : workspace ? moduleForPath(window.location.hash) : null; if (next && next !== workspace) {saveWorkspace(next); setWorkspace(next);}};
        sync(); window.addEventListener("hashchange", sync);
        return () => window.removeEventListener("hashchange", sync);
    }, [user, workspace]);

    if (!user) {
        return <LoginPage/>;
    }

    if (user.mustChangePassword) return <ChangePasswordPage/>;

    const activeFirmId = Number(getActiveFirmId());
    const hasSelectedFirm = Number.isInteger(activeFirmId) && activeFirmId > 0;
    const hasValidActiveFirm = firms.some(
        (firm) => firm.id === activeFirmId && !firm.isBlocked,
    );

    const shouldShowFirmSelection = isSuperAdmin && (
        !hasSelectedFirm ||
        (!areFirmsLoading && (isFirmsError || !hasValidActiveFirm))
    );

    if (shouldShowFirmSelection) {
        return (
            <FirmSelectionPage
                firms={firms}
                isLoading={areFirmsLoading}
                isError={isFirmsError}
                onRetry={() => { void refetchFirms(); }}
            />
        );
    }

    const activeFirm = firms.find((firm) => firm.id === activeFirmId);
    const selectWorkspace = (nextWorkspace: Workspace | null) => {
        if (nextWorkspace === workspace) return;
        dispatch(closeNavigationPanels({collapseSidebar: window.innerWidth <= 900}));
        saveWorkspace(nextWorkspace);
        if (nextWorkspace) window.location.hash = modules[nextWorkspace].path;
        setWorkspace(nextWorkspace);
    };

    if (!workspace) {
        return (
            <WorkspaceSelectionPage
                user={user}
                firmName={activeFirm?.name || user.firmName}
                onSelect={selectWorkspace}
                onSignOut={signOut}
            />
        );
    }

    if (workspace === "staff") {
        return (
            <div className="app-shell">
            <ModuleNavigation workspace={workspace} onSelect={selectWorkspace}/>
            <Suspense fallback={<Loader/>}>
            <StaffControlWorkspace
                user={user}
                onSignOut={signOut}
            />
            </Suspense>
            </div>
        );
    }

    return (
        <HashRouter future={{v7_startTransition: true, v7_relativeSplatPath: true}}>
            <div className="app-shell">
                <WorkspaceRouteSync workspace={workspace} onChange={next => {saveWorkspace(next); setWorkspace(next);}}/>
                <ScrollToTop/>
                <ModuleNavigation workspace={workspace} onSelect={selectWorkspace}/>
                <Header/>
                <div className="app-frame">
                    <Sidebar workspace={workspace}/>
                    <main className="app-main">
                        <Accountbar/>
                        <PageNavigation/>
                        <IncomingCallBanner/>
                    <Suspense fallback={<Loader/>}>
                    <Routes>
                        <Route path="/counterparties" element={<CounterpartiesPage/>}/>
                        <Route path="/telegram-link" element={<TelegramLinkPanel/>}/>
                        <Route
                            path="/"
                            element={
                                <Navigate replace to={modules[workspace].path}/>
                            }
                        />
                        <Route path="/mainPage" element={<MainPage/>}/>
                        <Route path="/reports" element={<Reports/>}/>
                        <Route path="/costing" element={<CostingPage/>}/>
                        <Route path="/costing/purchases" element={<ProcurementSourceList basePath="/costing/purchases"/>}/>
                        <Route path="/costing/purchases/:id" element={<ProcurementSourceDetail listPath="/costing/purchases"/>}/>
                        <Route path="/costing/new" element={<CostingEditor/>}/>
                        <Route path="/costing/:id" element={<CostingEditor/>}/>
                        <Route path="/servicesManagement/:id" element={<ServiceDetails/>}/>
                        <Route path="/commercialOffers" element={<CommercialOffersPage/>}/>
                        <Route path="/commercialOffers/new" element={<CommercialOfferEditorPage/>}/>
                        <Route path="/commercialOffers/:id" element={<CommercialOfferEditorPage/>}/>
                        <Route path="/commercialOffers/templates" element={<CommercialOfferTemplatesPage/>}/>
                        <Route path="/commercialOffers/templates/new" element={<CommercialOfferTemplateDesignerPage/>}/>
                        <Route path="/commercialOffers/templates/:templateId" element={<CommercialOfferTemplateDesignerPage/>}/>
                        <Route path="/ordersManagement" element={<OrdersManagement/>}/>
                        <Route path="/customers" element={<CustomersPage/>}/>
                        <Route path="/orderPipeline" element={<OrderPipelinePage/>}/>
                        <Route path="/telephony" element={<TelephonyPage/>}/>
                        <Route
                            path="/ordersManagement/createOrder"
                            element={<CreateOrder/>}
                        />
                        <Route
                            path="/ordersManagement/createOrder/categories"
                            element={<CategoriesHierarchy isOrder={true} categoryType={CategoryType.Product}/>}
                        />
                        <Route
                            path="/ordersManagement/createOrder/categories/:id"
                            element={<CategoriesHierarchy isOrder={true} categoryType={CategoryType.Product}/>}
                        />
                        <Route
                            path="/ordersManagement/editOrder/:orderId/categories"
                            element={<CategoriesHierarchy isOrder={true} categoryType={CategoryType.Product}/>}
                        />
                        <Route
                            path="/ordersManagement/editOrder/:orderId/categories/:id"
                            element={<CategoriesHierarchy isOrder={true} categoryType={CategoryType.Product}/>}
                        />
                        <Route
                            path="/ordersManagement/editOrder/:id"
                            element={<CreateOrder/>}
                        />
                        <Route path="/ordersManagement/:id" element={<OrderDetails/>}/>
                        <Route
                            path="/categoriesManagement"
                            element={<CategoriesManagement categoryType={CategoryType.Product} basePath="/categoriesManagement"/>}
                        />
                        <Route
                            path="/categoriesManagement/categoriesGraphTree"
                            element={<CategoriesGraphTree categoryType={CategoryType.Product}/>}
                        />
                        <Route
                            path="/categoriesManagement/hierarchy"
                            element={<CategoriesHierarchy isOrder={false} categoryType={CategoryType.Product} basePath="/categoriesManagement"/>}
                        />
                        <Route
                            path="/categoriesManagement/hierarchy/:id"
                            element={<CategoriesHierarchy isOrder={false} categoryType={CategoryType.Product} basePath="/categoriesManagement"/>}
                        />
                        <Route
                            path="/productCategories"
                            element={<CategoriesManagement categoryType={CategoryType.Product} basePath="/productCategories"/>}
                        />
                        <Route
                            path="/productCategories/categoriesGraphTree"
                            element={<CategoriesGraphTree categoryType={CategoryType.Product}/>}
                        />
                        <Route
                            path="/productCategories/hierarchy"
                            element={<CategoriesHierarchy isOrder={false} categoryType={CategoryType.Product} basePath="/productCategories"/>}
                        />
                        <Route
                            path="/productCategories/hierarchy/:id"
                            element={<CategoriesHierarchy isOrder={false} categoryType={CategoryType.Product} basePath="/productCategories"/>}
                        />
                        <Route
                            path="/serviceCategories"
                            element={<CategoriesManagement categoryType={CategoryType.Service} basePath="/serviceCategories"/>}
                        />
                        <Route
                            path="/serviceCategories/categoriesGraphTree"
                            element={<CategoriesGraphTree categoryType={CategoryType.Service}/>}
                        />
                        <Route
                            path="/serviceCategories/hierarchy"
                            element={<CategoriesHierarchy isOrder={false} categoryType={CategoryType.Service} basePath="/serviceCategories"/>}
                        />
                        <Route
                            path="/serviceCategories/hierarchy/:id"
                            element={<CategoriesHierarchy isOrder={false} categoryType={CategoryType.Service} basePath="/serviceCategories"/>}
                        />
                        <Route path="/categories" element={<CategoriesManagement categoryType={CategoryType.Product} basePath="/categoriesManagement"/>}/>
                        <Route
                            path="/categories/:categoryId"
                            element={<CategoriesManagement categoryType={CategoryType.Product} basePath="/categoriesManagement"/>}
                        />
                        <Route path="/productsManagement" element={<ProductsManagement/>}/>
                        <Route path="/catalogGeneration" element={<CatalogGenerationPage/>}/>
                        <Route path="/catalogGeneration/file" element={<ProductFileGenerationPage/>}/>
                        <Route path="/catalogGeneration/recognition" element={<ProductRecognitionPage/>}/>
                        <Route path="/catalogGeneration/file/review" element={<ProductFileReviewPage/>}/>
                        <Route path="/catalogGeneration/epass" element={<EpassPage/>}/>
                        <Route path="/catalogGeneration/lifecycle" element={<Navigate to="/catalogGeneration" replace/>}/>
                        <Route path="/catalogGeneration/batches" element={<CatalogGenerationBatchesPage/>}/>
                        <Route
                            path="/productDetails/:id"
                            element={<ProductDetails isOrder={true}/>}
                        />
                        <Route
                            path="/productsManagement/createProduct"
                            element={<CreateOrEditProduct/>}
                        />
                        <Route
                            path="/productsManagement/copyProduct/:id"
                            element={<CreateOrEditProduct isCopy={true}/>}
                        />
                        <Route
                            path="/productsManagement/editProduct/:id"
                            element={<CreateOrEditProduct/>}
                        />
                        <Route
                            path="/productsManagement/editProduct/productDetails/:id"
                            element={<ProductDetails isOrder={false}/>}
                        />
                        <Route path="/servicesManagement" element={<ServicesManagement/>}/>
                        <Route
                            path="/servicesManagement/createService"
                            element={<CreateOrEditService/>}
                        />
                        <Route
                            path="/servicesManagement/editService/:id"
                            element={<CreateOrEditService/>}
                        />
                        <Route path="/stockManagement" element={<StockManagement/>}/>
                        <Route path="/warehouseReceipts" element={<WarehouseReceiptsPage/>}/>
                        <Route path="/supplies" element={<Navigate to="/invoices" replace/>}/>
                        <Route path="/supplies/:id" element={<Navigate to="/invoices" replace/>}/>
                        <Route path="/warehouseReceipts/waybill/:id" element={<InvoiceApprovalPage/>}/>
                        <Route path="/stockAlerts" element={<StockAlertsPage/>}/>
                        <Route path="/collaboration" element={<CollaborationPage/>}/>
                        <Route path="/logistics" element={<LogisticsManagement/>}/>
                        <Route path="/invoices" element={<GoodsInvoicesPage/>}/>
                        <Route path="/invoices/:id" element={<TransportWaybillDetail goodsInvoice/>}/>
                        <Route path="/invoices/receipts/:receiptId" element={<InvoiceReceiptPage/>}/>
                        <Route path="/invoices/:id/approval" element={<InvoiceApprovalPage/>}/>
                        <Route path="/goodsInvoices" element={<GoodsInvoicesPage/>}/>
                        <Route path="/warehouseApprovals" element={<GoodsInvoicesPage approvals/>}/>
                        <Route path="/goodsInvoices/:id" element={<TransportWaybillDetail goodsInvoice/>}/>
                        <Route path="/goodsInvoices/:id/approval" element={<InvoiceApprovalPage/>}/>
                        <Route path="/transportWaybills" element={<GoodsInvoicesPage/>}/>
                        <Route path="/transportWaybills/:id" element={<TransportWaybillDetail goodsInvoice/>}/>
                        <Route path="/directories" element={<DirectoriesManagement/>}/>
                        <Route path="/settings" element={<MenuSettingsManagement/>}/>
                        {isCompanyAdmin && <Route path="/users" element={<UsersManagement/>}/>}
                        {isSuperAdmin && <Route path="/firms" element={<FirmsManagement/>}/>}
                        <Route path="/statuses" element={<StatusesManagement/>}/>
                        <Route
                            path="/statuses/createStatus"
                            element={<CreateOrEditStatus/>}
                        />
                        <Route
                            path="/statuses/editStatus/:id"
                            element={<CreateOrEditStatus/>}
                        />
                        <Route
                            path="/deliveryMethods"
                            element={<DeliveryMethodsManagement/>}
                        />
                        <Route
                            path="/deliveryMethods/createDeliveryMethod"
                            element={<CreateOrEditDeliveryMethod/>}
                        />
                        <Route
                            path="/deliveryMethods/editDeliveryMethod/:id"
                            element={<CreateOrEditDeliveryMethod/>}
                        />
                        <Route
                            path="/paymentMethods"
                            element={<PaymentMethodsManagement/>}
                        />
                        <Route
                            path="/paymentMethods/createPaymentMethod"
                            element={<CreateOrEditPaymentMethod/>}
                        />
                        <Route
                            path="/paymentMethods/editPaymentMethod/:id"
                            element={<CreateOrEditPaymentMethod/>}
                        />
                        <Route path="/sources" element={<SourcesManagement/>}/>
                        <Route
                            path="/sources/createSource"
                            element={<CreateOrEditSource/>}
                        />
                        <Route
                            path="/sources/editSource/:id"
                            element={<CreateOrEditSource/>}
                        />
                    </Routes>
                    </Suspense>
                    </main>
                </div>
            </div>
        </HashRouter>
    );
}

function App() {
    if (new URLSearchParams(window.location.search).get('telegramWebApp') === '1' || window.location.hash.split('?')[0] === '#/telegram') {
        return <Suspense fallback={<Loader/>}><TelegramWebApp/></Suspense>;
    }
    return (
        <AuthProvider onSessionEnd={resetSessionState}>
            <ToastContainer position="top-right" autoClose={3200} newestOnTop/>
            {new URLSearchParams(window.location.search).get('telegramPreview') === '1'
                ? <Suspense fallback={<Loader/>}><TelegramBrowserPage/></Suspense>
                : <AppShell/>}
        </AuthProvider>
    );
}

export default App;
