import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
export type StockLookup = {productId: number; gtin: string; name: string; currentStock: number};
export type ReceiptLine = {productId: number; gtin: string; productName: string; quantity: number; stockBefore: number; stockAfter: number};
export type Receipt = {id: string; createdAt: string; createdByUserId: number; comment: string; lines: ReceiptLine[]; transportWaybillId?: number | null; sourceDocumentKind?: number | null; sourceDocumentNumber?: string | null; isArchived?: boolean};
export type ReceiptPricingTerms = {currency: string; fxRate: number | null; fxDate: string | null; fxSource: string; warehouse: string};
export type ReceiveStock = {requestId: string; lines: {gtin: string; quantity: number; sourceLineId?: number; productId?: number; baseUnit?: string; unitsPerPurchaseUnit?: number}[]; comment: string; transportWaybillId?: number; excludedSourceLineIds?: number[]; pricing?: ReceiptPricingTerms};
export type WaybillReceiptPreparation = {id: number; number: string | null; date: string | null; receiptId: string | null; lines: {id: number; rowNumber: number; name: string | null; gtin: string | null; unitName: string | null; quantity: number | null; suggestedProduct: StockLookup | null}[]};
export const warehouseReceiptsApi = createApi({
    ...liveServerDataApiOptions, reducerPath: "warehouseReceiptsApi", baseQuery: createFirmBaseQuery("warehouse/receipts"), tagTypes: ["Receipts"],
    endpoints: builder => ({
        lookupStock: builder.query<StockLookup, string>({query: gtin => ({url: "lookup", params: {gtin}}), providesTags: ["Receipts"]}),
        searchStock: builder.query<StockLookup[], string>({query: query => ({url: "search", params: {query}}), providesTags: ["Receipts"]}),
        waybillReceiptPreparation: builder.query<WaybillReceiptPreparation, number>({query: id => `waybill/${id}`, providesTags: ["Receipts"]}),
        receiptHistory: builder.query<Receipt[], number | {page: number; archived: boolean}>({query: params => ({url: "", params: typeof params === "number" ? {page: params} : params}), providesTags: ["Receipts"]}),
        receipt: builder.query<Receipt, string>({query: id => id, providesTags: ["Receipts"]}),
        receiveStock: builder.mutation<Receipt, ReceiveStock>({query: body => ({url: "", method: "POST", body}), invalidatesTags: ["Receipts"]}),
        archiveReceipt: builder.mutation<void, string>({query: id => ({url: id, method: "DELETE"}), invalidatesTags: ["Receipts"]}),
        restoreReceipt: builder.mutation<void, string>({query: id => ({url: `${id}/restore`, method: "POST"}), invalidatesTags: ["Receipts"]}),
        deleteArchivedReceipt: builder.mutation<{deletedCount: number}, string>({query: id => ({url: `${id}/archive`, method: "DELETE"}), invalidatesTags: ["Receipts"]}),
        clearReceiptArchive: builder.mutation<{deletedCount: number}, void>({query: () => ({url: "archive", method: "DELETE"}), invalidatesTags: ["Receipts"]}),
    }),
});
export const {useLazyLookupStockQuery, useSearchStockQuery, useWaybillReceiptPreparationQuery, useReceiptHistoryQuery, useReceiveStockMutation, useReceiptQuery, useLazyReceiptQuery, useArchiveReceiptMutation, useRestoreReceiptMutation, useDeleteArchivedReceiptMutation, useClearReceiptArchiveMutation} = warehouseReceiptsApi;
