import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {Calculation, CatalogItem, Comparison, CostInput, CostResult, CostSummary, Resource} from "./types";
export type CreateCalculationBody = {itemType: number; itemId: number; name: string; notes: string; kind: number; baselineId: string | null; input: CostInput};
export const costingApi = createApi({
    ...liveServerDataApiOptions, reducerPath: "costingApi", baseQuery: createFirmBaseQuery("costing"), tagTypes: ["Costing", "Resources"],
    endpoints: b => ({
        costingList: b.query<{items: Calculation[]; total: number; page: number; pageSize: number}, {page?: number; search?: string; itemType?: number; itemId?: number; status?: number; kind?: number}>({query: params => ({url: "calculations", params}), providesTags: ["Costing"]}),
        costingCalculation: b.query<Calculation, string>({query: id => `calculations/${id}`, providesTags: ["Costing"]}),
        costingCatalog: b.query<CatalogItem[], string>({query: query => ({url: "catalog/search", params: {query}}), providesTags: ["Costing"]}),
        catalogCost: b.query<CostSummary, {itemType: number; itemId: number}>({query: p => `catalog/${p.itemType}/${p.itemId}`, providesTags: ["Costing"]}),
        costingDashboard: b.query<{approvedCount: number; belowCostCount: number; missingSellingPriceCount: number; items: CostSummary[]}, void>({query: () => "dashboard", providesTags: ["Costing"]}),
        costResources: b.query<Resource[], void>({query: () => "resources", providesTags: ["Resources"]}),
        costComparison: b.query<Comparison, {plannedId: string; actualId: string}>({query: params => ({url: "compare", params}), providesTags: ["Costing"]}),
        previewCost: b.mutation<CostResult, {itemType: number; itemId: number; input: CostInput}>({query: body => ({url: "preview", method: "POST", body})}),
        createCost: b.mutation<Calculation, CreateCalculationBody>({query: body => ({url: "calculations", method: "POST", body}), invalidatesTags: ["Costing"]}),
        saveCost: b.mutation<Calculation, {id: string; name: string; notes: string; input: CostInput; stamp: string}>({query: ({id, ...body}) => ({url: `calculations/${id}`, method: "PUT", body}), invalidatesTags: ["Costing"]}),
        approveCost: b.mutation<Calculation, {id: string; stamp: string}>({query: ({id, stamp}) => ({url: `calculations/${id}/approve`, method: "POST", body: {stamp}}), invalidatesTags: ["Costing"]}),
        archiveCost: b.mutation<Calculation, {id: string; stamp: string}>({query: ({id, stamp}) => ({url: `calculations/${id}/archive`, method: "POST", body: {stamp}}), invalidatesTags: ["Costing"]}),
        cloneCost: b.mutation<Calculation, {id: string; kind: number}>({query: ({id, kind}) => ({url: `calculations/${id}/clone`, method: "POST", body: {kind}}), invalidatesTags: ["Costing"]}),
        saveCostResource: b.mutation<Resource, Partial<Resource> & {name: string; unit: string; currency: string; category: number; unitCost: number; notes: string; stamp: string}>({query: ({id, ...body}) => ({url: id ? `resources/${id}` : "resources", method: id ? "PUT" : "POST", body}), invalidatesTags: ["Resources"]}),
        archiveCostResource: b.mutation<{archived: boolean}, {id: string; stamp: string}>({query: ({id, stamp}) => ({url: `resources/${id}/archive`, method: "POST", body: {stamp}}), invalidatesTags: ["Resources"]}),
        exportCost: b.query<Blob, string>({query: id => ({url: `calculations/${id}/export`, responseHandler: response => response.blob()})}),
    }),
});
export const {useCostingListQuery, useCostingCalculationQuery, useCostingCatalogQuery, useCatalogCostQuery, useCostingDashboardQuery, useCostResourcesQuery, useCostComparisonQuery, usePreviewCostMutation, useCreateCostMutation, useSaveCostMutation, useApproveCostMutation, useArchiveCostMutation, useCloneCostMutation, useSaveCostResourceMutation, useArchiveCostResourceMutation, useLazyExportCostQuery} = costingApi;
