const trimSlashes = (value: string) => value.replace(/^\/+|\/+$/g, "");

const DEFAULT_API_BASE_URL = process.env.NODE_ENV === "production"
    ? "https://vivotech1-001-site1.htempurl.com/api"
    : "https://localhost:7239/api";

export const API_BASE_URL = (
    process.env.REACT_APP_API_BASE_URL || DEFAULT_API_BASE_URL
).replace(/\/+$/g, "");

export const STAFF_CONTROL_API_BASE_URL = (
    process.env.REACT_APP_STAFF_CONTROL_API_BASE_URL ||
    `${API_BASE_URL.replace(/\/api$/i, "")}/staff-control`
).replace(/\/+$/g, "");

const ACTIVE_FIRM_STORAGE_KEY = "activeFirmId";

export const getAccessToken = (): string | null => {
    if (typeof window === "undefined") {
        return null;
    }

    return (
        window.localStorage.getItem("accessToken") ||
        window.localStorage.getItem("token")
    );
};

export const getActiveFirmId = (): string => {
    if (typeof window === "undefined") {
        return "";
    }

    const value = window.sessionStorage.getItem(ACTIVE_FIRM_STORAGE_KEY) || "";
    const firmId = Number(value);

    return Number.isInteger(firmId) && firmId > 0 ? String(firmId) : "";
};

export const setActiveFirmId = (firmId: number) => {
    if (!Number.isInteger(firmId) || firmId <= 0) {
        throw new Error("A valid company must be selected.");
    }

    window.sessionStorage.setItem(ACTIVE_FIRM_STORAGE_KEY, String(firmId));
    window.localStorage.removeItem(ACTIVE_FIRM_STORAGE_KEY);
};

export const clearActiveFirmId = () => {
    window.sessionStorage.removeItem(ACTIVE_FIRM_STORAGE_KEY);
    window.localStorage.removeItem(ACTIVE_FIRM_STORAGE_KEY);
};

export const firmApiUrl = (path = "") => {
    const normalizedPath = trimSlashes(path);
    const base = `${API_BASE_URL}/firms/${getActiveFirmId()}`;

    return normalizedPath ? `${base}/${normalizedPath}` : base;
};
