import {createApi} from "@reduxjs/toolkit/query/react";
import {createFirmBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";
import {AnalyticsParams, SalesAnalytics} from "../../models/analytics";

export const analyticsApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "analytics",
    tagTypes: ["Analytics"],
    baseQuery: createFirmBaseQuery("analytics"),
    endpoints: (builder) => ({
        getSalesAnalytics: builder.query<SalesAnalytics, AnalyticsParams | void>({
            query: (analyticsParams) => ({
                url: "sales",
                method: "GET",
                params: analyticsParams || undefined,
            }),
            providesTags: ["Analytics"],
        }),
        exportSalesAnalyticsCsv: builder.query<Blob, AnalyticsParams | void>({
            query: (analyticsParams) => ({
                url: "sales/export.csv",
                method: "GET",
                params: analyticsParams || undefined,
                responseHandler: (response) => response.blob(),
            }),
        }),
    }),
});

export const {
    useExportSalesAnalyticsCsvQuery,
    useGetSalesAnalyticsQuery,
    useLazyExportSalesAnalyticsCsvQuery,
    useLazyGetSalesAnalyticsQuery,
} = analyticsApi;
