import {createSlice, PayloadAction} from "@reduxjs/toolkit";
import {OrderParams} from "../../models/order";

interface OrderUiState {
    orderParams: OrderParams;
}

const initialState: OrderUiState = {
    orderParams: {
        orderBy: "dateDesc",
        pageNumber: 1,
        pageSize: 25,
        orderStatuses: [],
        searchTerm: "",
    },
};

export const orderSlice = createSlice({
    name: "order",
    initialState,
    reducers: {
        setOrderParams: (state, action: PayloadAction<Partial<OrderParams>>) => {
            state.orderParams = {
                ...state.orderParams,
                ...action.payload,
                pageNumber: 1,
            };
        },
        setPageNumber: (state, action: PayloadAction<number>) => {
            state.orderParams.pageNumber = action.payload;
        },
    },
});

export const {setOrderParams, setPageNumber} = orderSlice.actions;
