import {createApi} from "@reduxjs/toolkit/query/react";
import {createApiBaseQuery, liveServerDataApiOptions} from "../../api/baseQuery";

export interface TestDataStatus {
    hasTestData: boolean;
    trackedRecordCount: number;
    legacySeedDetected: boolean;
}

export interface TestDataOperationResult {
    status: TestDataStatus;
    addedRecordCount: number;
    removedRecordCount: number;
    preservedRecordCount: number;
}

export const testDataApi = createApi({
    ...liveServerDataApiOptions,
    reducerPath: "testDataApi",
    tagTypes: ["TestData"],
    baseQuery: createApiBaseQuery(),
    endpoints: (builder) => ({
        getTestDataStatus: builder.query<TestDataStatus, void>({
            query: () => "/test-data",
            providesTags: ["TestData"],
        }),
        seedTestData: builder.mutation<TestDataOperationResult, void>({
            query: () => ({url: "/test-data", method: "POST"}),
            invalidatesTags: ["TestData"],
        }),
        clearTestData: builder.mutation<TestDataOperationResult, void>({
            query: () => ({url: "/test-data", method: "DELETE"}),
            invalidatesTags: ["TestData"],
        }),
    }),
});

export const {
    useGetTestDataStatusQuery,
    useSeedTestDataMutation,
    useClearTestDataMutation,
} = testDataApi;
