import React, {createContext, useCallback, useContext, useEffect, useMemo, useState} from "react";
import {flushSync} from "react-dom";
import {AuthUser, LoginResponse} from "../models/auth";
import {clearActiveFirmId, setActiveFirmId} from "../api/config";

const SESSION_STORAGE_KEY = "authUser";
const WORKSPACE_STORAGE_KEY = "vivotech.activeWorkspace";
const ROLE_CLAIM = "http://schemas.microsoft.com/ws/2008/06/identity/claims/role";

const clearStoredSession = () => {
    for (const key of ['accessToken', 'token', SESSION_STORAGE_KEY]) window.localStorage.removeItem(key);
    window.sessionStorage.removeItem(WORKSPACE_STORAGE_KEY);
    clearActiveFirmId();
};

const getTokenRole = (payload: Record<string, unknown>): AuthUser["role"] | undefined => {
    const value = payload.role ?? payload[ROLE_CLAIM];
    const role = Array.isArray(value) ? value[0] : value;

    return role === "employee" || role === "company_admin" || role === "super_admin"
        ? role
        : undefined;
};

interface AuthContextValue {
    user: AuthUser | null;
    isCompanyAdmin: boolean;
    isSuperAdmin: boolean;
    signIn: (response: LoginResponse) => void;
    signOut: () => void;
    switchFirm: (firmId: number) => void;
    updateFirmName: (firmName: string) => void;
}

const AuthContext = createContext<AuthContextValue | null>(null);

const getTokenFirmId = (payload: Record<string, unknown>): number | null => {
    const value = payload.FirmId ?? payload.firmId;
    const firmId = Number(value);

    return Number.isInteger(firmId) && firmId > 0 ? firmId : null;
};

const synchronizeFirmContext = (user: AuthUser) => {
    if (user.role === "super_admin") {
        return;
    }

    if (user.firmId === null) {
        clearActiveFirmId();
        window.sessionStorage.removeItem(WORKSPACE_STORAGE_KEY);
        return;
    }

    setActiveFirmId(user.firmId);
};

const readStoredUser = (): AuthUser | null => {
    const token = window.localStorage.getItem("accessToken");
    const serializedUser = window.localStorage.getItem(SESSION_STORAGE_KEY);
    if (!token || !serializedUser) {
        clearStoredSession();
        return null;
    }

    try {
        const [, payload] = token.split(".");
        const normalizedPayload = payload.replace(/-/g, "+").replace(/_/g, "/");
        const paddedPayload = normalizedPayload.padEnd(Math.ceil(normalizedPayload.length / 4) * 4, "=");
        const decodedPayload = JSON.parse(atob(paddedPayload)) as Record<string, unknown>;
        const expiresAt = typeof decodedPayload.exp === "number"
            ? decodedPayload.exp * 1000
            : null;
        if (!expiresAt || !Number.isFinite(expiresAt) || expiresAt <= Date.now()) {
            clearStoredSession();
            return null;
        }

        const storedUser = JSON.parse(serializedUser) as AuthUser;
        const role = getTokenRole(decodedPayload);
        const tokenFirmId = getTokenFirmId(decodedPayload);
        if (!role || (role !== 'super_admin' && !tokenFirmId)) {
            clearStoredSession();
            return null;
        }
        const restoredUser = {
            ...storedUser,
            role,
            firmId: role === "super_admin" ? null : tokenFirmId,
            firmName: role === "super_admin" ? "" : storedUser.firmName,
            mustChangePassword: decodedPayload.password_reset_required === 'true',
        };

        if (role !== storedUser.role || restoredUser.firmId !== storedUser.firmId || restoredUser.firmName !== storedUser.firmName) {
            window.localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(restoredUser));
        }

        synchronizeFirmContext(restoredUser);
        return restoredUser;
    } catch {
        clearStoredSession();
        return null;
    }
};

export const AuthProvider = ({children, onSessionEnd}: {children: React.ReactNode; onSessionEnd?: () => void}) => {
    const [user, setUser] = useState<AuthUser | null>(() => readStoredUser());

    const signOut = useCallback(() => {
        // Unmount authenticated screens before clearing their company context or
        // query data. Otherwise a synchronous store update can briefly render a
        // global administrator without a company and open the company picker.
        flushSync(() => setUser(null));
        clearStoredSession();
        onSessionEnd?.();
    }, [onSessionEnd]);

    useEffect(() => {
        window.addEventListener("vivotech:unauthorized", signOut);
        return () => window.removeEventListener("vivotech:unauthorized", signOut);
    }, [signOut]);

    const value = useMemo<AuthContextValue>(() => ({
        user,
        isCompanyAdmin: user?.role === "company_admin" || user?.role === "super_admin",
        isSuperAdmin: user?.role === "super_admin",
        signIn: (response) => {
            const account = response.user.role === "super_admin" ? {...response.user, firmId: null, firmName: ""} : response.user;
            window.sessionStorage.removeItem(WORKSPACE_STORAGE_KEY);
            window.localStorage.setItem("accessToken", response.token);
            window.localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(account));
            if (account.firmId === null) {
                clearActiveFirmId();
            } else {
                synchronizeFirmContext(account);
            }
            setUser(account);
        },
        signOut,
        switchFirm: (firmId) => {
            setActiveFirmId(firmId);
            window.location.hash = "/ordersManagement";
            window.location.reload();
        },
        updateFirmName: (firmName) => {
            setUser((currentUser) => {
                if (!currentUser) {
                    return null;
                }

                const updatedUser = {...currentUser, firmName: currentUser.role === "super_admin" ? "" : firmName};
                window.localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(updatedUser));
                return updatedUser;
            });
        },
    }), [user, signOut]);

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (!context) {
        throw new Error("useAuth must be used inside AuthProvider");
    }

    return context;
};
